window.__D("text/likkutei-sichot/c002",{"p":[[1301410220,"א) גזירת הטומאה חלה על החפצא<sup data-n=\"1306\">16</sup> של הדבר הנעבד, ובאה בהמשך לאיסור ע\"ז (של תורה), דכשם שהתורה אסרה דבר הנעבד בהנאה כו' והוי חפצא ד­איסורא, ככה הוסיפו חכמים לגזור ש­יחול שם טומאה על הדבר הנעבד.\nב) גזירת הטומאה אינה קשורה עם חלות איסור הע\"ז (מן התורה) ואינה אלא מצד הגברא<sup data-n=\"1306\">16</sup>, כדי להרחיק ולהפריש את האדם מעבודה זרה.\nואע\"פ שטומאת ע\"ז יש בה ארבע אבות הטומאה שמטמאים גם כלים, דמזה מוכח שהגזירה דטומאת ע\"ז היא באופן שיש חלות טומאה על החפצא דהדבר הנעבד (ולא רק חלות טומאה על ה­גברא, הנוגע בע\"ז) — י\"ל שזה גופא אינה אלא מצד (הרחקת) הגברא, כי חומרא זו גופא מוסיפה בהרחקת האדם ממנה.\nויש לומר, שזהו טעמו של הרמב\"ם שכ' (א) שטומאת ע\"ז \"יש לה רמז בתו­רה\", (ב) ובזה גופא מביא הרמז דוקא מן הכתוב \"הסירו את אלקי הנכר גו'\", ולא הסתפק בהרמז \"שקץ תשקצנו\" (או \"תזרם כמו דוה\") שמביאו אח\"כ:\nהחילוק בין הדרשות שבש\"ס (שע\"ז מטמאה כשרץ וכנדה כו') והרמז מן ה­כתוב \"הסירו גו'\" הוא: בדרשות הנ\"ל מודגש מיאוס החפצא של ע\"ז (שהיא משוקצת כשרץ, או טמאה כנדה), משא\"כ בכתוב \"הסירו את אלקי הנכר אשר בתוככם והטהרו והחליפו שמלותיכם\" מדובר על מעשה הסרת הע\"ז מקרבם. ומש\"ה מקדים הרמב\"ם שהיסוד לטומאת ע\"ז הוא ה\"רמז בתורה הסירו גו'\", שבזה משמיענו, שענינה של טומאה זו הוא (לא מצד החפצא דע\"ז, אלא) מצד הגברא, כדי להפרישו ולהרחיקו ממנה — \"הסירו את אלקי הנכר גו'\"<sup data-n=\"1308\">17</sup>, אלא שכדי שתהי' הרחקה זו בשלימות גזרו שתהא מטמאה כשרץ וכנדה כו'.\nכלומר: אם לא הי' הרמב\"ם מקדים רמז זה, הרי מהדרשות שבהלכות של­אח\"ז הי' משתמע שטומאת ע\"ז היא מצד החפצא של הדבר הנעבד, שהוא משוקץ כשרץ וכו'. ולכן הוזקק להקדים שה­\"רמז בתורה\" על תוכנה הכללי של גזי­רת טומאת ע\"ז הוא מן הכתוב ד\"הסירו את אלקי הנכר גו'\" (המדגיש שענינה הוא הסרת ע\"ז מגבול ישראל), ומשאר הכתובים למדים רק פרטי ההלכות של טומאת ע\"ז (שאיתקש לשרץ, נדה ומת).\nג. ויש לבאר הטעם שהרמב\"ם נקט כאופן הב' הנ\"ל, שתוכן טומאת ע\"ז היא רק גזירה להרחיק את האדם מע\"ז (ולא מצד החפצא דע\"ז, כמו איסור ע\"ז שמן התורה) — ובהקדם:\nא) שונה איסור ע\"ז משאר איסורי הנאה, שכל איסורי התורה הם דבר שב­מציאות, משא\"כ ע\"ז אין לה ממש. דאף שהדבר הנעבד יש לו מציאות, מ\"מ זה שדבר זה הוא מציאות של עבודה זרה — הוא רק דמיונו של העובד ע\"ז, שבדמ­יונו הכוזב אומר \"לעץ אבי אתה ולאבן את ילידתני\"<sup data-n=\"1309\">18</sup>, אבל באמת הרי הוא \"שקר. . הבל ואין בם מועיל\"<sup data-n=\"1310\">19</sup>, ואינם",[["1306","16","להעיר מהשקו\"ט בבית האוצר (להר\"י ענגל) מערכת האל\"ף כלל קכד, \"לפי צד הסברא דאיסורים דרבנן רק איסור גברא המה אי אמרינן כן גם בטומאה דרבנן\". ע\"ש."],["1306","16","להעיר מהשקו\"ט בבית האוצר (להר\"י ענגל) מערכת האל\"ף כלל קכד, \"לפי צד הסברא דאיסורים דרבנן רק איסור גברא המה אי אמרינן כן גם בטומאה דרבנן\". ע\"ש."],["1308","17","וראה מפרשים עה\"פ, ש\"הסירו גו'\" הי' רק לשם הרחקה יתירה כי כבר נתבטלה הע\"ז לפנ\"ז. ע\"ש."],["1309","18","כלשון הכתוב ירמי' ב, כז."],["1310","19","ל' הכתוב ירמי' טז, יט. וראה ע\"ז נד, ב ואילך. ובכ\"מ."]]],[1301410221,"אלא עץ ואבן בעלמא<sup data-n=\"1311\">20</sup>. משא\"כ בשאר איסורים, שגם שם האיסור (ולא רק הדבר הנאסר) הוא דבר שיש לו ממש (ע\"פ תורה), כמו שור הנסקל, חמץ בפסח, וכן באיסורי אכילה כמו נבילה וטריפה כו' — שבכולם היותם מציאות אסורה באה מדבר שבמציאות.\nולכן מצינו שיש דין מיוחד בע\"ז, שאסור לעשות שום דבר שמחשיב אותה ונותן בה ממשות<sup data-n=\"1312\">21</sup>.\nב) אינו דומה חלות איסור הנאה לענין הטומאה, כי איסור הוא רק ענין שלילי, המבטל חשיבותו של הדבר (ש­א\"א ליהנות ממנו, ועד שאבד כל שוויותו); משא\"כ חלות \"טומאה\" יש בכללה שהרע והתיעוב שבדבר הנעבד יש לו ממש עד שבכחו לפעול באדם, שהנוגע בו נטמא, ובגלל זה נאסר עליו להכנס למקדש ולאכול בקדשים.\nומש\"ה ס\"ל להרמב\"ם שגזירת טומאת ע\"ז אינה מצד החפצא של ע\"ז, שאז הי' נראה שיש באיסור ע\"ז איזה ממש (שה­דבר הנעבד יש בו טומאה עצמית הגו­רמת טומאה באדם הנוגע בה<sup data-n=\"1313\">22</sup>) — אלא כולה היא רק מצד הגברא העובד ע\"ז, כנ\"ל.\nד. ויש לומר — ע\"ד הרמז עכ\"פ — שמדברי הרמב\"ם הללו (שמביא \"רמז בתורה\" מכתוב זה (ד\"הסירו גו'\") על טומאת ע\"ז), יש ללמוד ביאור כללי בענין ע\"ז.\nדהנה לכאורה יש מקום לשאלה — כיצד יתכן שבעולמו של הקב\"ה תהי' מציאות של ע\"ז שהיא שלילת אחדותו ית'? וע\"ד השאלה ששאלו את הזקנים \"אם אין רצונו בעבודת כוכבים למה אינו מבטלה\"<sup data-n=\"1314\">23</sup>.\nואע\"פ שענו ש\"הרי הן עובדין לחמה וללבנה ולכוכבים ולמזלות, יאבד עולמו מפני השוטים (בתמי')\"<sup data-n=\"1314\">23</sup> [וגם ענו על טענתם ש\"יאבד (רק) דבר שאין צורך ל­עולם בו ויניח דבר שצורך העולם בו\"<sup data-n=\"1314\">23</sup>] — מ\"מ עדיין אינו מחוור: כיצד מניח הקב\"ה שתהי' קס\"ד במחשבתו של אדם שיש מציאות של ע\"ז בעולם עד שיש צורך לאבדה (דפשיטא שאם רצון ה­בורא הי' שלא תהי' מציאות של ע\"ז בעולמו — לא הי' שייך שבן אדם ידמה בעיניו לעבוד ע\"ז)?\nוהתירוץ על זה מרומז במ\"ש הרמב\"ם שהמקור לדין טומאת ע\"ז היא במ\"ש \"הסירו את אלקי הנכר גו'\", כלומר: זה שישנה אפשרות למציאות של ע\"ז בעו­לם הוא רק כדי שענין זה גופא — שאין שום מקום למציאות של ע\"ז — יבוא (לא בתור דבר טבעי, אלא) ע\"י מעשה בנ\"י, להסיר את אלקי הנכר; דכיון ש\"למעשה ידיך תכסוף\"<sup data-n=\"1317\">24</sup>, שהקב\"ה רוצה שעניני קדושה יבואו ויתגלו על ידי עבודת ישראל, לכן גם בענין האמונה בהשם כן הוא, שרצונו ית' הוא שבנ\"י (בכחם הם) יגלו אמונה זו בעולם<sup data-n=\"1318\">25</sup>. ולכן ברא",[["1311","20","וגם השמש והירח כו' הם רק כגרזן ביד ה­חוצב בו ואין להם שום שליטה כו' (ראה פיהמ\"ש להרמב\"ם בהקדמה לפ' חלק היסוד החמישי. סהמ\"צ להצ\"צ מצות מילה ח\"א פ\"ג. ובכ\"מ)."],["1312","21","ראה דרישה לטור יו\"ד סקמ\"ז \"משום דנותן בה ממשות\". ועד\"ז בט\"ז יו\"ד שם סוסק\"א. ולהעיר ממנ\"ח (מצוה פו) דהא דלוקין רק בנודר ומקיים כי זו הזכרה שהיא כבוד להע\"ז ולכן הוא לאו גמור."],["1313","22","להעיר ממשנ\"ת במ\"א (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181175\" data-slug=\"likkutei-sichot\" data-id=\"1300181175\">לקו\"ש חי\"ח ע' 166</a>) בפירוש דברי הראב\"ד (הל' אבות הטומאה פ\"ב ה\"י) ש\"עכו\"ם הם כבהמות ואין מטמאין ואין מיטמאין\". ע\"ש."],["1314","23","משנה וברייתא ע\"ז נד, ב."],["1314","23","משנה וברייתא ע\"ז נד, ב."],["1314","23","משנה וברייתא ע\"ז נד, ב."],["1317","24","איוב יד, טו."],["1318","25","וי\"ל שזהו הרמז בזה שה\"רמז בתורה\" הוא מכתוב (דפרשתנו) שלפני הדיבור — שזה מדגיש עוד יותר הענין דעבודת האדם (בהסרת וביטול ע\"ז) בכח עצמו, גם בלי הנתינת כח מהדיבור דמ\"ת."]]],[1301410222,"הקב\"ה עולמו באופן כזה שתתכן מצי­אות של ע\"ז, ע\"ד כתוב והרוצה לטעות יטעה<sup data-n=\"1319\">26</sup>, כדי שבנ\"י יצטרכו לגלות את השקר שבע\"ז ואיך שאין בה ממש, שעי\"ז מבטלים את ענין הע\"ז ומגלים את ה­אמונה האמיתית בהשם אחד.\nה. והנה ידועים דברי רבינו הזקן ב­ספר התניא<sup data-n=\"1320\">27</sup>, שכל מעשה עבירה הוא בדקות ענין של עבודה זרה.\nכי האמונה האמיתית באחדותו ית' היא<sup data-n=\"1321\">28</sup> לא (רק) שאין עוד אלוקה מלבדו, ח\"ו, אלא שאין עוד שום מציאות בלעדו ית', כי אמיתית המציאות של כל נברא הוא רק ה\"דבר השם\" המחייהו ומהווהו מאין ליש תמיד; ולכן, כל המחשיב עצמו \"ליש ודבר בפני עצמו\" (כי אינו מרגיש שאין לו שום מציאות בלעדו ית') ה\"ז (בדקות) ענין של עבודה זרה ו\"כפירה באחדותו האמתית\"<sup data-n=\"1322\">29</sup>.\nונמצא, שעשיית עבירה (איזו שהיא), שבזה מחשיב עצמו ליש ודבר נפרד ממנו ית', ה\"ז (בדקות) גם כפירה באח­דותו ית' האמיתית (שאין עוד מלבדו).\nוכן הוא בנוגע להדברים האסורים עצמם, דכיון שהם נותנים אפשרות ל­מעשה העבירה של האדם שהיא כפירה באחדותו האמיתית, נמצא, שהם מנגדים ל\"אחדותו האמיתית\"<sup data-n=\"1323\">30</sup>.\nומזה מובן, דכשם שנת\"ל בנוגע ל­מציאות של ע\"ז בפשטות, שבאמת אין לה שום ממש ומציאות ואינה אלא דמיון של העובד, ועוד זאת, שהכוונה בזה גופא (שיש אפשרות שיהי' דמיון כזה במחשבת העובד) היא רק כדי שתהי' פעולת בנ\"י להסיר אותה, \"הסירו את אלקי הנכר גו'\" — כן הוא (בדקות) בכל הדברים האסורים, דזה שהם חפצא דאי­סורא, הנותנת אפשרות להאדם לכפור באחדותו האמיתית, אינו ענין עצמי בה­חפצא, אלא רק בשביל עבודת בנ\"י, כד­לקמן.\nו. והענין מובן ע\"פ המבואר בתניא<sup data-n=\"1324\">31</sup>, שהאפשרות למציאות של יש ודבר נפרד מאחדותו ית' היא רק מחמת ההסתר פנים, המכסה ומעלים על הכח האלקי שבנבראים (המהווה אותם תמיד מאין ליש); אמנם הסתר זה הוא רק לגבי ה­נבראים, שכלפם יש להסתר זה מציאות, וגורם שיהי' נדמה אצלם שיש איזו מציאות בלעדו ית', אבל לגבי הקב\"ה אין שום דבר מסתיר ומעלים לפניו, ואין שום דבר נפרד ממנו ית'<sup data-n=\"1325\">32</sup>, ולכן \"כל<sup data-n=\"1326\">33</sup> מאמינים שהוא לבדו הוא כמו שהי' קודם שנברא העולם ממש. . בלי שום שינוי\".\nולכאורה צריך ביאור: כיון שהאמת הגמורה היא שאין לשום דבר בעולם מציאות בלעדו ית' (ומה שלא נראה כן לעינים הוא רק מחמת ההסתר פנים ה­מכסה על האמת) — מדוע יש תוקף בדיני התורה (שהיא תורת השם ותורת אמת) למציאותם של הדברים ההם בתור דברים נפרדים מאחדותו ית', עד שנע­שים",[["1319","26","ב\"ר פ\"ח, ח."],["1320","27","ח\"א פ\"כ ואילך."],["1321","28","ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310060\" data-slug=\"tanya\" data-id=\"3401310060\">תניא ח\"ב פ\"א</a><a class=\"ft-cite\" href=\"#/read/tanya/3401310060\" data-slug=\"tanya\" data-id=\"3401310060\">­ג. שם פ\"ו (פ, ב</a> ואילך)."],["1322","29","<a class=\"ft-cite\" href=\"#/read/tanya/3401310027\" data-slug=\"tanya\" data-id=\"3401310027\">תניא ח\"א פכ\"ב</a>. ע\"ש באורך."],["1323","30","עיין <a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא שם</a> (וראה גם שם פכ\"ד (ל, ב))."],["1324","31","ראה שם פכ\"א­כב."],["1325","32","שם ספכ\"א."],["1326","33","ל' התניא רפ\"כ."]]],[1301410223,"אסורים וטמאים כו' באמת (ע\"פ תורה)<sup data-n=\"1327\">34</sup>?\nואחד הביאורים בזה — שזה שיש ל­דברים האסורים תוקף ומציאות ע\"פ תורה, הוא רק כדי שתהי' עבודת ישר­אל, להתגבר עליהם ולדחותם כו', וב­לשון הרמב\"ם (הנ\"ל) — \"הסירו את אלקי הנכר גו'\". כלומר: החפצא של האיסור מצד עצמו אין בו שום אמת (ואינו אלא מחמת ההסתר המכסה על האמת), וה­\"אמת\" שיש במציאות האיסור היא אך ורק מצד זה שניתן לה מציאות ותוקף (ע\"פ תורה) כדי שתהי' עבודת ישראל, ד\"למעשה ידיך תכסוף\" (כנ\"ל), שידחו את הדברים האסורים ויתגברו עליהם, כנ\"ל.\nז. ומכאן למדנו התחזקות גדולה ב­עבודת האדם עלי אדמות. דלפעמים יוכל האדם לבוא לרגש של חלישות ב­עבודתו בראותו את כל המניעות והעי­כובים בעולם על דברים שבקדושה, ושכדי להתגבר עליהם צריך מלחמה עצומה כו', ומאין יהי' לו התוקף לנצח מלחמה זו?\nוע\"ז באה ההוראה, שכל המציאות של המנגד אינה אלא מחמת ההסתר ה­מכסה על האמת ש\"אין עוד מלבדו\" ואין לשום דבר בעולם מציאות בלעדו ית', ולכן, אם יתדבק האדם בהשם עד שתת­גלה בו אחדותו ית' האמיתית, הרי בדרך ממילא תתבטל מציאות המנגד, כמו חושך הנדחה בפני אור, כי באמת אין לה שום מציאות כלל, כנ\"ל.\nוכמבואר<sup data-n=\"1328\">35</sup> גם כן בפירוש הכתוב<sup data-n=\"1329\">36</sup> \"כי תצא למלחמה על אויביך\", שזהו רמז על מלחמת היצר (שנקרא \"אויבו\" של האדם) — ובכללות יותר קאי על המלחמה נגד כל אויבי ה' — שעל האדם לידע (תיכף ביציאתו למלחמה), שבעצם הרי הוא \"על (ולמעלה מ)אויביך\", כי רק ישראל הדבוקים בהשם יש להם מציאות אמיתית<sup data-n=\"1330\">37</sup>, משא\"כ \"אויביך\" שהם מנגדים לקדושה, אין להם תוקף ומציאות אמי­תית.\nוא\"כ למה עשה ה' ככה שתהי' מצי­אות של \"אויביך\", שלעינים נראה שיש להם תוקף ויכולת לנגד לקדושה? הנה ע\"ז התירוץ בראשית הכתוב, \"כי תצא למלחמה\", שכל הכוונה היא רק כדי שבנ\"י יצאו למלחמה ויוציאו ויגלו בפועל את הכוחות שלהם בביטול אויבי ה'.\nובזה מבוארת הסתירה שבסיום ה­כתוב — \"(כי תצא למלחמה גו') ושבית שביו\":\nהפירוש ב\"שביו\" הוא, שלוקחים מה­אויב הדברים שהיו בשבי' אצלו, וב­עניננו<sup data-n=\"1331\">38</sup>, שהלעו\"ז (אויביך) אין לה תוקף ומציאות מצד עצמה ח\"ו, כי אם מה שנפל אצלה בשבי' מגבול הקדושה.",[["1327","34","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310027\" data-slug=\"tanya\" data-id=\"3401310027\">תניא שם רפכ\"ב</a> \"רק שהתורה דברה כ­לשון ב\"א כו' לפי שבאמת כך הוא דרך ירידת והמשכת החיות כו' וכ\"כ גברו ועצמו הצמצומים והסתר פנים העליונים עד שיוכלו להתהוות. . דברים טמאים כו'\", ע\"ש.\nוהשאלה בפנים היא — שלכאורה, בתורה צריך להיות בגילוי אחדותו האמיתית של הקב\"ה, שאין שום דבר נפרד ממנו ית' באמת (כיון שאין שום הסתר פנים לפניו ית')."],["1328","35","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו\"ת תצא (לו, רע\"א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380865\" data-slug=\"likkutei-torah\" data-id=\"4001380865\">לז, א</a>). וראה במאמרים שנסמנו בהערה 38."],["1329","36","ר\"פ תצא."],["1330","37","ראה אדר\"נ פל\"ד, י."],["1331","38","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380858\" data-slug=\"likkutei-torah\" data-id=\"4001380858\">לקו\"ת שם (לה, סע\"ב</a>). מאמרי אדה\"ז תקס\"ה ח\"ב (ע' תתכג. תתלד). מאמרי אדמו\"ר האמצעי פ' תצא (ע' תצו­ז)."]]],[1301410224,"אבל עפ\"ז אינו מובן סיום הכתוב \"ושבית שביו\" — כיון שזהו \"שבי\" — נכס שלך, מדוע נאמר \"ושבית\"? הרי היציאה מרשות האויב אינה ענין של שבי' (\"ושבית\"), אלא להיפך, השבה למקומו האמיתי, בגבול הקדושה, והול\"ל \"וה­שבות שביו\".\nאלא שהם הם שני ההפכים הנ\"ל ב­נוגע למציאות הלעו\"ז (\"אויביך\"): מצד אחד, הרי אין להם שום מציאות מצד עצמם, אלא מה שלוקחים ב\"שבי\" מגבול הקדושה; וביחד עם זה ניתן להם תוקף ע\"פ תורה, כי לולא זאת לא תתכן מצי­אות של עבודת ישראל [שאם לא יהי' להם תוקף ע\"פ תורה, וכל התנגדותם לקדושה לא תהי' אלא דמיון בעלמא, אין כאן חידוש בזה שהאדם מנצח את האויב]. וזהו מ\"ש \"ושבית שביו\", דאע\"פ שהמדובר ב\"שביו\", דבר שאין לו מצי­אות מצד עצמו אלא מחמת הקדושה, מ\"מ צ\"ל (מצד ישראל) פעולה של \"ו­שבית\", כאלו הם בבעלותם של האויב, כי רק עי\"ז מודגש חידושם של ישראל, בזה שמנצחים וכובשים האויב תחת רשות הקדושה.\nוזהו כל מציאותם של אויביך, לא שיש להם מציאות באמת ח\"ו, אלא אך ורק כדי שבנ\"י יטלו את שלהם (\"ושבית שביו\"), ע\"ד דברי רש\"י<sup data-n=\"1332\">39</sup> בנוגע לא\"י, \"כל הארץ של הקב\"ה היא, ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו\", היינו, שהנתינה להם היא מלכתחילה רק כדי ליטלה מהם וליתנה לישראל<sup data-n=\"1333\">40</sup>.\n<span data-k=\"q\">(משיחת ש\"פ שופטים תשמ\"ח) </span>",[["1332","39","בראשית א, א."],["1333","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051131\" data-slug=\"likkutei-sichot\" data-id=\"1300051131\">לקו\"ש ח\"ה (ע' 119</a>), שי\"ל שכוונת רש\"י היא, שהקב\"ה רצה שבנ\"י יעשו ויהפכו את ארץ הגוים לארץ ישראל, ונמצא שהרצון (הראשון) ליתנה להם הי' כדי ליטלה מהם וליתנה לנו (ע\"י כיבוש בנ\"י)."]]],[1301410225,"<h3>שיחה ג</h3>\nא. אחת מנשי עשו המנויות בפרשתנו היא \"בשמת בת ישמעאל\"<sup data-n=\"1334\">1</sup>, הנקראת בפ' תולדות<sup data-n=\"1335\">2</sup> בשם \"מחלת בת ישמעאל\". ומ­בואר ברז\"ל<sup data-n=\"1336\">3</sup>, והביאו רש\"י בפירושו על התורה כאן — ששמה הי' \"בשמת\" ומה שנק' \"מחלת\" הוא רמז — \"לפי שנמחלו לו (כל) עוונותיו\"<sup data-n=\"1337\">4</sup> (של עשו), ומזה למדין שחתן (נושא אשה) מוחלין לו כל עוונותיו.\nאמנם בביאור ענין זה (שחתן ביום חופתו נמחלו כל עוונותיו) מצינו ב' גירסאות:\nבירושלמי<sup data-n=\"1338\">5</sup> (ועד\"ז במדרש שמואל<sup data-n=\"1339\">6</sup>) איתא: חכם חתן נשיא גדולה<sup data-n=\"1340\">7</sup> מכפרת. . חכם, מפני שיבה תקום והדרת פני זקן<sup data-n=\"1341\">8</sup>, מה כתיב בתרי'<sup data-n=\"1342\">9</sup> וכי יגור אתכם<sup data-n=\"1343\">10</sup> גר גו' מה הגר מוחלין לו על כל עוונותיו אף חכם שנתמנה מוחלין לו על כל<sup data-n=\"1344\">11</sup> עוונותיו<sup data-n=\"1345\">12</sup>; חתן, וילך עשו אל ישמעאל ויקח את מחלת בת ישמעאל<sup data-n=\"1346\">13</sup> וכי מחלת שמה והלא בשמת שמה אלא שנמחלו<sup data-n=\"1347\">14</sup> לו כל עוונותיו; נשיא, בן שנה שאול במלכו<sup data-n=\"1348\">15</sup> וכי בן שנה הי' אלא שנמחלו לו<sup data-n=\"1349\">16</sup> (על<sup data-n=\"1350\">17</sup>) כל עוונותיו<sup data-n=\"1351\">18</sup>.",[["1334","1","לו, ג."],["1335","2","כח, ט."],["1336","3","ירושלמי בכורים פ\"ג ה\"ג. מדרש שמואל רפי\"ז. וצ\"ע שבפרש\"י נשמטה תיבת \"כל\". וראה לקמן הערה 11. 19."],["1337","4","כ\"ה בירושלמי. ובמדרש שמואל \"שמחלו<sup data-n=\"e36\">*</sup> לו על כל עונותיו\"."],["1338","5","ירוש' בכורים שם."],["1339","6","שם בשינויים קלים — כבהערות שלאח\"ז."],["1340","7","במדרש שמואל \"הגדולה\". וביל\"ש שמואל שם (רמז קיז) ליתא תיבה זו. וראה הערה 34."],["1341","8","קדושים יט, לב."],["1342","9","שם, לג."],["1343","10","כ\"ה בירושלמי. ולכאורה צ\"ל \"אתך\" (כב­כתוב). וכ\"ה במד\"ש ויל\"ש שם."],["1344","11","בירושלמי ובמד\"ש איתא בכולם \"כל עונו­תיו\" — בגר, חכם, חתן (בעשו) ונשיא — כבפנים. ביל\"ש שמואל שם איתא תיבת \"כל\" רק ב\"נשיא\". ב\"קונדריס אחרון\" שבסוף יל\"ש (\"אשר סדר הר' שמעון הדרשן לאחר שכתב זה הספר (היל\"ש)\" — נוסח ההקדמה דמהדורה הא' של היל\"ש על התורה (שאלוניקי, רפז)) סי' קעח איתא \"כל\" ב\"חכם\" ו\"נשיא\" אבל לא ב\"חתן\" (עשו) ו\"גר\". בס' פרדס הגדול בסופו (לקוטים ושו\"ת לרבינו שלמה) נט, ג — בשם \"מצא רבי במדרש\" — נאמרה תיבת \"כל\" בגר חכם וחתן (עשו), אבל לא בנשיא (ראה הערה 18)."],["1345","12","במדרש שמואל: מה גר נמחלו לו כל עונותיו אף זה נמחל לו על כל עונותיו. ועד\"ז ביל\"ש שם."],["1346","13","תולדות שם."],["1347","14","במדרש שמואל (וביל\"ש) \"אלא מלמד שמחלו לו\"."],["1348","15","ש\"א יג, א."],["1349","16","במדרש שמואל (ויל\"ש): אלא מלמד שמחלו לו, כנ\"ל."],["1350","17","כ\"ה בכמה דפוסי ירושלמי, וכבמדרש שמואל שם."],["1351","18","בירושלמי מסיים \"כתינוק בן שנה\". ובמדרש שמואל (ועד\"ז ביל\"ש) ממשיך: נשיא ומלך נעשה כתינוק בן שנה שלא טעם טעם חטא. ובספר הפרדס שבהערה 11 \"כיון שמלך נעשה כבן שנה נקי ומלובן\". וביל\"ש שם הובא לאח\"ז: רב הונא אמר<sup data-n=\"e37\">*</sup> כבן שנה שלא חטא מימיו."],["e36","*","בהוצאת באבער \"שמחלה (?) לו על כל עונותיו\". ובפרש\"י עה\"פ כאן ב' גירסאות \"שנמחלו (לו) עונותיו\", \"שנמחלו עונותי'\" (של בשמת). וראה לקמן הערה 41."],["e37","*","ביל\"ש שם נסמן יומא (כב, ב). וביומא שם לפנינו \"אמר רב הונא כבן שנה שלא טעם טעם חטא\"."]]],[1301410226,"אבל רש\"י בפירושו על התורה מע­תיק מ\"אגדת מדרש ספר שמואל\": \"ג' מוחלין להן עוונותיהן<sup data-n=\"1352\">19</sup> גר שנתגייר וה­עולה לגדולה והנושא אשה\" [ויליף מזה ש\"נקראת מחלת שנמחלו<sup data-n=\"1353\">20</sup> עוונותיו\"]<sup data-n=\"1354\">21</sup>.\nהיינו שבירושלמי ומדרש שמואל (ש­לפנינו) קחשיב רק \"חכם חתן ונשיא\" ולא נמנה עמהם גר שנתגייר (אף דמיני' ילפינן שכן הוא גבי חכם) — וי\"ל הטעם, כי גר שנתגייר ה\"ה מציאות חדשה, כ­קטן שנולד דמי<sup data-n=\"1355\">22</sup>, ואין לו שייכות למצי­אותו הקודמת<sup data-n=\"1356\">23</sup> (עד שמצד \"דין תורה\" יכול לישא אחותו (מגייותו)<sup data-n=\"1357\">24</sup>), שלכן<sup data-n=\"1358\">25</sup> מובן שאין לכללו בהנך ג' שמוחלין להן עוונותיהן — וצריך להבין מהו טעמו של רש\"י שכ' \"ג' מוחלין להן עוונותיהן גר שנתגייר וכו'\", שגם גר הוא מהג'<sup data-n=\"1359\">26</sup> (וחכם שנתמנה ונשיא — שניהם בכלל \"עולה לגדולה\")<sup data-n=\"1360\">27</sup>?\nב. והנה בהסברת גירסת רש\"י — ש­מביא גר שנתגייר בין אלה שמוחלין להם עוונותיהם (ולא עוד אלא שמקדים \"גר שנתגייר\" לכולם) — י\"ל (כמבואר במ\"א<sup data-n=\"1361\">28</sup>) דענין המחילה דגר מלמד על השאר: כשם שבגר שנתגייר הרי פשוט, שמחילת עוונותיו קשורה בזה ששינה מעשיו לטובה<sup data-n=\"1362\">29</sup> — כך גם מי שעולה ל­גדולה ונושא אשה<sup data-n=\"1363\">30</sup>, שעוונותיהם נמ­חלים, ה\"ז משום שבודאי עשו תשובה.\nולכאורה כן משמע קצת מב\"ר<sup data-n=\"1364\">31</sup> ש­עשו \"נתן דעתו להתגייר מחלת שמחל לו הקב\"ה על כל עוונותיו\", היינו ד­מחילת העוונות של החתן באה מצד דעתו לשנות מעשיו<sup data-n=\"1365\">32</sup>.",[["1352","19","כ\"ה ברוב דפוסי וכת\"י רש\"י (שתח\"י); ובב' כת\"י רש\"י (שתח\"י) \"על כל עונותיהם\". אבל בסוף פרש\"י (בנוגע למחלת) גם בב' כת\"י אלה ליתא תיבת \"כל\"."],["1353","20","ראה הערה 4 בשוה\"ג."],["1354","21","ביאור פרש\"י זה — ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051175\" data-slug=\"likkutei-sichot\" data-id=\"1300051175\">לקו\"ש ח\"ה ע' 163</a> ואילך."],["1355","22","יבמות כב, א. וש\"נ."],["1356","23","\"ונעשה ברי' ועשי' חדשה\" (שו\"ע אדה\"ז או\"ח סמ\"ו ס\"ד)."],["1357","24","ראה יבמות שם ובתוד\"ה ערוה שם. רמב\"ם הל' איסורי ביאה פי\"ד הי\"ב. וראה נ\"כ הרמב\"ם שם."],["1358","25","להעיר שבתשב\"ץ קטן (סתס\"ה) הביא ממדרש הלימוד בנוסח אחר מהירושלמי \"נשיא דכתיב מפני שיבה וגו' וסמיך לי' וכי יגור אתכם גר וגר שנתגייר כקטן שנולד דמי\", וליתא שם \"מה גר מוחלין לו על כל עונותיו\"."],["1359","26","להעיר שביבמות מח, סע\"ב פליגי אם ב\"נ נענש על זה שעבר קודם הגירות. אבל (נוסף ע\"ז דרק לדעת ר\"ח נענש, ולדעת רבים (ר\"י, אבא חנן משום רבי אליעזר) אינו נענש, הרי) לפ\"ז נמצא דמחז\"ל דג' מוחלין להן עונותיהם קשה, דהרי לדעת ר\"ח רק ב' מוחלין להם עונותיהם, ולדעת ר\"י דהו\"ל כקטן שנולד, דוחק קצת שמשווי לגמרי כל הג' שמוחלין להם עונותיהם. אבל ראה יפה מראה לירושלמי בכורים שם. וראה ספר חסידים סתרצ\"א ובמפרשים שם. דברים אחדים להחיד\"א (קלה, א ואילך). אנציקלופדי' תלמודית ערך גר (ע' רסט ואילך). וש\"נ."],["1360","27","לכאורה כן מפרש רש\"י במדרש שמואל, דבכללות מבואר כאן ג' סוגים אלו — גר, עולה לגדולה (חכם ונשיא) וחתן. וכמ\"ש ביפה מראה לירושלמי שם. ואין הכרח לומר שכן היתה גירסת רש\"י במדרש שמואל."],["1361","28","ראה לקו\"ש שם ע' 170."],["1362","29","ראה שו\"ת חוות יאיר סי' עט. וראה יפה מראה שם בסופו."],["1363","30","אבל להעיר מס' פרדס הגדול (לרש\"י) הנ\"ל הערה 11 בסופה: כיון שזכה לחתונה מוחלין לו על כל עונותיו (ומשמע שאינו תלוי בעשיית תשובה)."],["1364","31","פס\"ז, יג."],["1365","32","להעיר מבחיי פרשתנו עה\"פ, שכולל ב' דברי רז\"ל יחד, שמתחלה מביא \"עשו נתן דעתו להתגייר\", וממשיך \"ושלשה מוחלין להן על כל עונותיהן גר שנתגייר והעולה לגדולה והנושא אשה ומוכיח מן הכתוב הזה שנקראת מחלת שנמחלו לו על כל עונותיו\"."]]],[1301410227,"ולפ\"ז מסתבר, דלהירושלמי ומדרש שמואל (שלפנינו), שלא מנו גר בין הנך שמוחלין להם עוונותיהם (ורק נלמד מ­גר), משמע שמחילת העוונות בחכם חתן ונשיא לא באה מפני ששינו מעשיהם ועשו תשובה, אלא רק בגלל זה שנעשו חכם (שנתמנה) נשיא וחתן<sup data-n=\"1366\">33</sup>. וכן מוכח מדיוק לשון הירושלמי ומדרש שמואל \"חכם חתן נשיא גדולה<sup data-n=\"1367\">34</sup> מכפרת\", דאין \"גדולה\" חלוקה בפ\"ע<sup data-n=\"1368\">35</sup> אלא היא מוסבת על כל הג' פרטים שנמנו לפנ\"ז<sup data-n=\"1369\">36</sup>, דהיינו שעצם עלייתם לגדולה מכפר.\nויש להבין סברת החילוק בין דברי הירושלמי (והמדרש שמואל שלפנינו) והמאמר כפי שהובא בפרש\"י.\nעוד צריך ביאור בדברי הב\"ר הנ\"ל, כי אינם עולים בקנה אחד עם המבואר לעיל, שהרי מוכח שם שרק \"נתן דעתו להתגייר (היינו לשוב בתשובה<sup data-n=\"1370\">37</sup>)\", אבל לפועל לא נתגייר, שלא שינה מעשיו<sup data-n=\"1371\">38</sup>.\nג. גם יש לדייק: מדוע נרמז ענין כללי כזה השייך לנישואי כל איש ואיש (שחתן מוחלין לו עוונותיו) בנשואי עשו עם בשמת בת ישמעאל, ולא בנישואי חו\"כ מסוג יותר נעלה, המתאימים יותר לתוכנם של נישואין (ע\"פ תורה)? ובפרט שמלבד זאת שהמדובר הוא בנשואי עשו הרשע, הרי גם הנשואין עצמם לא היו אלא ענין של רמאות — להראות ליצחק שנושא אשה כשירה, כמסופר בפ' תול­דות<sup data-n=\"1372\">39</sup> \"וירא עשו כי ברך יצחק את יעקב. . ויצו עליו. . לא תקח אשה מבנות כנען. . וירא עשו כי רעות בנות כנען בעיני יצחק אביו וילך עשו אל ישמעאל ויקח את מחלת בת ישמעאל גו' על נשיו גו'\", ופרש\"י \"הוסיף רשעה על רשעתו שלא גרש את הראשונות\"<sup data-n=\"1373\">40</sup>.\nלפי הירושלמי (ומדרש שמואל של­פנינו) יש לומר, דבזה שהלימוד הוא דוקא מ\"מחלת\" שנאמר בנשואי עשו, בא הכתוב להשמיענו שמחילת עוונותיו של חתן ה\"ה גם באופן שלא שינה מעשיו לטוב ולא עשה תשובה (כמו עשו הרשע, \"שלא גרש את הראשונות\");\nאבל לפי פרש\"י שגם בחתן ה\"ז תלוי בשינוי מעשיו לטוב, בדוגמת גר שנת­גייר,",[["1366","33","ואף שנלמד מגר — הרי א) הלימוד מגר הוא רק על \"חכם\", משא\"כ חתן ונשיא נלמדים מ­פסוקים אחרים. ב) גם בחכם מסתבר לומר שהלימוד מ(הסמיכות ל)גר הוא רק בנוגע להמציאות בפועל, שמוחלין לו על כל עונותיו, אבל לא על אופן וגדר המחילה. וכדמוכח גם מלשון הירושלמי \"הגדולה מכפרת\", אף שמביא לימוד מיוחד על כל סוג בפ\"ע, מ\"מ, גדר הכפרה והמחילה שווה בכולם, \"גדולה מכפרת\", כדלקמן בפנים."],["1367","34","ולא \"וגדולה\" (בוא\"ו). במדרש שמואל לפנינו \"וגדולה מכפרת\". אבל לכאורה הוא ט\"ס. ובהוצאת באבער הוא כבירושלמי \"גדולה\"."],["1368","35","והרי לא הביא להלן ראי' בפ\"ע על \"גדולה\"."],["1369","36","וכן מוכח מהל' \"מכפרת\" (ל' יחיד ול' נקבה) דקאי על \"גדולה\" הכוללת כולם, דאל\"כ הול\"ל \"מכפרין\". וכ\"ה ביל\"ש שמואל שם (שליתא שם \"גדולה\") \"חכם חתן ונשיא מכפרין\". ועד\"ז ב­ספר הפרדס שם \"שלשה מכפרין חכם ונשיא וחתן\"."],["1370","37","לכאורה כ\"ה הכוונה במדרש \"להתגייר\" ולא כפשוטו — ראה רד\"ל לב\"ר שם סקי\"ט."],["1371","38","ראה יפה תואר השלם (ובהקצר) שם. נזר הקודש השלם שם. וראה גם יפה מראה לירושלמי בכורים שם; עץ יוסף לירושלמי שם — דהתנא דב\"ר והא דירושלמי פליגי. ע\"ש."],["1372","39","בסופו (כח, ו ואילך)."],["1373","40","הביאור בזה ע\"ד הפשט ראה בארוכה לקו\"ש שם ע' 169 ואילך ובהערות שם. חל\"ה ע' 113 ואילך."]]],[1301410228,"הרי תמוה ביותר, איך מתאים לו­מר שנמחלו עונותיו של עשו — והלא לא עשה תשובה אלא \"הוסיף רשעה כו'\"?\nלכאורה י\"ל שמהאי טעמא נרמז זה בשם אשתו — \"מחלת\" (ולא בשמו של עשו) — כי בנדו\"ד נמחלו עונותי' של מחלת אשת עשו, כי רק היא עשתה תשובה בעת הנישואין<sup data-n=\"1374\">41</sup>.\nאבל עדיין יש להבין מאי טעמא מ­רמז הכתוב דבר זה בנשואי עשו דוקא?\nיש מפרשים<sup data-n=\"1375\">42</sup>, ד\"ממה שנמצא לימוד זה בהך קרא למדנו דאע\"ג דכבר יש לו אשה ובנים דהשתא תו ליכא מצות פו\"ר אפ\"ה מוחלין לו דהא הכא גבי עשו כשלקח אשה זו כבר הו\"ל תרתי נשי ובנים נמי\".\nאמנם לכאורה אין זה ביאור מספיק — כי אף שלא מצינו לפנ\"ז מפורש בתורה ענין של נשואי אשה לאחר ש­כבר היו לו להנושא אשה ובנים<sup data-n=\"1376\">43</sup> (וגם בנשואי יעקב, שנשא ד' נשים, אין מקום ללימוד זה, כי מעיקרא לא היו לו עוונות<sup data-n=\"1377\">44</sup>) — הרי מובן הוא דכיון שכל עניני התורה הם בתכלית הדיוק, צריך לומר, שדבר זה מתאים להשמיענו (לרא­שונה) דוקא בנשואי עשו.\nד. וי\"ל הביאור בזה:\nכמה טעמים נאמרו<sup data-n=\"1378\">45</sup> ע\"ז ש\"נהגו<sup data-n=\"1379\">46</sup> שהחתן והכלה מתענין ביום חופתן\": א) \"דהוי<sup data-n=\"1380\">47</sup> סליחה דידהו שנמחלין עוונו­תיהן ויום כפור דידהו\"<sup data-n=\"1381\">48</sup>; ב) \"שמא יש­תכרו ולא יהי' דעתן מיושבת עליהן ב­שעת הקידושין\"<sup data-n=\"1382\">49</sup>; ג) \"מפני שמצוה חבי­בה עליהם (לכן נוהגין) כדרך שעושין חסידים הראשונים שהיו מתענין על מצוה החביבה, כגון לולב ושאר דברים\"<sup data-n=\"1383\">50</sup>.",[["1374","41","כהגירסא \"שנמחלו עונותי'\". — ולהגירסא ברש\"י \"נמחלו עונותיו\" — צריך לומר, שמחילת עונותי' של מחלת (מפני תשובה שלה) נמשכה גם על עשו (ואולי זוהי הכוונה בגי' מד\"ש באבער הנ\"ל (שוה\"ג להערה 4) \"שמחלה לו כו'\", היינו שבאה בסיבתה. ודוחק). ועצ\"ע."],["1375","42","משכיל לדוד לפרש\"י פרשתנו עה\"פ. ו­עד\"ז במלאכת הקודש עה\"פ."],["1376","43","וצ\"ע אם זה שייך כשנושא פלגש בנוסף על אשתו, כמו בס\"פ וירא."],["1377","44","וכן בנוגע לזה ש\"ויוסף אברהם ויקח אשה ושמה קטורה\" (ח\"ש כה, א), אחרי שכבר הי' לו בן יצחק (ולדיעה אחת (ב\"ב טז, ב) היתה לו גם בת, היינו קיום מצות פו\"ר גם לדעת ב\"ה (יבמות סא, ב)) — דהרי לא היו לו עוונות (רש\"י ח\"ש שם, ז). ונוסף ע\"ז — הרי אז לא היתה לו אשה בכלל, דשרה כבר מתה."],["1378","45","בכל הבא לקמן ראה נ\"כ השו\"ע שבהערה הבאה. שדי חמד אסיפת דינים מערכת חתן וכלה ס\"ד. אנציקלופדי' תלמודית ערך חתן (ע' שכ ואילך). וש\"נ."],["1379","46","ל' הרמ\"א שו\"ע אה\"ע סס\"א ס\"א."],["1380","47","שו\"ת מהר\"ם מינץ סי' קט (ד\"ה וראיתי רבותי), הובא בב\"ש אה\"ע שם סק\"ו. באר היטב שם סק\"ה. מג\"א או\"ח ר\"ס תקעג (והשמיטו הא דכ' \"וי\"כ דידהו\"). וראה מושב זקנים עה\"ת ס\"פ תולדות (נעתק לקמן הערה 65). ובשו\"ת מהר\"י ברונא \"אמרתי בינקותי. . משום דאמרינן. . דמלך נידון בכל יום וחתן דומה למלך והואיל ויומא דדינא הוא לגבי' בעי מתענה כמו ביום כפור\", אבל ממשיך \"ומהאי טעמא יש בני אדם דמתענים בר\"ה לפי שיום דין הוא\". וראה הערה הבאה."],["1381","48","בשו\"ת מהר\"ם מינץ שם ממשיך \"כדדר­שינן על הא דכתיב ויקח את מחלת כו'\". ובשו\"ת מהר\"י ברונא שם הביא כטעם בפ\"ע \"ועוד שמעתי לפי דאמרי' בגמ' המתעלה עוונותיו נמחלין וכיון דעולה לגדולה אולי יגרום החטא ויתבטל ומקבל עלי' תשובה וצערא בעלמא עד דסיים חופתו והדר אכיל\"."],["1382","49","שו\"ת מהר\"מ מינץ שם, הובא בב\"ש ובאר היטב אה\"ע שם. מג\"א שם. וראה שו\"ת מהר\"י ברונא שם בתחלתו."],["1383","50","רוקח סי' שנג."]]],[1301410229,"וא' מהחילוקים שנאמר בפוסקים בין הני טעמי הוא<sup data-n=\"1384\">51</sup>: לטעם הא' ראוי להש­לים התענית<sup data-n=\"1385\">52</sup>, משא\"כ לטעם הב' והג' — א\"צ להשלימו, כפשוט (ולאידך אם נת­אחרה החופה עד אחר צה\"כ — לטעם הא' א\"צ להתענות רק עד צה\"כ, ולטעם הב' והג' — צריכים להתענות עד אחרי החופה).\nוי\"ל שאפי' את\"ל שגם לטעם הא' (דהוא יום סליחה שלהם) אין צריך להשלים התענית — כיון שגם תענית שעות נחשב כתענית<sup data-n=\"1386\">53</sup> — יש חילוק עיקרי בין הני ג' טעמי בהגדרת מהות התענית: לטעם הא' יש כאן חלות דין תענית על הגברא וגם על היום<sup data-n=\"1387\">54</sup>; משא\"כ לטעם הב' והג', דאין בזה חלות תענית, אפי' על הגברא, כ\"א רק שלילה והעדר האכילה.\nוהנה פשוט דלכו\"ע (גם הפוסקים שנקטו הטעם הב' והג') הרי יום החופה הוא יום מחילה וסליחה להחתן והכלה, כפשטות דרשת רז\"ל בירושלמי ומדרש שמואל.\nולפ\"ז צ\"ל, שהפוסקים שנתנו טעמים אחרים להתענית סבירא להו שמחילתם של החו\"כ אינה תלוי' בתשובה ותענית של תשובה, אלא המחילה באה ע\"י ה­נשואין לבד.\nומכיון שלכו\"ע<sup data-n=\"1388\">55</sup> יום חופתם של החתן והכלה הוי יום מחילה וסליחה (ע\"ד יום כיפור), יש לומר, שהמחלוקת בין הטעמים הנ\"ל שבפוסקים — אם זקו­קים לתענית של תשובה בשביל הכפרה — היא בדוגמת הפלוגתא שמצינו בענין כפרת יום הכפורים<sup data-n=\"1389\">56</sup>: לדעת רבי בין עשה תשובה בין לא עשה תשובה יוה\"כ מכפר, דעיצומו של יוה\"כ מכפר, ולדעת רבנן — רק אם עשה תשובה יוה\"כ מכפר.\nועד\"ז הוא בנדו\"ד, דהאומרים דמת­ענין משום דהוי יום סליחה ויו\"כ דידהו, ס\"ל דחתן וכלה צריכים עשית תשובה לכפרתן<sup data-n=\"1390\">57</sup>, דזהו תוכן תענית של תשו­בה<sup data-n=\"1391\">58</sup> (כמ\"ש הרמב\"ם<sup data-n=\"1392\">59</sup> דהצום הוא \"כדי לעורר הלבבות לפתוח דרכי התשובה\"), ואלו שנקטו הטעם הב' והג' הנ\"ל — ס\"ל דהכפרה היא מצד עיצומו של יום (חופתן), ע\"ד דעת רבי (הנ\"ל) בנוגע ליוה\"כ.",[["1384","51","ב\"ש ובאר היטב שם. כנסת הגדולה אה\"ע סס\"ב הגהות הטור סקט\"ו. פתחי תשובה שם סס\"א סק\"ט. ועוד. וראה בארוכה שד\"ח שם."],["1385","52","אבל ראה הלשון בשו\"ת מהר\"י ברונא שם (נעתק לעיל הערה 48). וראה שדי חמד שם."],["1386","53","עזר מקודש לאה\"ע שם. וכן משמע בפרמ\"ג (א\"א) או\"ח ר\"ס תקעג. וראה אגה\"ת פ\"ג \"עד חצי היום דמיחשב ג\"כ תענית בירושלמי\". וראה הערה הבאה."],["1387","54","ראה בארוכה צפע\"נ להל' תעניות פ\"א ה\"ט ובכ\"מ (נעתק בצפע\"נ כללים בערכו) דעיקר גדר תענית היא על היום שיהא היום נקרא תענית וממילא אסור לאכול. ובהל' תעניות שם הי\"א (לז, א) כ' \"דתענית חל על עצם היום, גבי שעות לא, רק זה לכו\"ע בגדר לצעורי נפשי'\". ולכאורה לפי מ\"ש בתוס' (ע\"ז לד, א. הובא בצפע\"נ שם), רא\"ש (תענית פ\"א סי\"ב), דגם תענית שעות צריך לקבל עליו מאתמול מבעוד יום, משמע דגם בתענית שעות חל על (חלק זה ד)היום שם \"תענית\". ואכ\"מ."],["1388","55","וידוע הכלל שאין להרבות במחלוקת (דרכי שלום (בשדי חמד, קה\"ת) כללי הש\"ס אות ל' סרנ\"ז)."],["1389","56","שבועות יג, א. וש\"נ."],["1390","57","ראה ביאור הגר\"א לרמ\"א שו\"ע או\"ח סתקס\"ב ס\"ב."],["1391","58","ראה שו\"ע אדה\"ז חלק חו\"מ הל' נזקי גוף ונפש ס\"ד \"ולכן מותר להתענות לתשובה כו'\". וראה אגה\"ת פ\"א."],["1392","59","הל' תעניות פ\"ה ה\"א. וראה שם פ\"א ה\"ב. מעשה רוקח לרמב\"ם שם."]]],[1301410230,"ה. אמנם אפילו לרבנן, דס\"ל שאין יו\"כ מכפר בלי תשובה, מוכח מדברי הרמב\"ם<sup data-n=\"1393\">60</sup> דאין הכפרה באה מהתשובה, אלא מעיצומו של יום הכפורים, אלא שעיצומו של יוה\"כ מכפר דוקא כאשר ישנה תשובת האדם<sup data-n=\"1394\">61</sup>.\nויתירה מזו<sup data-n=\"1395\">62</sup>: מזה שכתב הרמב\"ם<sup data-n=\"1393\">60</sup> \"עיצומו של יום הכפורים מכפר לשבים\" ולא אמר \"מכפר עם התשובה\" וכיו\"ב, מוכח דלדעת הרמב\"ם מועילה כפרת עיצומו של היום גם לזה שלא עשה תשובה (גמורה) על חטאיו (תשובה עם כל גדרי' ותנאי' — חרטה על העבר וקבלה טובה על להבא בוידוי דברים), אלא שהוא נמצא רק בתנועה וגדר של \"שב\", ששב ופונה לה'.\nוע\"פ זה נמצא שיש ג' שיטות באופן הסליחה ומחילה דיו\"כ ויחסה לתשובה: א) דעת רבי שאין צריך לתשובה בשביל הסליחה; ב) דעת רבנן (בפשטות) שצריך תשובה ממש; ג) שיטת הרמב\"ם (לפי פירושו בדעת רבנן) שצ\"ל תנועה של שיבה, אבל לא מעשה תשובה ממש.\nויש לומר, שמעין שלש שיטות אלו ביו\"כ הן ג' השיטות הנ\"ל בגדר הסליחה ומחילה ביום החופה:\nלפי הטעם שהתענית היא רק בשביל צלילות הדעת בשעת הקנין — נמצא שאין לסליחה כל קשר עם התענית; לפי הטעם דהוי תענית של תשובה — ה\"ז כמו יו\"כ לדעת רבנן (בפשטות)<sup data-n=\"1397\">63</sup>; ולפי הטעם שהתענית הוא משום חביבות המצוה, י\"ל שהוא ע\"ד שיטת הרמב\"ם ביו\"כ — שהרי סו\"ס אף שהתענית אינו לתשובה, הרי בחביבות של מצוות הקב\"ה — יש בה קירוב ושיבה להקב\"ה.\nו. לפי זה יש לבאר החילוק הנ\"ל בין דרשת הירושלמי ומדרש שמואל (לפנינו) — ופרש\"י והמדרש:\nכפי פשטות דרשת הירושלמי, ה­כפרה דחתן היא כולה מצד עצם ענין הגדולה דמכפרת<sup data-n=\"1398\">64</sup>, והיינו כענין עיצומו של יום ביום כפור, משא\"כ לפרש\"י ש­מחילת עוונות של חתן ועולה לגדולה באה דוקא כאשר יש עמה תשובה<sup data-n=\"1399\">65</sup> — יש לומר, שהכפרה היא אמנם מצד עצם הענין דנושא אשה (ועולה לגדולה), אלא שכפרה זו אינה אלא דוקא כאשר ישנו ענין התשובה, בדוגמת גר שמשנה מע­שיו כולן לטובה.\n[ולכן אף שלא מצינו מפורש שעשו עשה תשובה, הרי השם מחלת הוא שמה של אשתו — שהיא עשתה תשובה בעת הנשואין<sup data-n=\"1400\">66</sup>].\nולפי המדרש ש\"נתן דעתו להתגייר מחלת שמחל לו הקב\"ה על כל עוונו­תיו\", נמצא דאף שלא הי' כאן ענין של (גיור ו)תשובה ממש, אלא רק תנועה של קירוב לטוב דחפץ להתגייר<sup data-n=\"1401\">67</sup> — גם זה מועיל למחילת עוונותיו שנמחלים ע\"י ענין הנשואין.",[["1393","60","הל' תשובה פ\"א סוף ה\"ג."],["1394","61","ראה לקו\"ש ח\"ד ע' 1150 ואילך."],["1395","62","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271126\" data-slug=\"likkutei-sichot\" data-id=\"1300271126\">לקו\"ש חכ\"ז ע' 126</a> ואילך."],["1393","60","הל' תשובה פ\"א סוף ה\"ג."],["1397","63","להעיר מלקוטי לוי\"צ — אגרות ע' רז."],["1398","64","ראה חדושי אגדות מהר\"ל יבמות סג, ב. גו\"א לפרש\"י פרשתנו עה\"פ. הכותב ויפה מראה לירושלמי בכורים שם. ועוד. וראה שד\"ח שם בסופו מה שמחלק בין חתן להשאר."],["1399","65","ראה מושב זקנים עה\"ת ס\"פ תולדות: מחלת מכאן שהנושא אשה מוחלין לו עונותיו לכך נהגו להתענות החתן ביום הנשואין כי הוא יום הכפורים שלו."],["1400","66","ראה לעיל הערה 41."],["1401","67","ראה מפרשי הב\"ר שם — נסמנו בהערה 38."]]],[1301410231,"ז. עפ\"ז מובן הטעם לזה שנרמז ב­כתוב ענין זה ד\"חתן מוחלין לו כל עוונותיו\" בנשואי עשו עם בת ישמעאל (\"ולמד הטעם מכאן\"), כי גדר זה דכפרה ומחילה מצד ענין הנשואין יתכן רק בישראל<sup data-n=\"1402\">68</sup>, לא בעכו\"ם:\nכשם שהכפרה דעיצומו של יום ה­כפורים לכלל ישראל, שהוא כמ\"ש<sup data-n=\"1403\">69</sup> \"כי ביום הזה יכפר עליכם לטהר אתכם לפני ה' תטהרו\", פועל על האדם היציאה מחטאיו<sup data-n=\"1404\">70</sup>, די\"ל הטעם שהוא כיון ד­כאו\"א מישראל רוצה לעשות כל ה­מצות<sup data-n=\"1405\">71</sup> — עד\"ז הוא ביום כפור פרטי דחתן (וכלה) אשר נושא אשה והולך ל­קיים מצוה רבה דפו\"ר, הרי זה פעולת הנשמה קדושה שלו, ולכן זה גורם למחילת עוונותיו, משא\"כ בעכו\"ם.\nולכן רמזה התורה ענין זה בעשו דוקא, כי עשו הי' בנו דיצחק, הי' לו דין ישראל, כדאיתא בגמ'<sup data-n=\"1406\">72</sup> דעשו ישראל מומר הוי, משא\"כ אלו שמסופר אודות נישואיהם בדורות שלפנ\"ז, הרי לא הי' להם דין ישראל<sup data-n=\"1407\">73</sup>.\nח. ובפנימיות הענינים יש לומר:\nנישואי איש ואשה (כפשוטם), הרי הם משתלשלים מהנישואין, כביכול, ד­הקב\"ה וכנסת ישראל (שנקראים איש ואשה, כמבואר בארוכה בשה\"ש ובמד­רז\"ל), והיינו הדביקות וההתאחדות ד­ישראל ואביהם שבשמים, על ידי עסק התורה וקיום המצות כו', עד לתכלית הדביקות וההתאחדות.\nוכשם שתכלית ענין הנישואין (הגש­מיים) הוא בשביל קיום מצות פרו ורבו גו', הולדת בנים<sup data-n=\"1408\">74</sup> [וכמבואר ברא\"ש<sup data-n=\"1409\">75</sup> שזהו הטעם שלא תיקנו לברך (בברכת אירוסין) \"אשר קדשנו במצותיו וצונו לקדש את האשה\" — \"כי ברכה זו אינה ברכה לעשיית המצוה כי פרי' ורבי' היינו קיום המצוה\"<sup data-n=\"1410\">76</sup>] — כן הוא גם ב­נשואין שבין ישראל ואבינו שבשמים, שתכליתם הוא בשביל פרו ורבו דישר­אל (ברוחניות)<sup data-n=\"1411\">77</sup>, שזה כולל כללות עבו­דת האדם, \"מאי פירות. . מצוות\"<sup data-n=\"1412\">78</sup>, כמחז\"ל<sup data-n=\"1413\">79</sup> \"כל המלמד בן חבירו תורה מעלה עליו הכתוב כאילו ילדו\", וב­כללות — קירוב בני ישראל ליהדות, תורה ומצוותי'.\nעפ\"ז מובן עוד צד­השוה של השלשה שמוחלין להם עוונותיהם — חתן חכם ו­נשיא — כי גם חכם ונשיא ענינם ל­העמיד \"תולדות\", \"פרו ורבו\" ברוחניות; ד\"חכם\" אמיתי הוא המלמד תורה לעמו ישראל (כפסק הרמב\"ם<sup data-n=\"1414\">80</sup> \"מצוה על כל חכם וחכם מישראל ללמד את כל ה­תלמידים\"), ונשיא — שאמיתית תואר \"נשיא\" הוא מי ש\"אין על גביו אלא ה'",[["1402","68","ולהעיר דישמעאל הי' בן אברהם וגם עשה תשובה קודם שמת אברהם (פרש\"י לך טו, טו. ח\"ש כה, ט), ע\"ד עשו — לקמן בפנים."],["1403","69","אחרי טז, ל. הובא ברמב\"ם הל' תשובה שם."],["1404","70","ראה בארוכה לקו\"ש חכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271128\" data-slug=\"likkutei-sichot\" data-id=\"1300271128\">שם (ע' 128</a>)."],["1405","71","רמב\"ם הל' גירושין ספ\"ב."],["1406","72","קדושין יח, רע\"א."],["1407","73","וראה לעיל הערה 68; <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151192\" data-slug=\"likkutei-sichot\" data-id=\"1300151192\">לקו\"ש חט\"ו ע' 192</a> — בנוגע לישמעאל. וש\"נ."],["1408","74","ולהעיר גם מפרש\"י בראשית ב, כד."],["1409","75","כתובות פ\"א סי\"ב."],["1410","76","וי\"א שלכן אין מברכין שהחיינו בברכת נישואין (גליון מהרש\"א לשו\"ע יו\"ד סכ\"ח בש\"ך סק\"ה)."],["1411","77","ראה סה\"מ תרנ\"ט ע' טז­יז."],["1412","78","סוטה מו, סע\"א."],["1413","79","סנהדרין יט, ב."],["1414","80","הל' ת\"ת פ\"א ה\"ב. וראה שו\"ע יו\"ד סרמ\"ה ס\"ג. שו\"ע אדה\"ז הל' ת\"ת פ\"א ס\"ח."]]],[1301410232,"אלקיו\"<sup data-n=\"1415\">81</sup>, דהיינו מלך [וכמפורש בנדו\"ד שהכוונה לשאול המלך<sup data-n=\"1416\">82</sup>] — שענינו של מלך הוא (בלשון הרמב\"ם<sup data-n=\"1417\">83</sup>) \"להרים דת האמת\", לכוף כל ישראל לילך בדרך התורה והמצות ולחזק בדקה כו'.\nט. ועל פי זה יש ללמוד גם הוראה למעשה לכאו\"א — ממחז\"ל הנ\"ל ש­\"מוחלין להם כל עוונותיהם\":\nלכל לראש יש כאן עידוד וחיזוק מיוחד לכאו\"א הבוחר לחלקו ולגורלו להתעסק בהפצת התורה וחיזוק היהדות וכו' — פרו ורבו ברוחניות — שמובטח לו ש\"מוחלין לו על כל עוונותיו\"!\nויתירה מזו — זה שולל טעות של כמה, שטוענים שאינם ראויים לאותה איצטלא, להיות מן המשפיעים טוב לכל ישראל, כי ידע אינש בנפשי' שעדיין רחוק הוא משלימות עצמו, ועליו לקיים הוראת חז\"ל<sup data-n=\"1418\">84</sup> \"קשוט עצמך ואחר כך קשוט אחרים\".\nובא הלימוד ממחז\"ל הנ\"ל — נוסף לזה שכבר הורה לנו נשיא דורנו בשם אביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"1419\">85</sup> שב­דורות האחרונים דעקבתא דמשיחא צ\"ל \"חטוף ואכול חטוף ואישתי\"<sup data-n=\"1420\">86</sup>, דכאשר אינה ה' לידו האפשריות והיכולת ל­השפיע על אחבנ\"י שליט\"א לקרבם לה' ולתורתו ומצוותיו, עליו \"לחטוף\" הזדמ­נות זו בלי חשבונות [ובפרט כשהמדובר בהצלת נפשות ממש, להציל אחבנ\"י שהם בגדר תינוק שנשבה, שלא יטמעו ח\"ו כו'<sup data-n=\"1421\">87</sup>] —\nהנה עוד זאת, שעצם ההחלטה להק­דיש את חייו, עכ\"פ חלק חשוב מחייו, לעסוק בפרי' ורבי' (ברוחניות), מביאה סיוע ועזר הקב\"ה (גם) בעבודתו ה­פרטית, ש\"מוחלין לו כל עוונותיו\" (וב­מילא הרי הוא גם \"קושט עצמו\" תחלה), ועי\"ז גם עבודתו עם אחרים תהי' ב­שלימות יותר, כדבעי<sup data-n=\"1422\">88</sup>.\nועוד זאת: גם אם נדמה בעיניו שהוא בתכלית הירידה שאין למטה ממנה — הרי ענין זה (מחילת עוונות דחתן) נרמז גבי נשואי עשו, ללמדנו, שאינו נוגע לעיכובא מצבו הקודם, וגם אם מצבו הרוחני הוא שפל ביותר (ע\"ד ח\"ו עשו הרשע), הרי תיכף כשבא לקיים מצות פו\"ר הרוחנית ובוחר לו לחלקו ולגורלו לעסוק בקירוב אחבנ\"י לאביהם שב­שמים, הרי הוא מתעלה<sup data-n=\"1423\">89</sup> ממעמדו ומצבו שלפנ\"ז<sup data-n=\"1424\">90</sup>, ומתגלה אמיתית מהותו (זה שרוצה לקיים כל המצות ולהתרחק מן העבירות), ו(בדרך ממילא) נמחלו ונמחקו כל עוונותיו.",[["1415","81","משנה הוריות י, א. וש\"נ."],["1416","82","וראה במדרש שמואל שם ההמשך \"נשיא ומלך\"."],["1417","83","ספ\"ד דהל' מלכים. שם ספי\"א — בנוגע למלך המשיח."],["1418","84","ב\"מ קז, סע\"ב. וש\"נ."],["1419","85","ראה מבוא לקונטרס ומעין ע' 22. אגרות קודש אדמו\"ר (מהורש\"ב) נ\"ע ח\"א ע' רסו."],["1420","86","עירובין נד, רע\"א."],["1421","87","להעיר משו\"ע אדה\"ז או\"ח סו\"ס שו (וש\"נ) שמחללין שבת להציל נפש אחת מישראל שלא תצא מכלל ישראל, אפילו אם הוא ספק. ע\"ש."],["1422","88","ראה יפה מראה לירושלמי בכורים שם."],["1423","89","להעיר מרמב\"ם סוף הל' שמיטה ויובל: ולא שבט לוי בלבד אלא כל איש ואיש. . אשר נדבה רוחו אותו כו' להבדל לעמוד לפני ה' לשרתו ולעובדו כו' (וכמ\"ש בהלכה יב שם שענינו של שבט לוי הוא \"להורות דרכיו הישרים ומשפטיו הצדיקים לרבים\") הרי זה נתקדש קדש קדשים כו'."],["1424","90","להעיר מקונטרס דרושי חתונה תרפ\"ט (ע' כב. סה\"מ קונטרסים ח\"א כז, א): וזהו שארז\"ל (סנהדרין דצ\"ט ע\"ב) כל המלמד את בן חבירו תורה מעלה עליו הכתוב כאילו עשאו דזהו\"ע הקביעות בלימוד התורה ברבים דוקא שעי\"ז נעשה ברי' חדשה."]]],[1301410233,"ודוקא עי\"ז נעשה שלימות הנשואין בין כנסת ישראל וקוב\"ה<sup data-n=\"1425\">91</sup>, זה מקרב את קיום היעוד<sup data-n=\"1426\">92</sup> \"והי' ביום ההוא נאם ה' תקראי אישי ולא תקראי לי עוד בעלי\", בביאת משיח צדקנו, בעגלא דידן ממש.\n<span data-k=\"q\">(משיחות ש\"פ וישלח תשכ\"ז; ש\"פ תולדות תשמ\"ה) </span>",[["1425","91","כמ\"ש בשמו\"ר ספט\"ו: לימות המשיח יהיו נישואין."],["1426","92","הושע ב, יח."]]],[1301410234,"<h3>י\"ט כסלו</h3>\nא. מסופר<sup data-n=\"1427\">1</sup>, שבהיות רבינו הזקן ב­מאסר, באו פ\"א לבקרו רבותיו מעלמא דקשוט — רבו הרב המגיד והבעש\"ט נ\"ע. ושאל אותם רבינו הזקן למה מגיע לו שישב במאסר ומה תובעים ממנו? ו­השיבו לו, שנתחזק עליו הקטרוג על ש­אומר דברי חסידות הרבה ובגילוי<sup data-n=\"1428\">2</sup> כו', ושאל אותם: וכאשר אצא מכאן — האם אפסיק מלומר דברי חסידות? והשיבו לו: כיון שהתחלת אל תפסיק, ואדרבה, לכשתצא תאמר יותר. ע\"כ תוכן הסיפור.\nכלומר: מאסרו של רבינו הזקן למטה (בגשמיות), נשתלשל ובא מהקטרוג ל­מעלה<sup data-n=\"1429\">3</sup> על ריבוי דברי חסידות שאמר ובגילוי כו'; ולכן נתעורר אצלו ספק אולי צריך להפסיק הנהגתו, ועל זה הורו לו רבותיו שאדרבה, \"לכשתצא תאמר יותר\".\nולכאורה זה דורש ביאור: קטרוג מסוג זה כבר הי' בזמן נשיאותו של הרב המגיד, וכידוע<sup data-n=\"1430\">4</sup> הסיפור אודות הקטרוג אז וסיבתו, שפעם \"מצאו כתב של חסי­דות שהתגלגל במקום בלתי ראוי כו' ונעשה קטרוג למעלה על המגיד שמפר­סם עניני רזין דרזין באופן דתשתפכנה<sup data-n=\"1431\">5</sup> אבני קודש בראש כל חוצות — ורבינו הזקן ביטל את הקטרוג ע\"י שהביא משל מבן מלך שנחלה במחלה מסוכנת, שלא מצאו לה אלא תרופה אחת: לקחת את האבן היקרה הקבועה בכתר מלכותו של המלך, שבה תלוי כל היוקר דכתר ה­מלך, לשחקה ולערבה במים, ולשפוך מתערובת זו לבין שפתיו של בן המלך, בתקוה שכולי האי ואולי תיכנס טיפה אחת לתוך פיו וכו' ותציל את חייו — שכן הוא גם בנדו\"ד, אשר פרסום רזי התורה (האבן היקרה שבכתר המלך) כדאי הוא להציל את חיי בן המלך (עם ישראל)\".\nועפ\"ז — אם כבר בימי המגיד ביטל רבינו הזקן את הקטרוג על גילוי דברי חסידות, על ידי ההסברה שפירסום ו­הפצת החסידות הוא דבר מוכרח ביותר, ענין של פיקוח נפש, הנוגע להצלת חייו של בן המלך — עאכו\"כ כשעבר עוד שלב ב\"ירידת הדורות\"<sup data-n=\"1432\">6</sup>, ומן הסתם ירד מצבו (הרוחני) של בן המלך, הרי בודאי ובודאי שהפצת דברי חסידות (שחיקת האבן היקרה שבכתר המלך) הוא הכי הכרחי להצלת חיי נפשו של בן המלך.\nומה נשתנה בעת נשיאותו של רבינו הזקן, ששוב נתעורר עליו הקטרוג בגלל ריבוי דברי החסידות שהשפיע בגילוי — ועד שנתעורר ספק אצלו [למרות שהוא הוא שביטל קטרוג דומה על המגיד ע\"י המשל דשחיקת האבן היקרה שבכתר המלך] שאולי יש לו למנוע מלומר דברי",[["1427","1","בית רבי ח\"א פט\"ז (בהערה)."],["1428","2","וצע\"ק מסה\"מ תש\"ט (ע' 91) שסיבת המאסר הוא הקטרוג על אשר אינו מבאר את תורת החסידות בלבושי השגה כו'."],["1429","3","וכמבואר ג\"כ בכו\"כ שיחות ומכתבים של רבותינו נשיאינו."],["1430","4","\"התמים\" ח\"ב ע' מט [עב, א]. אגרות קודש אדמו\"ר מהוריי\"צ ח\"ג ע' שכו ואילך. ועוד."],["1431","5","איכה ד, א."],["1432","6","דאם ראשונים כמלאכים כו' (שבת קיב, ב (ושם: כבני מלאכים))."]]],[1301410235,"חסידות, והוזקק להוראה מפורשת מרבו­תיו ש\"אדרבה, לכשתצא תאמר יותר\"?\nב. ויובן זה בהקדים ביאור דברי ה­אריז\"ל<sup data-n=\"1433\">7</sup> ש\"דוקא בדורות אלו<sup data-n=\"1434\">8</sup> האחרונים מותר ומצוה<sup data-n=\"1435\">9</sup> לגלות זאת החכמה\" — אף שבדורות הראשונים היתה חכמת הקבלה \"נסתרה<sup data-n=\"1436\">10</sup>. . ונעלמה מכל תלמידי חכמים כ\"א ליחידי סגולה ואף גם זאת בהצנע לכת ולא ברבים כדאיתא ב­גמ'<sup data-n=\"1437\">11</sup>\"—\nדלכאורה: מכיון שהורו חז\"ל ש­\"דברים שהן כבשונו של עולם (\"סתרו של עולם\") יהיו תחת לבושך\"<sup data-n=\"1438\">12</sup>, וע\"פ דין הגמ'<sup data-n=\"1437\">11</sup> יש כמה תנאים והגבלות באופן גילוי חכמה זו (וכן נפסק להלכה ב­רמב\"ם<sup data-n=\"1440\">13</sup>) — איך הותר בדורות אחרונים \"לגלות זאת החכמה\"?\nוהביאור בזה — ובהקדים:\nמובן, שהתנאים וההגבלות בלימוד חכמת האמת אינם מפני איסור מצד ה­חפצא דתורה (שחלק זה שבתורה — צריך בעצם להיות בהסתר), אלא מפני חסרון בהגברא, דכיון שרוב בנ\"א אינם יכולים לעמוד על דברים אלה, לכן לימוד זה עלול להביא לידי היזק (ע\"ד \"לא<sup data-n=\"1441\">14</sup> זכה נעשית לו כו'\"). אבל מצד ה­חפצא דתורה, הרי חכמה זו היא חלק מ­תורתנו הקדושה השייכת לכאו\"א מישר­אל — \"מורשה קהלת יעקב\"<sup data-n=\"1442\">15</sup>, וכל אחד ואחד מישראל חייב ללמוד אותו<sup data-n=\"1443\">16</sup> (כמו שמחוייב ללמוד שאר כל התורה כולה).\nובפרט ע\"פ דברי הרמב\"ם בסוף ספר היד<sup data-n=\"1444\">17</sup>, וז\"ל: \"ובאותו הזמן. . לא יהי' עסק כל העולם אלא לדעת את ה' בלבד ולפיכך יהיו ישראל חכמים גדולים ו­יודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם שנאמר<sup data-n=\"1445\">18</sup> כי מלאה הארץ דעה את ה' כמים לים מכסים\". הרי להדיא, שבימות המשיח יהי' עסק כל העולם לדעת את ה', היינו ש(עיקר) עסק התורה אז<sup data-n=\"1446\">19</sup> לא יהי' בלימוד הלכות התורה הנגלות לנו ולבנינו, אלא בידיעת הבורא, \"דברים הסתומים\", וזה יהי' \"עסק כל העולם\", ובאופן ד\"כמים לים מכסים\", ומובן שלא יהיו ההגבלות ד­\"אין דורשין. . (אפילו) ביחיד אא\"כ כו'\"<sup data-n=\"1447\">20</sup>.\nולכאורה ה\"ז היפך פסק הרמב\"ם עצמו ע\"ד התנאים וההגבלות בלימוד חכמות אלו (והרי גם בימות המשיח לא תתבטל שום הלכה כו' מהלכות התורה)? ועכצ\"ל, שכל האיסור מלכתחילה אינו אלא מפני שבזמן הזה אא\"פ לרוב בני אדם לעמוד על חכמות אלו, ולכן קבעה",[["1433","7","ראה הקדמת הרח\"ו לשער ההקדמות (נדפ­סה ג\"כ בהוספה לקונטרס עץ החיים לכ\"ק אדמו\"ר (מהורש\"ב) נ\"ע). ועוד."],["1434","8","ל' אדה\"ז — תניא אגה\"ק סכ\"ו (קמב, ב). — ואולי צ\"ל אלה<sup data-n=\"e38\">*</sup>."],["1435","9","ראה תניא קו\"א ד\"ה להבין מ\"ש בפע\"ח (קנו, ב) שהיא \"מצוה רמה<sup data-n=\"e39\">*</sup> ונשאה ואדרבה עולה על כולנה\"."],["1436","10","ל' אדה\"ז בתניא שבהערה 8."],["1437","11","חגיגה יא, ב ואילך. שם יג, א."],["1438","12","חגיגה יג, א ופרש\"י שם."],["1437","11","חגיגה יא, ב ואילך. שם יג, א."],["1440","13","הל' יסודי התורה ספ\"ב. שם פ\"ד הי\"א ואילך."],["1441","14","יומא עב, ב."],["1442","15","ברכה לג, ד. וראה רמב\"ם הל' ת\"ת רפ\"ג."],["1443","16","כפסק אדה\"ז בהל' ת\"ת שלו פ\"א ס\"ד — ראה לקמן בסוף השיחה."],["1444","17","הל' מלכים ספי\"ב."],["1445","18","ישעי' יא, ט."],["1446","19","ראה בכ\"ז — אגה\"ק סו\"ס כו. עיי\"ש."],["1447","20","משנה חגיגה רפ\"ב. רמב\"ם הל' יסוה\"ת שם."],["e38","*","כלשון תורה (אף שבל' חכמים רגיל \"אלו\")."],["e39","*","כצ\"ל — ראה לוח התיקון לתניא שם."]]],[1301410236,"תורה תנאים מסויימים בלימוד זה; אבל לימות המשיח, שאז \"לא יהי' שם לא רעב ולא מלחמה ולא קנאה ותחרות\"<sup data-n=\"1448\">21</sup>, וכאו\"א יהי' במצב שיוכל להתעמק כראוי בענינים אלו, הרי בזה יהי' \"עסק כל העולם — לדעת את ה' בלבד\".\nאבל, בדורות האחרונים מצוה לגלות זאת החכמה (למרות התנאים וההגבלות כו') — וי\"ל בזה שני ביאורים<sup data-n=\"1449\">22</sup>:\nא) ע\"ד מ\"ש הרמב\"ם בפתיחה לספרו מורה הנבוכים<sup data-n=\"1450\">23</sup>, שהטעם שכתב ספרו זה, שיש בו \"ענינים נסתרים\", הוא \"אמרם<sup data-n=\"1451\">24</sup> בכמו זה הענין — עת<sup data-n=\"1452\">25</sup> לעשות לה' הפרו תורתך\", והיינו, דהיות בנ\"י במצב של \"נבוכים\" הכריח אותו לגלות \"ענינים נסתרים\" כדי להציל \"נבוכים\" בעניני אמונה כו'.\nועד\"ז הוא בנוגע לגילוי פנימיות ה­תורה בדורות האחרונים — שזהו בגדר \"עת לעשות לה' הפרו תורתך\": גודל ה­ירידה של הדורות האחרונים, שנתמעטו הלבבות וכו', וכן מצד מצב העולם ב­כללותו, שהרע בדורות אלה הוא בהת­גברות יתירה, מהווה הכרח רב לגלות זאת החכמה, פנימיות התורה, שהיא מעוררת את הכחות הפנימים הנסתרים שבנשמת האדם, הנותנים לו עזר וסיוע להתגבר על חשכת הגלות מבחוץ ועל המניעות שמבפנים, להתעורר באהבת ה' ויראתו כו' ולעבדו בלב שלם<sup data-n=\"1453\">26</sup>.\nב) מצינו כמה ענינים שבאים בתור הכנה לימות המשיח, ובלשון הרמב\"ם<sup data-n=\"1454\">27</sup> \"ליישר ישראל ולהכין לבם\" לימות ה­משיח, וכ\"ש וק\"ו שכן צ\"ל בנוגע לענינם העיקרי של ימות המשיח — \"לא נתאוו החכמים והנביאים ימות המשיח. . אלא כדי שיהיו פנויין בתורה וחכמתה\"<sup data-n=\"1455\">28</sup>, ש­יוכלו לעסוק בהשגת \"דעת בוראם\" — שצריכים \"ליישר ישראל ולהכין לבם\" לכך<sup data-n=\"1456\">29</sup>, וזהו על ידי גילוי פנימיות ה­תורה בדורות האחרונים דוקא.\nג. בהתאם להחילוק בין שני הביאו­רים בטעם גילוי פנימיות התורה בדורות האחרונים — ישנם שני אופנים גם באופן הגילוי, ע\"ד שני האופנים שבנגלה ד­תורה — משנה וגמרא:\nא) גילוי פנימיות התורה באופן שה­עיקר הוא ידיעת נקודת הענין בקיצור, ע\"ד לשון המשנה שהוא \"דבר<sup data-n=\"1457\">30</sup> קצר וכולל ענינים רבים\".\nב) הגילוי באופן מבואר ומוסבר ב­הרחבה, ע\"ד אריכות הביאור והשקו\"ט שבגמרא, ובלשון הזהר<sup data-n=\"1458\">31</sup> — \"יתפרנסון\",",[["1448","21","ל' הרמב\"ם הל' מלכים שם."],["1449","22","בהבא לקמן — ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151295\" data-slug=\"likkutei-sichot\" data-id=\"1300151295\">לקו\"ש חט\"ו ע' 282</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201172\" data-slug=\"likkutei-sichot\" data-id=\"1300201172\">ח\"כ ע' 172</a>. וש\"נ. ועוד."],["1450","23","ב\"צוואת זה המאמר\" בסופה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261032\" data-slug=\"likkutei-sichot\" data-id=\"1300261032\">לקו\"ש חכ\"ו ע' 32</a> ואילך."],["1451","24","גיטין ס, א."],["1452","25","תהלים קיט, קכו."],["1453","26","ראה בארוכה בזה — קונטרס עץ החיים (לכ\"ק אדמו\"ר (מהורש\"ב) נ\"ע) פי\"ג, ובמכתבו הנדפס בהוספה שם (ע' 82 ואילך). ועוד."],["1454","27","הל' מלכים פי\"ב ה\"ב (בנוגע לאליהו). וראה שם פי\"א ה\"ד (אלא שברוב הדפוסים נשמט ע\"י הצנזור) \"ליישר דרך למלך המשיח\" (אפילו ע\"י ענין שלילי ביותר, ועאכו\"כ — להבדיל — שכן צ\"ל בנוגע לחכמת התורה)."],["1455","28","ל' הרמב\"ם שם פי\"ב ה\"ד. ועד\"ז בהל' תשובה פ\"ט ה\"ב."],["1456","29","וי\"ל ההכרח \"ליישר ישראל ולהכין לבם\" למצב של ימוה\"מ — כי בלי הכנה זו, הרי שינוי עצום כזה באופן פתאומי ה\"ז בגדר ביטול \"מנהגו של עולם\", ולדעת הרמב\"ם גם לימות המשיח \"עולם כמנהגו נוהג\" (הל' מלכים רפי\"ב. ועד\"ז הל' תשובה ספ\"ט). ואכ\"מ."],["1457","30","ל' הרמב\"ם בהקדמתו לפירוש המשניות (ד\"ה אח\"כ ראה להסתפק — בתחלתו)."],["1458","31","תקו\"ז ת\"ו בסופו."]]],[1301410237,"וכמבואר במפרשי הזהר<sup data-n=\"1459\">32</sup>, דהיינו שעני­ני חכמת האלקות מפורשים ומוסברים בהבנה והשגה (לא כהלומד לגירסא), ש­אז הלימוד הוא בגדר \"פרנסה\", כמבואר בתניא<sup data-n=\"1460\">33</sup> שע\"י לימוד התורה \"היטב ב­עיון שכלו עד שנתפסת בשכלו ומתאח­דת עמו והיו לאחדים — נעשה מזון לנפש\".\n[ויש לומר, שבזה יש לתווך דברי אדמו\"ר הזקן אודות לימוד חכמת ה­קבלה, שנראים כסותרים לכאורה זא\"ז:\nאחז\"ל<sup data-n=\"1461\">34</sup> — וכן נפסק להלכה<sup data-n=\"1462\">35</sup> — ש­חייב אדם לשלש זמן לימודו — שליש במקרא שליש במשנה ושליש בתלמוד. ופסק אדה\"ז בהל' ת\"ת שלו<sup data-n=\"1463\">36</sup>, ד\"חכמת הקבלה תחשב בכלל שליש בתלמוד\" (ומיוסד על פסק הרמב\"ם<sup data-n=\"1464\">37</sup> ש\"הענינים הנקראים פרדס בכלל הגמרא הן\"); ואילו בספרו לקו\"ת<sup data-n=\"1465\">38</sup> מבאר אדה\"ז (וב­שקו\"ט ע\"ד הנגלה) \"דלימוד הזהר וכה­אריז\"ל הוא בכלל שליש במקרא\"<sup data-n=\"1466\">39</sup>, \"ש­הרי מדרש הזהר הוא על פסוקי ה­תורה<sup data-n=\"1467\">40</sup> ועוד שגם בלימוד רזין דאוריי­תא אינו משיג רק המציאות כו'\"<sup data-n=\"1468\">41</sup>, \"וה\"ז<sup data-n=\"1466\">39</sup> כעין לימוד המקרא שהוא קורא בשמותיו של הקב\"ה אע\"פ שאינו משיג כלל עצמיות הגנוז בהן. . וכעין זה הוא בלימוד הזהר וע\"ח\".\nוע\"פ הנ\"ל שיש שני אופנים בלימוד פנימיות התורה יש לתווך, שאם לומד<sup data-n=\"1470\">42</sup> רק נקודות הענינים (ע\"ד דברים קצרים שבמשנה) ה\"ז בכלל \"מקרא\"<sup data-n=\"1471\">43</sup>, משא\"כ כשלומד בהבנה והסברה ובפרטיות, וב­מיוחד — כשמשיג הענין ונתפס בשכלו ונעשו לאחדים<sup data-n=\"1472\">44</sup>, ה\"ז ע\"ד \"שליש ב­תלמוד\"<sup data-n=\"1473\">45</sup>, שהוא לימוד טעמי ההלכות",[["1459","32","כסא מלך לתקו\"ז שם. הקדמת מקדש מלך לזהר. — וראה ג\"כ שער ההקדמות (הנ\"ל הערה 7)."],["1460","33","פ\"ה (י, רע\"א)."],["1461","34","קידושין ל, א."],["1462","35","רמב\"ם הל' ת\"ת פ\"א הי\"א­יב. טושו\"ע יו\"ד סרמ\"ו ס\"ד. הל' ת\"ת לאדה\"ז פ\"ב ס\"א."],["1463","36","שם בסוף הסעיף."],["1464","37","הל' ת\"ת שם הי\"ב — \"לפ\"ד ש\"ך\" (ל' אדה\"ז שם) — ראה ש\"ך יו\"ד שם סק\"ו בנוגע ל­חכמת הקבלה (ובדרישה לטיו\"ד שם (שהובא בש\"ך) — ד\"פרדס. . חקירות עיונית אלקית\")."],["1465","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381140\" data-slug=\"likkutei-torah\" data-id=\"4001381140\">ויקרא — ביאור ד</a>\"ה ולא תשבית פ\"ד וה'. לקו\"ת שה\"ש ד\"ה לריח שמניך (הא') ספ\"ב. וראה גם ביאוה\"ז בראשית ב, ד (ולהצ\"צ שם — ע' תרכ)."],["1466","39","ל' הלקו\"ת שה\"ש <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381143\" data-slug=\"likkutei-torah\" data-id=\"4001381143\">שם (ג, סע\"ג</a>)."],["1467","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380097\" data-slug=\"likkutei-torah\" data-id=\"4001380097\">לקו\"ת שם (ויקרא ה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381143\" data-slug=\"likkutei-torah\" data-id=\"4001381143\">שה\"ש ג, סע\"ג</a>) בנוגע למדרש רבה כו' (והתיווך עם מ\"ש בהל' ת\"ת שם)."],["1468","41","ל' הלקו\"ת ויקרא <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380096\" data-slug=\"likkutei-torah\" data-id=\"4001380096\">שם (ה, רע\"ג</a>)."],["1466","39","ל' הלקו\"ת שה\"ש <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381143\" data-slug=\"likkutei-torah\" data-id=\"4001381143\">שם (ג, סע\"ג</a>)."],["1470","42","נוסף על החילוק אם לומד פירוש המקראות (שבספרי קבלה כו') — שזהו בכלל מקרא (ראה הערה 40), או ששקו\"ט בהבנה והסברה."],["1471","43","מכיון שיש בזה רק ידיעת המציאות לחוד (משא\"כ ידיעת ההלכות שבמשנה) — כנ\"ל בפנים מלקו\"ת (ע\"ש באורך).\nוע\"פ המבואר בפנים י\"ל, שאפשר להיות ג\"כ לימוד פנימיות התורה ע\"ד לימוד הלכות פסוקות שבמשנה ותלמוד — שליש במשנה."],["1472","44","ועפ\"ז, רק \"לימוד הזהר וע\"ח\" (בפ\"ע) הוא בכלל ה\"שליש במקרא\" — כי בספרים אלו עצמם אין ביאור והסברה בהרחבה כו' (משא\"כ כפי ש­עניני פנימיות התורה נתבארו בתורת חסידות חב\"ד, ע\"י משלים וכו').\nאלא שצע\"ק, כי בלקו\"ת שם משמע, שזה גופא שאין בזה השגת המהות אלא ידיעת המציאות לבד ה\"ה בכלל מקרא, והרי הגבלה זו היא \"אפילו ל­גדולי החכמים\" (לקו\"ת שה\"ש שם). ואכ\"מ."],["1473","45","ועפ\"ז צ\"ל לכאורה, דמ\"ש הרמב\"ם (כנ\"ל) ש\"הענינים הנקראים פרדס בכלל הגמרא הן\" — זהו רק כשלומדם בהבנה והסברה ובפרטיות<sup data-n=\"e40\">*</sup>, משא\"כ כשלומד רק נקודות הענינים בכללות* ה\"ז בכלל מקרא (או משנה — ראה הערה 43)."],["e40","*","כמשנ\"ת במק\"א (\"הדרן על הרמב\"ם\" (קה\"ת, תשמ\"ה) הערה 6. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261005\" data-slug=\"likkutei-sichot\" data-id=\"1300261005\">לקו\"ש חכ\"ו ע' ה</a>­חילוק בין \"לטייל בפרדס\" (ל' הרמב\"ם הל' יסוה\"ת ספ\"ד) ו\"נכנסו לפרדס\". ע\"ש."]]],[1301410238,"כו', עד ללימוד בעיון להבין דבר מתוך דבר וכו'<sup data-n=\"1474\">*45</sup>].\nוי\"ל ששני אופנים אלו באופן הלי­מוד, תלויים בב' הטעמים הנ\"ל על גילוי פנימיות התורה בדורות האחרונים<sup data-n=\"1475\">46</sup>:\nע\"פ הטעם משום \"עת לעשות לה'\", בשביל פיקוח נפש (ברוחניות), מפני הת­גברות החושך וירידת הדורות — מספיק גילוי פנימיות התורה באופן של נקודות ובקיצור בתכלית, כי גם \"נקודה\" של פנימיות התורה, \"המאור שבה\"<sup data-n=\"1476\">47</sup>, בכחה להחיות נפשות (וכיון שזה מספיק — הרי אין לגלות יותר);\nמשא\"כ גילוי פנימיות התורה כדי \"ליישר ישראל ולהכין לבם\" לגילוי פנימיות התורה שיהי' \"באותו הזמן\" — הרי כיון שאז תהי' השגה גמורה בידיעת השם, \"כפי כח האדם\"<sup data-n=\"1477\">48</sup> ועד \"כמים לים מכסים\", הרי מובן, שגם ההכנה לזה בדורות האחרונים צ\"ל ע\"ד זה דוקא.\nד. ע\"פ כל הנ\"ל יתבאר היטב הסי­פור הנ\"ל אודות הקטרוג ע\"ז שרבינו הז­קן אמר דברי חסידות בריבוי כו':\nהחידוש באופן גילוי החסידות על ידי רבינו הזקן לגבי הבעש\"ט והמגיד ותלמידיהם — יש לראות בפשטות כש­לומדים תורת החסידות שנתגלתה לנו, שעניני חסידות שנתגלו ע\"י הבעש\"ט וה­מגיד ותלמידיהם הם באופן של \"נקו­דות\" ובקיצור, ע\"ד לשון המשנה שהיא דבר קצר, משא\"כ ביאור הענינים שב­תורת חסידות חב\"ד שנתגלה על ידי רבינו הזקן הוא באופן של \"הרחבה\" ושקו\"ט, שבמאמרי ותורת חסידות שלו (החל מספר התניא) ביאר עניני תורת החסידות באופן של הבנה והשגה, וכ­שמה — \"חסידות חב\"ד\".\nושינוי זה באופן גילוי תורת החסי­דות, י\"ל שהוא שגרם לקטרוג החדש על רבינו הזקן, גם לאחרי שנתבטל הקטרוג על המגיד על ידי הסברת המשל מ­שחיקת אבן יקרה שבכתר המלך בשביל הצלת חיי בן המלך.\nובביאור יותר:\nבמשל רבינו הזקן ע\"ד הצלת חייו של בן המלך ע\"י שחיקת האבן הטובה שבכתר המלך — מודגש הצורך שתכנס לכה\"פ \"טיפה אחת\" לפיו של בן המלך, אשר טיפה זו תציל את חייו של בן המלך.\nודוגמתו בנמשל — גילוי החסידות (פנימיות התורה, האבן הכי יקרה שב­כתר המלך) עכ\"פ באופן של נקודה (\"טיפה אחת\"), וכנ\"ל, שגם נקודה אחת של פנימיות התורה יש בכחה להחיות את בן המלך.\nוראי' לדבר — גילוי החסידות באופן של נקודה, ע\"י הבעש\"ט והמגיד ותלמי­דיהם ותלמידי תלמידיהם לדורותם — הועיל ופעל להחיות את בן המלך, ו­העמיד יראים ושלמים לאלפים ולרבבות כו'.\nאבל כאשר רבינו הזקן התחיל לגלות את תורת החסידות (לא רק באופן של",[["1474","*45","ראה רמב\"ם ואדה\"ז (ובקו\"א) הל' ת\"ת שם."],["1475","46","להעיר גם ממשנ\"ת בד\"ה וכל בניך תשמ\"א פ\"ז (סה\"מ מלוקט ח\"ב ע' קצד­ה) בביאור שני הענינים בלימוד פנימיות התורה — (א) שמביאה ללב שלם, בירור המדות; (ב) הלימוד והידיעה ד­פנימיות התורה מצד עצמו (שלמעלה מבירורים). ע\"ש."],["1476","47","פתיחתא לאיכ\"ר ב. ירושלמי חגיגה פ\"א ה\"ז (ובקרבן העדה שם (וכן ביפה ענף לאיכ\"ר) — שקאי על \"סודות החכמה\")."],["1477","48","ל' הרמב\"ם הל' מלכים ספי\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271255\" data-slug=\"likkutei-sichot\" data-id=\"1300271255\">לקו\"ש חכ\"ז ע' 241</a>."]]],[1301410239,"נקודה, \"טיפה אחת\", אלא) באופן של הרחבה, ע\"י תורת חב\"ד — אזי נתחדש הקטרוג למעלה, שהרי גילוי החסידות באופן של הרחבה, בהבנה והשגה ד­תורת חב\"ד אינו (לכאורה) דבר המוכרח להצלת חייו של בן המלך.\nוי\"ל שזהו הטעם שנתעורר ספק אצל רבינו הזקן שאולי צריך להפסיק מגילוי דברי חסידות באופן כזה, וע\"ז הורו לו רבותיו, שע\"י מסירת נפשו וישיבתו במאסר פעל למעלה<sup data-n=\"1478\">49</sup> שיוכל להמשיך לגלות דברי חסידות באופן של הרחבה, \"ואדרבה, לכשתצא תאמר יותר\" — כדי \"ליישר ישראל ולהכין לבם\" לגילוי \"סוד טעמי' ומסתר צפונותי'\"<sup data-n=\"1479\">50</sup> של תורה שיתגלו בביאת המשיח ועד כמים לים מכסים.\nה. והמעשה הוא העיקר:\nלאחרי שניתנה ההוראה של הבעש\"ט והמגיד לרבינו הזקן, שלא זו בלבד שלא יפסיק ח\"ו מלומר דברי חסידות, אלא אדרבה, שיוסיף עוד יותר — הרי מובן, שזוהי הוראה לכאו\"א מישראל, שחייב להכין את עצמו ל\"אותו הזמן\" ש\"לא יהי' עסק כל העולם אלא לדעת את ה' בלבד\" — על ידי לימוד פנימיות התורה באופן של הבנה והשגה דוקא.\nומזה מובן, שגם מי שלפי דעתו לי­מוד פנימיות התורה, ובפרט באופן של \"חב\"ד\" (לימוד בהרחבה, הבנה והשגה, \"יתפרנסון\"), אינו מוכרח להחיות נפשו — כי לדעתו<sup data-n=\"1480\">51</sup> אין חייו הרוחניים עומ­דים בסכנה ח\"ו, ודי ומספיק עבורו לי­מוד נגלה דתורה ולימוד דברי מוסר ו­לימוד דברי חסידות של הבעש\"ט וה­מגיד ותלמידיהם ותלמידי תלמידיהם, כדי להתגבר על החושך כפול ומכופל דעקבתא דמשיחא — איך יפטור עצמו מלימוד זה, כשפסק דין ברור הלכה למעשה בנגלה דתורה (בהלכות ת\"ת של \"הרב\", אדמו\"ר הזקן<sup data-n=\"1481\">52</sup>) שכל נפש מישר­אל חייב ללמוד כל התורה כולה, \"הן בפשטי ההלכות הן ברמזים ודרשות וסודות\" (ויתירה מזה מ\"ש במק\"א<sup data-n=\"1482\">53</sup> שכל נפש מישראל מחוייב \"לחדש שכל חדש הן בהלכות הן באגדות הן בנגלה הן בנסתר\"<sup data-n=\"1483\">54</sup>).\nועל ידי \"יפוצו מעינותיך חוצה\" — פירסום והפצת מעיינות החסידות, בכל מקום ומקום, עד שיגיעו גם חוצה — נזכה בקרוב (כהבטחת מלך המשיח לה­בעש\"ט<sup data-n=\"1484\">55</sup>) לקאתי מר דא מלכא משיחא, שאז יקויים היעוד<sup data-n=\"1445\">18</sup> \"כי מלאה הארץ דעה את ה' כמים לים מכסים\", ובמהרה בימינו ממש.\n<span data-k=\"q\">(משיחות מוצש\"ק מקץ ומוצאי זאת חנוכה תשמ\"ו) </span>",[["1478","49","ראה אגרות קודש אדמו\"ר מהוריי\"צ ח\"א ע' קמז (נדפס ג\"כ בהוספה לקונטרס החלצו — תרנ\"ט)."],["1479","50","ל' רש\"י שה\"ש א, ב."],["1480","51","אבל ממשנ\"ת במקומות שבהערה 26 מובן, שמפני ירידת הדורות (גם לגבי דור אדה\"ז כו'), הרי עתה מוכרח לימוד פנימיות התורה באופן של דעת גם כדי לעבדהו בלב שלם. ע\"ש."],["1481","52","פ\"א ס\"ד. וש\"נ (וע\"ש עד היכן הדברים מגיעים)."],["1482","53","תניא אגה\"ק סכ\"ו (קמה, א)."],["1483","54","שמזה מובן שגם הנסתר צריכים ללמוד באופן של חב\"ד, דאל\"כ אא\"פ \"לחדש שכל חדש\", כפשוט."],["1484","55","אגה\"ק המפורסמת דהבעש\"ט — נדפסה בריש ס' כתר שם טוב. ובכ\"מ."],["1445","18","ישעי' יא, ט."]]],[1301410240,"<h3>שיחה א</h3>\nא. דובר כמה פעמים<sup data-n=\"1486\">1</sup> ע\"ד שמות פרשיות התורה, דזה שכל פרשה נקראת (ע\"פ מנהג ישראל, דתורה הוא) בשם מסויים, הוא לא (רק) משום שהתחלתה היא בתיבה זו (שנקבעה להיות שמה), אלא לפי שבשם זה נרמז גם תוכן ה­פרשה<sup data-n=\"1487\">2</sup>. וכמו שם כל דבר שנקרא בו בלשון הקודש, שהוא חיות הדבר ההוא ומורה על תוכן הדבר שנקרא בשם זה<sup data-n=\"1488\">3</sup>.\nומובן שכן הוא גם בנוגע לפרשתנו, דשמה אשר יקראו לה ע\"פ מנהג ישראל הוא \"וישב\"<sup data-n=\"1489\">4</sup> — שצ\"ל שבו מרומז תוכנה של פרשה זו.\nוצריך להבין: \"וישב\" פירושו — הת­יישבות באופן של שלווה ומנוחה, וכדרשת חז\"ל<sup data-n=\"1490\">5</sup> בריש פרשתנו \"וישב — בקש<sup data-n=\"1491\">6</sup> יעקב לישב בשלוה\"<sup data-n=\"1492\">7</sup>; ואילו תוכ­נה של הפרשה הוא בענין מכירתו של יוסף, שהפריעה ושללה את \"וישב יעקב\", את מנוחתו ושלוותו של יעקב, וכדרשת חז\"ל הנ\"ל \"בקש יעקב כו' קפץ עליו רוגזו של יוסף\".\nב. ויובן זה בהקדים ביאור מחז\"ל הנ\"ל \"ביקש<sup data-n=\"1491\">6</sup> יעקב לישב בשלוה קפץ עליו<sup data-n=\"1494\">8</sup> רוגזו של יוסף, צדיקים מבקשים לישב בשלוה אמר הקב\"ה לא דיין ל­צדיקים מה שמתוקן להם לעולם הבא אלא שמבקשים לישב בשלוה בעוה\"ז\".\nהפירוש במאמר זה לפי מפרשי המד­רש (ורש\"י) הוא<sup data-n=\"1495\">9</sup>, דזה ש\"ביקש יעקב לי­שב בשלוה\" היא הסיבה שבגללה \"קפץ עליו רוגזו של יוסף\". כלומר, אין כוונת חז\"ל רק להשמיענו שלא נתקיים מבו­קשו של יעקב לישב בשלוה — כי קפץ עליו רוגזו של יוסף, אלא יתירה מזו: \"קפץ עליו רוגזו של יוסף\" הוא תוצאה מזה ש\"ביקש יעקב לישב בשלוה\". וכ­מפורש במדרש<sup data-n=\"1496\">10</sup> \"יעקב אבינו ע\"י ש­בקש",[["1486","1","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051057\" data-slug=\"likkutei-sichot\" data-id=\"1300051057\">לקו\"ש ח\"ה ע' 57</a> ואילך ובהערות שם."],["1487","2","ואחת ההוכחות לזה — בפשטות: פרשה ש­תחלתה \"אלה תולדות נח\" נקראת \"נח\", ופ' אחרת שתחלתה \"ואלה תולדות יצחק\" נקראת \"תולדות\" (וראה לקו\"ש שבהערה 4). ולכאורה — באם נאמר ששמות הפרשיות הם רק על שם התחלתן — הרי פ' \"אלה תולדות נח\" מכיון שהיא הראשונה המתחילה \"אלה תולדות\" הוצרכה להקרא בשם \"תולדות\" (מכיון שתיבת \"תולדות\" היא לפני תיבת \"נח\") ופ' \"ואלה תולדות יצחק\" שלאחרי' המתחילה ג\"כ בתיבת \"תולדות\" — בשם \"יצחק\" (כדי להבדילה מפ' אלה תולדות נח)? ומזה מובן ששם שתי הפרשיות הוא (גם) ע\"ש תוכנן, ולכן נקראת הפרשה הראשונה בשם \"נח\" והשני' — \"תולדות\" — כי שמות אלה מורים על תוכנן, כמבואר במקום אחר."],["1488","3","ראה אור תורה להה\"מ ס\"פ בראשית (ד, סע\"ב ואילך) ולקו\"א להה\"מ סרמ\"ד (הוצאת קה\"ת). <a class=\"ft-cite\" href=\"#/read/tanya/3401310060\" data-slug=\"tanya\" data-id=\"3401310060\">תניא</a> שער היחוד והאמונה פ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380254\" data-slug=\"likkutei-torah\" data-id=\"4001380254\">לקו\"ת בהר מא, ג</a>. ובכ\"מ."],["1489","4","ברמב\"ם (בסוף ספר אהבה ב)סדר תפלות \"וישב יעקב\". אבל כבר נתבאר כמ\"פ שרוב ה­פרשיות ברמב\"ם שם נק' בב' תיבות. ועד\"ז רוב שמות הפרשיות שהובאו בסידור הרס\"ג \"קריאת התורה\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211146\" data-slug=\"likkutei-sichot\" data-id=\"1300211146\">לקו\"ש חכ\"א ע' 146</a> הערה 6. ואכ\"מ."],["1490","5","ב\"ר פפ\"ד, ג. פרש\"י ריש פרשתנו לז, ב: ועוד נדרש בו."],["1491","6","לשון רש\"י שם."],["1492","7","ראה רא\"ם (ועד\"ז בגו\"א ועוד) דפי' וישב יעקב, היינו דביקש \"להתיישב ולנוח מהצער כו'\"."],["1491","6","לשון רש\"י שם."],["1494","8","וצ\"ע שרוגזו של יוסף קפץ לאחרי כתשע שני שלוה! וראה לקמן ס\"ו."],["1495","9","וראה גם כלי יקר ואוה\"ח ריש פרשתנו."],["1496","10","ב\"ר שם."]]],[1301410241,"לישב בשלוה בעוה\"ז נזדווג לו שטנו של יוסף\"<sup data-n=\"1497\">11</sup>.\nאבל אין זה מחוור בלשון חז\"ל הנ\"ל. כי אף שהלשון \"בקש יעקב כו' קפץ עליו כו'\" בנוגע ליעקב, הי' אפשר ל­פרשו (בדוחק עכ\"פ) שהבקשה היתה חסרון וכעין חטא, הרי המשך הלשון \"צדיקים מבקשים לישב בשלוה\" משמעו, שזהו המבוקש של צדיקים בכלל — ומ­כיון שנקראים בשם \"צדיקים\", פשיטא שהכוונה לצדיקים אמיתיים שאין בהם חטא ועון ח\"ו — וא\"כ איך יתכן שבמבו­קשם של הצדיקים (\"לישב בשלוה\") יהי' ענין של חטא וחסרון?!\n— לפי הגירסא במדרש<sup data-n=\"1496\">10</sup> \"בשעה שה­צדיקים יושבים בשלוה ומבקשים לישב בשלוה בעולם הזה השטן בא ומקטרג אמר לא דיין כו'\", אולי אפשר לפרש שאין המדובר בתור כלל לכל הצדיקים, אלא רק בנוגע צדיקים מסויימים — שב­שעה שיושבים בשלוה ומבקשים (להמ­שיך) לישב בשלוה, אז \"השטן בא כו'\"<sup data-n=\"1499\">12</sup>, אבל לפי הגירסא הנ\"ל<sup data-n=\"1500\">13</sup> \"צדיקים מבק­שים לישב בשלוה\" — משמעות הענין היא, שזוהי הנהגתם של צדיקים בכלל.\nועם היות שמצינו בתורה ענין של חטא — עכ\"פ \"חטא\" בדקות — גם אצל צדיקים — מ\"מ, נוסף לזה שאין זו מילתא דשכיחא בצדיקים [ועאכו\"כ ב­נוגע ליעקב, בחור שבאבות<sup data-n=\"1501\">14</sup>, נוסף לזה שבכלל — האבות הן הן המרכבה<sup data-n=\"1502\">15</sup>, ו­מפורש בחז\"ל<sup data-n=\"1503\">16</sup> שהאבות לא שלט בהן יצר הרע] — הרי מובן שלא יתכן לומר, שזהו מבוקשם הרגיל של צדיקים, רגי­לין להתנהג באופן בלתי רצוי!\nועכצ\"ל, דזה ש\"צדיקים מבקשים לישב בשלוה\" אינו ענין שלילי, היפך הרצוי, אלא אדרבה — הנהגה המתאימה לצדיק וחלק משלימות עבודתו.\nולפ\"ז צריך ביאור לאידך גיסא — מאחר שזוהי הנהגה מתאימה לצדיקים (היינו שזהו בהתאם לרצונו של הקב\"ה), מדוע \"אמר הקב\"ה לא דיין לצדיקים מה שמתוקן להם לעוה\"ב אלא שמבקשים לישב בשלוה בעוה\"ז\" (שאין הקב\"ה ממלא מבוקשם לישב בשלוה, ואדרבא בא הפכו צרה ורוגז, וכמו שמצינו ב­יעקב ש\"קפץ עליו רוגזו של יוסף\")?\nג. ולהוסיף:\nלפי גירסת המדרש \"בשעה שהצדי­קים יושבים בשלוה כו' השטן בא ומ­קטרג כו' תדע לך כו' יעקב אבינו ע\"י שבקש כו' נזדווג לו שטנו של יוסף\" — יש לתרץ, דזה ש\"נזדווג לו שטנו של יוסף\" לא בא כעין עונש על מבוקש בלתי רצוי, אלא רק מצד קטרוגו של השטן.\nוכמו שמצינו כמ\"פ ענין של קטרוג",[["1497","11","ואף שהי' צ\"ל פרעון שטר חוב דבברית בין הבתרים (כמו שהביא רש\"י בפ' וישלח לו, ז) — הרי אין הכרח שיהי' ע\"י \"רוגזו של יוסף\". וכן זה שיעקב נענש שפירש יוסף מאביו כ\"ב שנה כנגד כ\"ב שנה שלא קיים יעקב כבוד או\"א (מגילה יז, א. פרש\"י פרשתנו לז, לד. רש\"י ישן ס\"פ תולדות) — ה\"ז טעם רק על עצם הפרשתו מאביו, אבל לא על ה\"רוגז\", הצער שהי' קשור לזה, עד שיעקב לא הי' יודע שיוסף חי — ראה מפרשי רש\"י פרשתנו שם, לג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101130\" data-slug=\"likkutei-sichot\" data-id=\"1300101130\">לקו\"ש ח\"י ע' 130</a>, 133 ואילך. וש\"נ."],["1496","10","ב\"ר שם."],["1499","12","כן פי' ביפה תואר (השלם) ונזר הקודש (השלם) לב\"ר שם. ועוד."],["1500","13","שבפרש\"י. וראה חילופי נוסחאות בב\"ר הוצאת תיאדור."],["1501","14","ב\"ר רפע\"ו. וראה גם זהר פרשתנו קפ, א. ועוד."],["1502","15","ב\"ר פמ\"ז, ו. פפ\"ב, ו. ועוד."],["1503","16","ב\"ב יז, רע\"א."]]],[1301410242,"השטן כגון דא — כמו בקטרוג השטן<sup data-n=\"1504\">17</sup> על אברהם ש\"מכל<sup data-n=\"1505\">18</sup> סעודה שעשה אברהם לא הקריב לפניך פר אחד כו'\", שזהו גרם לנסיון העקידה (\"א\"ל (הקב\"ה) כלום עשה אלא בשביל בנו אלו הייתי אומר לו זבח אותו לפני לא הי' מעכב\") — שמובן שלא הי' כאן דבר בהנהגת אברהם בפועל היפך הרצוי, וכל הענין נגרם על ידי קטרוג השטן.\nוכן בעניננו, שלפי המדרש יתכן לו­מר, דבקשתו של יעקב לישב בשלוה גרמה לקטרוג השטן, ולכן \"נזדווג לו שטנו של יוסף\"<sup data-n=\"1506\">19</sup>.\nמשא\"כ לפי הנוסח \"אמר הקב\"ה לא דיין לצדיקים כו'\" — מובן (שאין זה בא רק מחמת קטרוג השטן, אלא) שזוהי טענת הקב\"ה על הצדיקים.\nד. ויש לומר הביאור בזה<sup data-n=\"1507\">20</sup>:\nבקשתם של צדיקים \"לישב בשלוה\" — היינו בשלוה שלימה ואמתית. כי אין כוונתם (רק) לשלוה גשמית וגופנית, אלא לשלוה רוחנית, ע\"ד השלוה שב­עוה\"ב ש\"אין בו לא אכילה ולא שתי' כו' צדיקים יושבין כו' ונהנים מזיו השכי­נה\"<sup data-n=\"1508\">21</sup>. ולכן \"אמר הקב\"ה לא דיין ל­צדיקים מה שמתוקן להם לעוה\"ב אלא שמבקשים לישב בשלוה בעוה\"ז\".\nואף שמקומה וזמנה של שלוה כזו (יושבין ונהנין מזיו השכינה, ללא כל עבודה) הוא דוקא בעוה\"ב — משא\"כ בעוה\"ז הרי \"היום לעשותם\" כתיב<sup data-n=\"1509\">22</sup>, והיינו שכל רגע צ\"ל (לא \"שלוה\" אלא) עבודה\n[ויתירה מזו: שלימות העבודה היא — העבודה מאהבה, שאינו עובד את ה' \"מפני<sup data-n=\"1510\">23</sup> דבר בעולם. . ולא כדי לירש הטובה (גם לא \"כדי שאזכה לחיי העולם הבא\"<sup data-n=\"1511\">24</sup>) אלא עושה האמת מפני שהוא אמת\"]\nהרי בקשתם של צדיקים לישב ב­שלוה אינה לשם השלוה עצמה (קיבול שכר), אלא כדי שעל ידה יוכלו להוסיף בעבודתו ית' עד שתגיע לתכלית השלי­מות. ע\"ד מ\"ש הרמב\"ם<sup data-n=\"1512\">25</sup> דמה ש\"נתאוו כל ישראל נביאיהם וחכמיהם לימות ה­משיח\" הוא \"כדי שינוחו ממלכיות שאינן מניחות להם לעסוק בתורה ומצות כהוגן וימצאו להם מרגוע וירבו בחכמה\".\nוזהו הפירוש ש\"צדיקים מבקשים לישב בשלוה\", כלומר, שהם מתאווים למצב של שלוה כדי שיוכלו לעבוד ה' מתוך מנוחה; ומה שהקב\"ה אומר \"לא דיין לצדיקים כו'\" אין זה משום שהיא בקשה בלתי רצוי', אלא מפני שג\"ז — מצב של עבודת ה' מתוך מנוחה — הוי כעין קיבול שכר הבא רק לאחרי תכלית השלימות בעבודת ה'.\nוכן הוא ביעקב, שבבקשתו לישב בשלוה נתכוון לשלוה שלמה רוחנית שיוכל לעבוד השם מתוך מנוחה. וזה ש\"קפץ עליו רוגזו של יוסף\" הוא מפני שבמעמדו ומצבו אז לא הי' ראוי עדיין לשלוה זו; אמנם, סו\"ס נתקיימה בקשתו",[["1504","17","ובב\"ר (פנ\"ה, ד) איתא \"מלאכי השרת אמרו כו'\"."],["1505","18","פרש\"י וירא כב, א. מסנהדרין פט, ב."],["1506","19","אבל ראה יפ\"ת השלם שם."],["1507","20","בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151323\" data-slug=\"likkutei-sichot\" data-id=\"1300151323\">לקו\"ש חט\"ו ע' 310</a> ואילך."],["1508","21","ברכות יז, א. רמב\"ם הל' תשובה פ\"ח ה\"ב."],["1509","22","עירובין כב, א. וש\"נ. רש\"י ס\"פ ואתחנן."],["1510","23","רמב\"ם הל' תשובה פ\"י ה\"ב."],["1511","24","רמב\"ם שם ה\"א."],["1512","25","שם ספ\"ט. וראה הל' מלכים פי\"ב ה\"ד. פיהמ\"ש סנהדרין הקדמה לפ' חלק."]]],[1301410243,"לישב בשלוה (גם בעוה\"ז) — לאחרי גמר הזמן ד\"רוגזו של יוסף\" ישב בשלוה גם בעוה\"ז, דזהו מה שאמר הכתוב<sup data-n=\"1513\">26</sup> \"ויחי יעקב בארץ מצרים שבע עשרה שנה\", שהיו שנות שלוה ומנוחה<sup data-n=\"1514\">27</sup>.\nה. ויש לומר בעומק יותר — וב­הקדם:\nלפי הנ\"ל שזה שלא ישב בשלוה ש­ביקש הוא מפני שלא הי' ראוי לה אז — עדיין אינו מובן: למה קפץ עליו \"רוגזו של יוסף\"<sup data-n=\"1515\">28</sup>, צרה חדשה וצרה גדולה כזו שגרמה ליסורים גדולים בערך ל­הצער והדוחק דצרת לבן וצרת עשו כו'<sup data-n=\"1516\">29</sup>?\nאך הענין הוא:\nזה גופא שיעקב זכה בסוף ימיו ל\"שלוה בעוה\"ז\" הוא מפני ש\"קפץ עליו רוגזו של יוסף\" (וכנ\"ל (סעיף ב), דזה שהקב\"ה הביא עליו \"רוגזו של יוסף\" ה\"ז תוצאה מבקשתו של יעקב לישב בשלוה). כלומר: כדי להעלות את יעקב למדריגה נעלית יותר בעבודת השם, עד שיהי' ראוי לישב בשלוה בעוה\"ז, הביא הקב\"ה עליו את \"רוגזו של יוסף\", וכ­ידוע, שהעבודה מתוך צרה וצער כו' מזככת ומעלה את האדם<sup data-n=\"1517\">30</sup> למדריגות גבוהות ביותר בעבודת השם; וכן בעני­ננו, שדוקא ע\"י עבודתו של יעקב במצב של \"רוגזו של יוסף\" זכה לישב בשלוה בעוה\"ז (\"ויחי יעקב בארץ מצרים שבע עשרה שנה\").\nועפ\"ז יש ליישב השאלה דלעיל (סעיף א) — מדוע נקראת הפרשה בשם \"וישב\" המורה על ישיבה בשלוה, אף שתוכנה (ותיכף מהתחלתה — \"יוסף<sup data-n=\"1518\">31</sup> בן שבע עשרה שנה הי' רועה גו'\") הוא\nע\"ד \"רוגזו של יוסף\" (היפך \"וישב\" — שלוה)—\nכי מכיון שעבודתו של יעקב מתוך המיצר של \"רוגזו של יוסף\" היא היא שהביאה לקיום בקשתו \"לישב בשלוה\" (כנ\"ל), נמצא, שתוכנה האמיתי של פרשה זו הוא — \"וישב יעקב\" (שלוותו של יעקב), מאחר ש\"רוגזו של יוסף\" אינו אלא הכנה והקדמה שהביאה לשלוה ד\"ויחי יעקב בארץ מצרים שבע עשרה שנה\".\nו. אמנם עדיין צריך להבין:\nמובן ופשוט, שהענין הנ\"ל (ששלימות השכר דשלוה רוחנית באה אחרי שלי­מות העבודה) הי' ידוע גם ליעקב. ומ­כיון שמדתו של יעקב היא מדת האמת (כידוע<sup data-n=\"1519\">32</sup>) — הרי ברור שיעקב הכיר מצבו ומדריגתו בעבודת השם כפי שהוא באמת, ומאחר שביקש לישב בשלוה, עכצ\"ל שמצד מעמדו ומצבו אז כבר הי' ראוי באמת לשלוה זו (כי לאחרי כל היסורים שעברו עליו ע\"י הצרות וה­הרפתקאות של לבן ועשו וצרת דינה וכו'<sup data-n=\"1516\">29</sup>, הרי הוא ראוי לעבוד עבודתו בשלימות מתוך שלוה).",[["1513","26","ר\"פ ויחי."],["1514","27","ראה זהר פרשתנו קפ, סע\"א. זח\"א רטז, ב. וראה גם בעה\"ט עה\"פ."],["1515","28","ראה לעיל הערה 11."],["1516","29","ראה ב\"ר כאן. פרש\"י מקץ מג, יד. וראה נזר הקודש השלם לב\"ר שם ד\"ה לא שלותי."],["1517","30","להעיר ממרז\"ל (ראה מנחות נג, ב. שמו\"ר פל\"ו, א) הזית כשכותשין אותו מוציא שמנו — הובא ע\"י כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע (תורת שלום ע' 26) לענין מאסר וגאולת אדה\"ז בי\"ט כסלו (דאזלינן מיני'). וראה לקו\"ד ח\"א צד, א ואילך."],["1518","31","משא\"כ הפסוק שלפניו — ראה לעיל הערה 8."],["1519","32","זח\"א קלט, סע\"א. קסא, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא ספי\"ג</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261008\" data-slug=\"likkutei-sichot\" data-id=\"1300261008\">לקו\"ש חכ\"ו ע' 8</a>. וש\"נ."],["1516","29","ראה ב\"ר כאן. פרש\"י מקץ מג, יד. וראה נזר הקודש השלם לב\"ר שם ד\"ה לא שלותי."]]],[1301410244,"ומכיון שכן — טעמא בעי: מדוע ב­אמת הוצרך עוד ל\"רוגזו של יוסף\" כדי שיוכל לזכות לענין השלוה?\nויש לומר נקודת הביאור בזה:\n\"שלוה\" זו שאותה ביקש יעקב אינה אותה השלוה שניתנה לו ע\"י ש\"קפץ עליו רוגזו של יוסף\". כי כנ\"ל, בקשתו של יעקב לישב בשלוה הי' (לא בתור קיבול שכר, מכיון ש\"היום לעשותם\" כתיב, אלא) רק שיוכל לעבוד את ה' מתוך מנוחה, ולשלוה כזו כבר אז הי' ראוי ע\"י עבודתו הקודמת.\nויתירה מזו: לפי חשבון השנים<sup data-n=\"1521\">33</sup> ש­הי' יעקב בארץ כנען נמצא, שעד ש\"קפץ עליו רוגזו של יוסף\" (בהיות יוסף בן שבע עשרה שנה) היו ליעקב תשע שנים של שנות שלוה בארץ מגורי אביו<sup data-n=\"1522\">34</sup>. וי\"ל שהיא היא השלוה שביקש יעקב<sup data-n=\"1523\">35</sup>.\nאבל, הקב\"ה רצה שיעקב יזכה לשל­וה בשלימותה, \"עולמך תראה בחייך\"<sup data-n=\"1524\">36</sup>, שגם בעוה\"ז יזכה למצב של עוה\"ב. ושלוה זו ניתנה ליעקב רק לאח\"ז, כאשר \"ויחי יעקב בארץ מצרים שבע עשרה שנה\" (שבא ע\"י \"רוגזו של יוסף\").\n[וי\"ל שפרט זה נרמז גם במנהג ישראל ששם הפרשה הוא \"וישב\" (סתם), ולא \"וישב יעקב\": תוכן הפרשה הוא אמנם ענין של התיישבות (\"וישב\") ו­שלוה, כי \"רוגזו של יוסף\" הוא שהביא לשלוותו של יעקב אבל בארץ מצרים; אין זו השלווה שיעקב השתוקק לה ו­ביקש עלי' (\"וישב יעקב\"), שכן מבוקשו הי' לישב בשלוה בארץ מגורי אביו, ואילו זה ש\"קפץ עליו רוגזו של יוסף\" גרם והביא \"וישב\" סתם — שלוה סתם, שהיא חיי עוה\"ב, שזכה לה כאשר \"ויחי יעקב בארץ מצרים\" דוקא].\nז. ביאור הענין:\nההבדל בין שני אופני השלוה הנ\"ל הוא: השלוה שביקש יעקב היא שלוה שבגדר הנבראים, שלוה כזו שבכחם של בנ\"א להגיע אלי', ובמילא — לבקש אותה<sup data-n=\"1525\">37</sup>; ואילו הקב\"ה נתן ליעקב שלוה כזו שאינה בגדר הנבראים ואין בכח הנברא להגיע אלי' בכח עצמו.",[["1521","33","ראה רש\"י (ורש\"י ישן) ס\"פ תולדות. רש\"י ויצא ל, כה; וישלח לג, יז; פרשתנו לז, לד."],["1522","34","ראה פרקי דר\"א פל\"ח. ב\"ר פפ\"ד, ה (בסופו)."],["1523","35","ע\"פ המבואר בפנים בטלה התמי' במחז\"ל זה \"בקש יעקב לישב בשלוה קפץ עליו רוגזו של יוסף\" — שלפי המפרשים הכוונה שהקב\"ה לא הסכים לבקשתו של יעקב לישב בשלוה ולכן \"קפץ עליו רוגזו של יוסף\" — והרי היו לו תשע שנות שלוה בארץ כנען עד ש\"קפץ עליו רוגזו של יוסף\", כנ\"ל?\n— כי<sup data-n=\"e41\">*</sup> המטרה ד\"קפץ עליו רוגזו של יוסף\" לא היתה לשלול מיעקב השלוה בארץ מגורי אביו (ש­ביקש), כ\"א להגביהו לשלוה נעלית יותר. וכדי להדגיש זה, נתן לו הקב\"ה כמה שנות שלוה בארץ מגורי אביו עד שהביא עליו \"רוגזו של יוסף\".\n[ומובן ששתי השלוות צ\"ל מן הקל אל הכבד; וי\"ל גם — בתחילה שלוה בדוגמת ימוה\"מ, ואח\"כ — שלות עוה\"ב]."],["1524","36","ל' רז\"ל — ברכות יז, א. וראה ב\"ב (יז, רע\"א) שהאבות הטעימן מעין עוה\"ב."],["1525","37","כי אין מתריעין על מעשה ניסים (ירושלמי תענית פ\"ג ה\"ב. וראה ברכות ס, א)."],["e41","*","ע\"פ מ\"ש ברש\"י ישן ריש פרשתנו \"יעקב ראה כל האלופים הכתובים למעלה תמה ואמר מי יכול לכבוש את כולן. . יוסף\" (וראה גם רש\"י ויצא ל, כה) — י\"ל (ע\"ד הרמז עכ\"פ) שטענת הקב\"ה היא, שיעקב הי' צריך לעסוק בכיבוש אלופי עשו ולא \"לישב בשלוה\". אלא שכ\"ז שיוסף (\"שטנו של עשו\" — פרש\"י ויצא שם) הי' קטן בשנים אינו בידו, אבל כשגדל ונעשה בן י\"ז שנה \"קפץ עליו כו'\" (ועפ\"ז יומתק הא ששלילת שלוותו של יעקב היא ע\"י \"רוגזו של יוסף\" דוקא, מדה כנגד מדה, שלא עסק בכיבוש אלופי עשו ע\"י יוסף)."]]],[1301410245,"וע\"ד שהוא בפשטות: בקשתו של יעקב לישב בשלוה היתה שישב \"בארץ מגורי אביו\" בלי בלבולים וכו', כדי ש­יוכל לעבוד את ה' במנוחה, ביחד עם בניו ויוצאי חלציו כו' הולכי וממשיכי בדרכו היא הדרך \"אשר יצווה את בניו גו' ושמרו דרך הוי'\"<sup data-n=\"1526\">38</sup> — שזהו המקום והאופן הטבעי להגיע ולקבל שלוה כזו;\nאבל הקב\"ה נתן לו שלוה שהיא למע­לה מהטבע — \"ויחי יעקב בארץ מצרים שבע עשרה שנה\": ע\"פ טבע, עצם ה­מצאו \"בארץ לא להם\"<sup data-n=\"1527\">39</sup> הוא בלבול ל­מנוחת ושלות הנפש, ומה גם בארץ מצרים, ערות הארץ, שהיא בלבול גדול ביותר לשלוה אמתית. ומכל מקום, סיבב הקב\"ה שישב יעקב במיטב הארץ<sup data-n=\"1528\">40</sup>, ש­ימצא הן שלוה גשמית והן שלוה רוח­נית<sup data-n=\"1529\">41</sup>, באופן היותר נעלה (בלי כל דאגה משכן רע — מקולקלין שבאומות<sup data-n=\"1530\">42</sup>, שאוי לרשע ואוי לשכנו<sup data-n=\"1531\">43</sup> וכו').\nוכשם שהוא בגשמיות ובפשטות, ש­שלות יעקב בארץ מצרים היתה למעלה מן הטבע — כן הוא ברוחניות הענינים, שה\"שלוה\" בארץ מצרים היתה קשורה עם \"הנאה\" מזיו השכינה בדומה ל\"נהנין מזיו השכינה\"<sup data-n=\"1532\">44</sup> שבעולם הבא, שהיא הנאה שלמעלה מגדר הנבראים, ובלשון הרמב\"ם<sup data-n=\"1533\">45</sup> — \"אין כח באדם להשיגה על בורי' ואין יודע גדלה ויפי' ועצמה אלא הקב\"ה לבדו. . עין<sup data-n=\"1534\">46</sup> לא ראתה אלקים זולתך כו'\".\nח. ובזה יבואר הטעם שבשביל ה­שלוה הוצרך להיות \"קפץ עליו רוגזו של יוסף\" — כי לשלוה זו (שלמעלה מגדר הנבראים) לא הי' אפשר להגיע ב­כח עצמו ועבודתו, אלא ע\"י ענין מיוחד שיעלה ויגבי' אותו למעלה ממדידותיו והגבלותיו (כדי שיוכל לקבל שלוה זו).\nובשביל זה לא הי' די בעבודתו ועילויו ע\"י צרת לבן ועשו וכו', אלא \"קפץ עליו רוגזו של יוסף\" — כי \"רוגזו של יוסף\" אינו רק ענין שצרתו מרובה יותר, בכמות ובאיכות, אלא שהוא מסוג אחר, ולכן גם העילוי שבא על ידו הוא נעלה יותר באי\"ע.\nוההסברה בזה:\nצרת לבן וצרת עשו היו בתוכנם מלחמת ועבודת יעקב עם צד הלעו\"ז. בתחילה עם לבן הארמי, \"עם לבן הרשע גרתי ותרי\"ג מצות שמרתי ולא למדתי ממעשיו הרעים\"<sup data-n=\"1535\">47</sup>, ועד\"ז בצרת עשו, המורה על מלחמת הקדושה נגד כחות הרע, כידוע בענין מלחמתו של יעקב עם שרו של עשו, \"ויאבק איש עמו עד עלות השחר\"<sup data-n=\"1536\">48</sup> — שמלחמה זו ה\"ז מעבודת ותפקיד האדם עלי ארץ, לבטל הרע ש­בעולם, לתקן עולם במלכות שד\"י, ב­אופן שגם ביכולתו של האדם (נברא)",[["1526","38","וירא יח, יט. וברש\"י שם: יצווה ל' הווה."],["1527","39","לך טו, יג."],["1528","40","ויגש מז, ו."],["1529","41","וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101160\" data-slug=\"likkutei-sichot\" data-id=\"1300101160\">לקו\"ש ח\"י ע' 160</a> ואילך."],["1530","42","תו\"כ אחרי<sup data-n=\"e42\">*</sup> (יח, ג) הובא בפרש\"י שם."],["1531","43","סוכה בסופה. ועוד. פרש\"י במדבר ג, כט (מתנחומא שם, יב). ר\"פ קרח ד\"ה דתן ואבירם (מתנחומא שם, ד)."],["1532","44","ראה ביאורי הזהר (לאדהאמ\"צ) לזח\"א רטז, ב (לא, ב): וז\"ש (בזהר שם לגבי הי\"ז שנה דויחי יעקב בארץ מצרים) בעינוגין ותפנוקין. . כמו נהנין מזיו כו'."],["1533","45","הל' תשובה פ\"ח ה\"ז."],["1534","46","ישעי' סד, ג."],["1535","47","רש\"י וישלח לב, ה."],["1536","48","וישלח לב, כה. וראה בארוכה כלי יקר ובכמה מפרשי התורה שם."],["e42","*","ולגי' רבינו הלל הוא בס\"פ קדושים."]]],[1301410246,"לראות ולהכיר את התועלת שבעבודה זו.\nאמנם \"רוגזו של יוסף\" ה\"ז סוג אחר לגמרי, שאין בזה מלחמה עם צד הלעו\"ז או \"בירור\" עניני העולם וכיו\"ב — ולכאורה, כולו אינו אלא צער וצרה בלי שום מטרה כלל [ואדרבה, צרה זו גרמה לירידה כביכול במצבו של יעקב, \"וית­אבל על בנו\"<sup data-n=\"1537\">49</sup>, ועד שמשו\"ז פירשה ממנו שכינה<sup data-n=\"1538\">50</sup>, ועוד זאת, שאמר \"כי ארד אל בני אבל שאולה\" — \"גיהנם\"<sup data-n=\"1539\">51</sup>].\nו\"רוגז\" זה, שלכאורה הוא בגדר \"גזירה\" שאין בה טעם, הוא הוא הנסיון שהביא הקב\"ה על יעקב כדי להעלותו למעלה מעלה, עד לעילוי שלא בערך כלל, שעי\"ז נעשה כלי לאמיתית השלוה, עוה\"ב (שלמעלה מגדר נברא).\nט. ועדיין יש מקום לתמי': לפי הנ\"ל שהשלוה שניתנה ליעקב אינה אותה השלוה שביקש, אלא הוא ענין מיוחד לעצמו, מה שרצה הקב\"ה להטעימו מעין השכר דעוה\"ב — א\"כ מדוע חיכה הקב\"ה בזה עד שביקש יעקב לישב ב­שלוה (וכנ\"ל מהמדרש, דהא דקפץ עליו רוגזו של יוסף הי' תוצאה מבקשתו של יעקב לישב בשלוה)?\nוי\"ל טעם הדבר (בפנימיות) — כי \"הקב\"ה מתאווה לתפלתן של צדיקים\"<sup data-n=\"1540\">52</sup>, ולכן כל זמן שלא ביקש יעקב לישב בשלוה — לא ניתנה לו השלוה המגיעה לו; ורק כש\"ביקש יעקב לישב בשלוה\" — די\"ל ד\"ביקש\" כאן הוא (לא רק — רצה, אלא) לשון בקשה ותפלה — הרי לא זו בלבד שנתמלאה בקשתו, אלא עוד זאת — שניתנה לו השלוה בשלימותה, עוה\"ב.\nומכאן למדנו יסוד גדול והוראה ב­עבודתנו בזמננו אנו, עד כמה נוגע ענין בקשת הגאולה<sup data-n=\"1541\">53</sup>, שעל כאו\"א מבנ\"י ללמוד מהנהגתו של יעקב לבקש לישב בשלוה, שכל זמן שעדיין משיח לא בא, צריך כאו\"א מישראל לבקש, ועוד יותר — לתבוע שיבוא משיח צדקנו, כלשון חז\"ל<sup data-n=\"1542\">54</sup> (שהובא כמ\"פ) \"תני ר' שמעון בן יוחי. . כל אותן אלפים שנפלו במלחמה בימי דוד, לא נפלו אלא על שלא תבעו בנין בית המקדש. . ומה אם אלו. . אנו. . על אחת כמה וכמה, לפיכך התקינו חסידים הראשונים שיהיו מתפללים. . בכל יום. . השב שכינתך לציון וסדר העבודה לירושלים, ותקנו בונה ירושלים ברכה בפני עצמה בתפלה, ובברכת המזון\".\nוהובא (גם) להלכה<sup data-n=\"1543\">55</sup>, וז\"ל: הטעם",[["1537","49","פרשתנו לז, לד."],["1538","50","ראה תרגום אונקלוס ופרש\"י ויגש מה, כז. ומפורש בתיב\"ע שם \"ושרת רוח נבואה דאיסתלקת מני' בעידן דזבינו ית יוסף\"<sup data-n=\"e43\">*</sup>. וכ\"ה בזהר פרשתנו קפ, א. — ושאני בבית לבן שאף שהקב\"ה אמר ליעקב (רש\"י ויצא לא, ג) \"אבל בעודך מחובר ל­טמא אי אפשר להשרות שכינתי עליך\", — בכ\"ז \"עם לבן גרתי ותרי\"ג מצות שמרתי\", ובפרט משנולד יוסף (פרש\"י ויצא ל, כה), נעשה מוכן לגאולה השלימה (ראה תו\"א ותו\"ח ר\"פ וישלח — לעיל ע' 146) ועוד, כולל אמירת הוי' ליעקב הנ\"ל. וראה פרש\"י דברים ב, יז."],["1539","51","פרשתנו לז, לה ובפרש\"י."],["1540","52","יבמות סד, סע\"א."],["1541","53","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201233\" data-slug=\"likkutei-sichot\" data-id=\"1300201233\">לקו\"ש ח\"כ ע' 233</a> ואילך. ושם — לענין \"בקש יעקב לגלות את הקץ\"."],["1542","54","מדרש תהלים (הוצאת באבער) מזמור יז. ועד\"ז במדרש תהלים שם לפנינו. מדרש שמואל ספל\"א, הובא ברד\"ק סוף ש\"ב."],["1543","55","ב\"י לטאו\"ח סקפ\"ח (ד\"ה וכתב הרמב\"ם) משבלי הלקט דין סדר ברכת המזון סקנ\"ז. וברוקח הל' תפלה סי' שכב הובא מחז\"ל שבהערה הקודמת."],["e43","*","וראה גם ב\"ר פצ\"א, ו. תוד\"ה יום שכלו (ב\"ב קכא, א)."]]],[1301410247,"שצריך להזכיר מלכות בית דוד בברכה זו (בונה ירושלים). . לפי שצריכים אנו להזכיר מלכות שמים ומלכות בית דוד ובית המקדש. . ואין (ישראל) נגאלין עד שיתודו ויתבעו שלשתן.\nאלא שבזמנו של יעקב הוצרך ל\"קפץ עליו רוגזו של יוסף\" כהקדמה כדי לקבל שלוה זו; משא\"כ בזמננו אנו, הרי כבר עברו כל עניני \"רוגז\" ר\"ל על בני ישראל, הגזירות והשמדות ל\"ע<sup data-n=\"1544\">56</sup>, עד להשמדות האחרונות ר\"ל בדורנו אנו.\nוהקב\"ה מתאווה לתפילתם של ישר­אל, שיבקשו הגאולה — \"ביקש לישב בשלוה\" — וזה מביא ומזרז עוד יותר את הגאולה; וכמ\"ש החיד\"א<sup data-n=\"1545\">57</sup> \"אמרו ב­ילקוט תהלים רמז תשל\"ו<sup data-n=\"1546\">58</sup> אפי' אין ביד ישראל אלא הקיווי כדאי הם לגאולה בשכר הקיווי וכו'. . ובזה פירש. . מטבע ברכת את צמח דוד מהרה תצמיח וקרנו תרום בישועתך כי לישועתך קוינו כל היום דאומרו כי לישועתך אינו מובן מה נתינת טעם היא. . אבל ע\"פ האמור א\"ש והכי פירושה את צמח דוד וכו' וכי תימא שאין לנו זכות מ\"מ תצמיח כי לישועתך קוינו ויש לנו הקיווי ובשכר הקיווי כדאי שתגאלנו\".\nובפשטות: כאשר בנ\"י יבקשו כדבעי לישב בשלוה — הרי תיכף ומיד<sup data-n=\"1547\">59</sup> תקויים בקשת כאו\"א מישראל \"ותחזינה עינינו בשובך לציון ברחמים\" — שיבה בשובה ונחת וישיבה בשלוה \"בארץ מגורי אביו\", כפשוטו בגשמיות, בפועל ממש למטה מעשרה טפחים, ובעגלא דידן ממש.\n<span data-k=\"q\">(משיחות ש\"פ וישב ומקץ תשד\"מ; ש\"פ וישב תשמ\"ו) </span>",[["1544","56","ראה שערי תשובה לאדמו\"ר האמצעי (ה, ב. וראה גם אשל אברהם (בוטשאטש) או\"ח סס\"ח) שכבר \"בטלו השמדות ולא יהי' עוד\"."],["1545","57","מדבר קדמות מערכת ק' אות טז."],["1546","58","ממדרש תהלים מזמור מ. הובא גם ב­אבודרהם ס' תפלות יוהכ\"פ בסופו."],["1547","59","כלשון הרמב\"ם בספרו של \"הלכות הלכות\": ומיד הן נגאלין (הל' תשובה פ\"ז ה\"ה)."]]],[1301410248,"<h3>שיחה ב</h3>\nא. בסיפור לידת פרץ וזרח (בניהם של יהודה ותמר) נאמר בפרשתנו<sup data-n=\"1548\">1</sup>: ויהי בלדתה ויתן יד (הוציא האחד ידו לחוץ<sup data-n=\"1549\">2</sup>) ותקח המילדת ותקשור על ידו שני לאמר זה יצא ראשונה, ויהי כמשיב ידו (לאחר שקשרה על ידו השני החזירה<sup data-n=\"1549\">2</sup>) ו­הנה יצא אחיו גו' ויקרא שמו פרץ, ואחר יצא אחיו אשר על ידו השני ויקרא שמו זרח.\nעל התיבות<sup data-n=\"1551\">3</sup> \"אשר על ידו השני\" פרש\"י: ארבע ידות כתובות כאן כנגד ארבע חרמים שמעל עכן שיצא ממנו. ויש אומרים כנגד ד' דברים שלקח אדרת<sup data-n=\"1552\">4</sup> שנער ושתי<sup data-n=\"1553\">5</sup> חתיכות כסף של מאתים שקלים ולשון זהב.\nולכאו' יש לתמוה, איך מתאים פירוש זה עם הכלל שכלל רש\"י כמ\"פ<sup data-n=\"1554\">6</sup>, שבפי­רושו על התורה לא בא אלא לפשוטו של מקרא — שהרי פירוש זה בפסוק, שד' הפעמים שנא' כאן \"יד\" הם כנגד \"ד' חרמים שמעל עכן\" (או \"ד' דברים ש­לקח\"), לכאורה אינו אלא רמז בעלמא שאין לו שייכות לפירושן הפשוט של תיבות אלו.\nודוחק גדול לומר שבלימוד ע\"ד ה­פשט (פרש\"י) מתורץ עי\"ז הכפלת תיבת \"יד\" ד' פעמים, שהוא יתור לשון בכתוב — כי הו\"ל להוסיף \"רבותינו דרשו\" ו­כיו\"ב, כדרכו בכ\"מ שמביא \"אגדה<sup data-n=\"1555\">7</sup> ה­מיישבת דברי המקרא\",\nועוד, ע\"ד הפשט אין בהכפלת תיבת \"יד\" ד' פעמים יתור בכתוב — כי פעם הא' והג' (\"ויתן יד\", \"ויהי כמשיב ידו\") מוכרחות הן בפשטות להמשך הסיפור; היתור בפעם הב' \"ותקשור על ידו\" הוא רק שבמקום שתי התיבות \"על ידו\" הי' אפשר לכתוב רק תיבת \"עלי'\" — \"ריווח\" של תיבה אחת! ואין זה יתור הדורש ביאור, כי (ע\"פ פשוטו של מקרא) כדאית הוספת תיבה אחת ליתר ביאור.\nאמנם בנוגע לפעם הד' (\"ואחר יצא אחיו אשר על ידו השני\") לכאורה יש מקום לומר, שלא רק תיבת \"ידו\" מיות­רת, אלא שכל ד' התיבות \"אשר על ידו השני\" מיותרות<sup data-n=\"1556\">8</sup>, שהרי ברור מהמשך ה­כתובים ש\"אחיו\" (שיצא באחרונה) הוא זה \"אשר על ידו השני\", ואין צורך ב­סימן זה; ועפ\"ז יש לתרץ לכאורה ש­יתור זה מלמדנו על שאר ה\"ידות\"<sup data-n=\"1557\">9</sup>, שיש רמז בכך ש\"ארבע ידות כתובות כאן\" — \"כנגד ד' חרמים. . ד' דברים\".\nאבל כד דייקת שפיר, גם בפעם הד' אין כאן יתור (ע\"ד הפשט, הדורש בי­אור) — כי:",[["1548","1","לח, כח­ל."],["1549","2","ל' רש\"י שם, כח."],["1549","2","ל' רש\"י שם, כח."],["1551","3","שם, ל."],["1552","4","ע\"פ יהושע ז, כא. וראה לקמן סעיף ה."],["1553","5","כ\"ה בכמה דפוסים וכת\"י (או — \"וב'\"). ובדפוסים אחדים \"ושני\". ולכאו' הוא טה\"ד."],["1554","6","רש\"י בראשית ג, ח. שם, כד. ובכ\"מ."],["1555","7","ל' רש\"י בראשית ג, ח."],["1556","8","ומתורץ בפשטות הטעם שהעתיק רש\"י בה­ד\"ה גם התיבות \"אשר על. . השני\" שלכאורה אינן שייכות לתוכן פירושו. וראה לקמן הערה 31."],["1557","9","ראה יפ\"ת (השלם) לב\"ר (פפ\"ה, יד): ואע\"ג דלא מייתרו כל ד' הידות כו' דמדהני לדרשא כולהו נמי לדרשא. וראה גם נזר הקדש (השלם) שם."]]],[1301410249,"(א) בתיבות אלו — \"אשר על ידו ה­שני\" — בא הכתוב להדגיש את הטעם לקריאת שם \"זרח\" (שנאמר בכתוב תיכף לאח\"ז), וכפרש\"י \"ויקרא שמו זרח — ע\"ש זריחת מראית השני\"<sup data-n=\"1558\">10</sup>.\n(ב) ועיקר: מצינו כמ\"פ שהכתוב מכ­פיל ענין (אף שיש בזה יתור של תיבות אחדות) — לשם תוספת הבהרה או אפילו רק ליופי הלשון.\nולדוגמא — בפ' בראשית<sup data-n=\"1559\">11</sup>: \"ויכל אלקים ביום השביעי מלאכתו גו' ויש­בות ביום השביעי גו' ויברך אלקים את יום השביעי גו'\" — ג' פעמים \"ביום ה­שביעי\", ולא פי' שם רש\"י טעם הכפלה זו<sup data-n=\"1560\">12</sup> (שהי' אפשר לכתוב \"ויכל אלקים ביום השביעי מלאכתו גו' וישבות בו מכל מלאכתו גו' ויברך אותו אלקים ויקדש גו'\" — ולא הי' ספק שהמדובר \"ביום השביעי\")!\nועכצ\"ל, שאין ביתור עד\"ז קושי ע\"ד הפשט — שלכן לא מצינו בנדו\"ד בפר­שתנו, שפשטני המקרא יעמדו על כך ש\"ארבע ידות כתובות כאן\", אף שי\"ל שסמכו על פרש\"י — והדרא קושיא ל­דוכתא.\nב. גם יש להבין כמה דיוקים ב­פירוש רש\"י זה — ומהם:\nא) מהו דיוק הל' \"ארבע ידות כתובות כאן\" (כאילו שהן ארבע ידות שונות)? והרי כוונת רש\"י היא לד' פעמים \"יד\" — וא\"כ הול\"ל \"נכתב יד ד\"פ\"<sup data-n=\"1561\">13</sup>, או \"ד' פעמים יד כתיב כאן\"<sup data-n=\"1562\">14</sup> וכיו\"ב<sup data-n=\"1563\">15</sup>? ובפרט ש\"ארבע הידות\" הוא ל' הכתוב בפי' שונה — חלקים<sup data-n=\"1564\">16</sup>.\nב) מדוע הוזקק רש\"י לשני פירו­שים<sup data-n=\"1565\">17</sup>? — וכמשנ\"ת כמ\"פ, דכאשר רש\"י מביא שני פירושים, הרי זה משום שבכל אחד מהם יש קושי שאין בהשני, אלא ש­הפירוש הראשון הוא קרוב יותר לפשט ולכן מביאו ראשונה.\nג) בפירוש הא' לא פירט רש\"י אילו הם ד' החרמים שמעל עכן, ואילו בפי­רוש השני מפרט רש\"י ד' הדברים שלקח — \"אדרת שנער ושתי חתיכות כסף. . ולשון זהב\"!\nוביותר תמוה: בבראשית רבה<sup data-n=\"1566\">18</sup> — בפשטות, מקורו של פירוש רש\"י זה — הוא באופן הפוך: בפירוש הא' מפורטים החרמים שמעל עכן — \"ואלו הן ד', חרמו של עמלק וחרמו של סיחון ועוג וחרמו של יריחו וחרמו של כנענים (נ\"א מדין<sup data-n=\"1567\">19</sup>)\", ואילו בפירוש השני שם נאמר רק \"כנגד ד' דברים. . הה\"ד<sup data-n=\"1568\">20</sup> ואראה בשלל אדרת שנער אחת טובה וגו'\" (מ­בלי להעתיק המשך הכתוב שבו נפרטו שאר הדברים<sup data-n=\"1569\">21</sup>)!",[["1558","10","ראה גם נחלת יעקב, יריעות שלמה (מהרש\"ל) ועוד על פרש\"י."],["1559","11","ב, ב­ג."],["1560","12","וראה ספורנו שם."],["1561","13","ראה פרש\"י ר\"פ ח\"ש."],["1562","14","וכהלשון בתוס' הדר זקנים כאן."],["1563","15","ואף שעד\"ז הוא הלשון בבראשית רבה (פפ\"ה, יד) \"כמה ידות כתיב כאן\" — הרי נת' כמ\"פ שאין רש\"י מעתיק לשונות חז\"ל דוקא כצורתן, אלא באופן וסגנון שמתאים לפשש\"מ."],["1564","16","ויגש מז, כד. אבל ראה תרומה כו, יז (ועוד) שלרש\"י — אין צורך לבאר מש\"כ הראב\"ע שם."],["1565","17","ולהעיר שבמדרש לקח טוב כאן הביא רק טעם השני (אף שבמדרש רבה הובאו ב' הטעמים)."],["1566","18","פפ\"ה, יד."],["1567","19","כ\"ה בהוצאת ראם (וצילום שלה). וראה מפרשי המדרש. וראה ב\"ר הוצאת אלבק שם."],["1568","20","יהושע ז, כא."],["1569","21","כ\"ה בב\"ר לפנינו. וראה ב\"ר הוצאת אלבק שם. — וביפה תואר לב\"ר שם (ומלאכת הקודש על פרש\"י כאן), שגירסת רש\"י בב\"ר שנפרטו כל ד' ה­דברים, ולכאורה אין דבריו מוכרחים. ובפרט שב­רש\"י לב\"ר שם פי' ד' הדברים באו\"א (כדלקמן הערה 40)."]]],[1301410250,"ג. ויש לומר הביאור בכל זה:\nכוונת רש\"י בפירוש זה אינה לתרץ יתור בלשון הכתוב, אלא לבאר ענין כללי בסיפור זה: גם בלימוד ע\"ד הפשט מובן, שבסיפורי התורה בכלל<sup data-n=\"1570\">22</sup>, ושל האבות והשבטים בפרט, בא הכתוב ל­למדנו ולהשמיענו תוכן מסויים — אם ענין הנוגע לידיעת חייהם הם, או שזהו בגדר \"מעשה אבות סימן לבנים\", ענין המרמז על מאורעות של בניהם אחריהם\n— וכפי שמצינו כמ\"פ בפרש\"י בפר­שיות הקודמות<sup data-n=\"1571\">23</sup> (שמפרש כמה מאורעות של האבות איך שהם רומזים על דברים העתידים לבא בחיי בניהם), ובמיוחד במאורע כעין זה לעיל — בלידת יעקב ועשו: \"ואחרי כן יצא אחיו וידו אוחזת בעקב עשו\"<sup data-n=\"1572\">24</sup>, שפרש\"י שם<sup data-n=\"1573\">25</sup> תוכן ענין זה ובפרטיות: \"בדין הי' אוחז בו לעכבו, יעקב נוצר מטיפה ראשונה כו' ויעקב בא לעכבו שיהא ראשון ללידה כראשון ליצירה ויפטור את רחמה ויטול את ה­בכורה מן הדין\", וכן פרש\"י הטעם שהי' אוחז \"בעקב עשו\" — \"סימן שאין זה מספיק לגמור מלכותו עד שזה עומד ונוטלה הימנו\" —\nוא\"כ צריך להבין בנדו\"ד — מהו תוכנו של סיפור זה ע\"ד לידת פרץ וזרח, שאותו בא הכתוב ללמדנו, ש­תחילה \"הוציא האחד ידו לחוץ ולאחר שקשרה על ידו השני החזירה\" ויצא אחיו, ואחר יצא זה \"אשר על ידו השני\", ומהו הטעם שזרח יצא לאחרונה אף ש­הוציא ידו תחילה?\n[ואין לומר שגם כאן עיכב פרץ את זרח<sup data-n=\"1574\">26</sup> כדי שיצא הוא ראשון והוא יהי' הבכור<sup data-n=\"1575\">27</sup> — דביעקב ועשו, הרי כיון שעשו הי' רשע, מובן הטעם שיעקב לא רצה שעשו יצא ראשון<sup data-n=\"1576\">28</sup> (וכן לאידך — עשו, להיותו רשע, לא הניח ליעקב לצאת ראשון); אבל בנדו\"ד, הרי כבר פרש\"י — הן בפ' תולדות<sup data-n=\"1577\">29</sup> והן כאן בפרשתנו<sup data-n=\"1578\">30</sup> — ש\"שניהם צדיקים\", ומדוע יצא פרץ לפני זרח שהוציא את ידו תחלה?].\nודבר זה מסביר רש\"י בפירושו<sup data-n=\"1579\">31</sup>:",[["1570","22","ראה רש\"י בראשית א, א ובמפרשי רש\"י שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051003\" data-slug=\"likkutei-sichot\" data-id=\"1300051003\">לקו\"ש ח\"ה (ע' 3</a> ואילך)."],["1571","23","ראה לדוגמא: רש\"י לך יב, ו. שם, ח. שם יד, יד. ועוד (ובכולם לא הקדים רש\"י \"ורבותנו דרשו\")."],["1572","24","תולדות כה, כו."],["1573","25","והקדמת רש\"י שם \"שמעתי מדרש אגדה הדורשו לפי פשוטו\" — הוא מפני שתוכן הפירוש (שיעקב נוצר מטיפה ראשונה כו') הו\"ע של אגדה, אבל כללות הענין, שיש בסיפור זה תוכן ומשמעות, הוא (גם) לפי \"פשוטו\"."],["1574","26","ראה פרש\"י כאן (בטעם קריאת שם \"פרץ\") \"פרצת — חזקת עליך חוזק\"."],["1575","27","היינו בכור לאמו. ולהעיר מפענח רזא ומושב זקנים כאן."],["1576","28","כי בפשטות, אם עשו הי' ראוי לבכורה אין מקום שיעקב ישתדל לעכב עליו מלצאת ראשון (היפך הטבע ד\"הנכנסת אחרונה תצא ראשונה\" — רש\"י שם); אלא שאם יעקב לא הי' \"ראשון ליצירה\" לא הי' מקום לעכב כו' כי אין אחיזתו \"בדין\". ואכ\"מ."],["1577","29","כה, כד."],["1578","30","לח, כז."],["1579","31","ומה שכתב רש\"י זה כאן דוקא, ולא בתחי­לת הענין (בפעם הא' שנאמר \"יד\") — כי הקושיא היא לאחרי הפעם הא', ובתקפה בפעם הד' שנאמר \"יד\".\nאלא שעצ\"ע מדוע העתיק בהד\"ה גם התיבות \"אשר על (ידו) השני\". וי\"ל, שבזה מרמז רש\"י, שע\"פ פירושו מתורץ בפשטות (ובאופן מרווח) היתור של ד' תיבות אלו (אבל אינו, כי ביאור טעם קריאת שם \"זרח\" — ה\"ז מפורש בקרא. וראה תרגומים עה\"פ)."]]],[1301410251,"\"ארבע ידות כתובות כאן, כנגד ארבע חרמים שמעל עכן שיצא ממנו\", כלומר, שענינו של סיפור זה הוא \"סימן\" הרומז והשייך ל\"בן\" לאחר כמה דורות; ולכן נדחה זרח ויצא לאחרונה ולא זכה בבכורה<sup data-n=\"1580\">32</sup>, היות שיצא ממנו<sup data-n=\"1581\">33</sup> עכן שמעל בד' חרמים<sup data-n=\"1582\">34</sup>.\nד. עפ\"ז מתורץ ג\"כ הטעם שלא הק­דים רש\"י כאן \"ורבותינו דרשו\" (וכיו\"ב):\nרש\"י כותב הקדמה כזו במקום שיש קושי בלשון המקרא, המתיישב רק ע\"פ דרש או רמז; אבל בנדו\"ד לא בא רש\"י להפקיע הכתובים מידי פשוטם (וגם — לא בא לדרוש יתורא דקרא), אלא כוונתו היא לבאר ה\"סימן\" שבמאורע זה (וכנ\"ל, שכן רגיל (גם) ע\"פ פשוטו של מקרא, שיש תוכן ורמז במאורע זה, וכמו \"וידו אוחזת בעקב עשו\" שפרש\"י (כנ\"ל) \"סימן שאין זה מספיק לגמור מלכותו כו'\", ולא הקדים שזוהי אגדה או דרשה).\nוזהו דיוק לשון רש\"י — \"ארבע ידות כתובות כאן\" (ולא \"ארבע פעמים כתיב יד\" וכיו\"ב) — להדגיש, שאין כוונתו ל­עצם ההכפלה בלשון הכתוב, כ\"א, שב­לידה זו כתובות \"ארבע ידות\" — ד' עני­ני \"יד\" שונים (\"ידות\" ל' רבים) — \"ויתן יד\", \"ותקשור על ידו\", \"כמשיב ידו\", \"אשר על ידו השני\";\nוכיון שכן, מסתבר לומר, שהתוכן וה­\"סימן\" מרמז ג\"כ למאורע בעתיד השייך ל\"יד\", והקשור במספר של ד' — ולכן פרש\"י \"כנגד ד' חרמים שמעל עכן. . ד' דברים שלקח\".\nובזה מובן ג\"כ טעם העדיפות בפי­רושו הראשון של רש\"י לגבי הפירוש השני: כיון ש\"ארבע ידות כתובות כאן\" — ד' ענינים בקשר ל\"יד\" וכ\"א בתוכן שונה (\"ויתן\", \"משיב\" כו', כנ\"ל) — מס­תבר לומר, שגם בה\"סימן\" אירעו ד' מאורעות שונים; ולכן פירושו הראשון של רש\"י הוא \"כנגד ד' חרמים שמעל עכן\", שהן ארבע פעולות שונות, בד' זמנים שונים; משא\"כ לפירוש השני, שהם כנגד \"ד' דברים שלקח\", אין כאן ד' לקיחות (\"ידות\") שונות, כ\"א ד' פרטים בלקיחה אחת.\nה. אלא שמ\"מ לא הסתפק רש\"י בפי­רוש הא' ומביא גם דברי ה\"יש אומרים\" — \"כנגד ד' דברים שלקח\" — כי יש יתרון (גם) בפירוש השני.\nויש לומר, שרש\"י מרמז זה ע\"י ה­שינוי (הנ\"ל סעיף ב'), שבפירוש הא' לא פירט החרמים ובפירוש הב' פירט ד' הדברים.\nוהביאור בזה:\nהטעם בפשטות מה שלא פירט רש\"י מה הן ד' החרמים הוא — מפני שבפשוטו של מקרא אין הכרע מה הם החרמים שבהם מעל עכן, שהרי בקרא מפורש רק ע\"ד המעילה בחרם של יריחו, אבל לא ע\"ד שאר המעילות<sup data-n=\"1583\">35</sup>.",[["1580","32","ראה רמב\"ן כאן \"פרץ הוא הבכור\". וב­בחיי: הבכור הגמור. . פרץ שהוא הנפטר מן הרחם תחילה. . וכן הכתוב יזכיר שמו תחילה (ויגש מו, יב. וכן פינחס כו, כ)."],["1581","33","להעיר מברכת יעקב לאפרים ומנשה (ויחי מח, יט ובפרש\"י שם ושם, כ). וראה רש\"י שם, ח. ועד\"ז בכ\"מ. — ולהעיר מהשקו\"ט במפרשים ב­פרש\"י וירא (כא, יז) \"באשר הוא שם\". ואכ\"מ."],["1582","34","ואף שגם מפרץ יצאו מלכים לא כשרים (שמעשיהם פגעו בכלל ישראל — ראה לקמן ס\"ו) — הרי כיון שיצאו ממנו מלכי בית דוד, עד למלך המשיח, מובן שזה מכריע (משא\"כ בזרח)."],["1583","35","ראה רש\"י סנהדרין מג, ב (ד\"ה שנים) \"וכיוצא בזו עשה בעיירות אחרות ולא נתפרסמו\"."]]],[1301410252,"ואע\"פ שמאמירת עכן<sup data-n=\"1584\">36</sup> \"וכזאת וכזאת עשיתי\" יודעים (כפרש\"י שם) שמעל \"גם בחרמים אחרים\" — הרי אין יודעים מזה (א) בכמה חרמים מעל<sup data-n=\"1585\">37</sup>, (ב) ובאיזה חרמים מעל [ועד שי\"א שמעל בג' או ה' חרמים<sup data-n=\"1586\">38</sup>, וגם מצינו שקו\"ט ארוכה במפרשים<sup data-n=\"1587\">39</sup> מה הם החרמים].\nוזוהי העדיפות בפירוש השני על פירוש הראשון — כי ה\"(ד') דברים ש­לקח\" מפורשים בפשוטו של מקרא. ולכן מדייק רש\"י לפרט את ארבעת הדברים — כי בשטחיות מפורש בקרא<sup data-n=\"1568\">20</sup> רק שלשה דברים \"אדרת שנער אחת טובה ומאתים שקלים כסף ולשון זהב אחד\" (אדרת, כסף, זהב), ולכן מפרט ומפרש רש\"י שהיו כאן \"שתי חתיכות כסף של מאתיים שקלים\"<sup data-n=\"1589\">40</sup>.\nמשא\"כ ד' המעילות של עכן (שבפי­רוש הראשון), כנ\"ל, שלא מצינו אותן מפורטות בפשוטו של מקרא.\nו. ועוד י\"ל, ובהקדם: מובן ופשוט, דזה שזרח לא זכה בבכורה מפני שיצא ממנו עכן, הוא דוקא מפני שמעשיו של עכן (שנרמזו בארבע ידות הכתובות כאן) פגעו בכלל ישראל<sup data-n=\"1590\">41</sup>, אין זה ענין של חטא פרטי שלו אלא חטא הנוגע להכלל כולו.\n[כי פשוט, דמה שא' מיוצאי חלציו של זרח הנהו רשע (ואפילו רשע גדול ביותר) אין זה טעם שעבור זה יפסיד זרח את בכורתו, וכ\"ש וק\"ו שהכתוב יספר אודות זה תיכף בלידת זרח].\nוזהו הקושי בפירושו הראשון של רש\"י (שלכן לא הסתפק רש\"י בו בלבד), שלפיו נרמזו כאן (גם) ג' המעילות הרא­שונות של עכן, שלא פגעו בכלל ישר­אל<sup data-n=\"1591\">42</sup> אלא הן חטאיו הפרטיים (ועד שלא נחית הכתוב לספר אודותם) — וא\"כ מדוע רמזן הכתוב בלידת זרח כסיבה ל­הפסד הבכורה?\nמשא\"כ לפירוש השני שהרמז ב\"ד' הידות\" הוא רק בשייכות להמעילה ב­חרם של יריחו, שפגע בכלל ישראל כ­מסופר במקומו (בס' יהושע)<sup data-n=\"1590\">41</sup>.\nז. מיינה של תורה בפרש\"י זה:\nאיתא בספר הבהיר<sup data-n=\"1593\">43</sup>, ש\"זרח\" ו\"פרץ\" הם שמש ולבנה, וענינם של שמש ולבנה בעבודת ה'<sup data-n=\"1594\">44</sup> — \"שמש\" מרמז על עבודת הצדיקים, שעבודתם היא \"תמידים כסד­רם\", בלי שינוי (כמו אור השמש שאין בו שינויים), ולבנה מרמזת על בעלי תשובה (כמו מולד ומילוי הלבנה שבא לאחרי חסרונה).\nולכן מפרץ (שכנגד) לבנה יצאה מל­",[["1584","36","יהושע ז, כ."],["1585","37","ע\"ד הפשט. משא\"כ ע\"ד הדרש — ראה מפרשים שצויינו לקמן הערה 39 שלמדים מהלשון \"וכזאת וכזאת\" וכיו\"ב [אלא שבכל אופן, מזה גופא שיש בזה פלוגתא מובן שגם ע\"ד הדרש אינו פשוט כו']."],["1586","38","סנהדרין שם [אלא שבחדא\"ג מהרש\"א שם מגי' \"ד'\" במקום \"ה'\" (כבירושלמי שם פ\"ו ה\"ג, ומציין לרד\"ק יהושע שם — דמשמע שכן היתה גירסתו בש\"ס)]."],["1587","39","ראה ר\"ח ומפרשי ע\"י סנהדרין שם. מפרשי ב\"ר שם. מפרשי רש\"י כאן. ואכ\"מ."],["1568","20","יהושע ז, כא."],["1589","40","וברש\"י לב\"ר שם פי' באופן אחר (שהיו שתי אדרות). וראה נזר הקדש לב\"ר שם (ועוד). ואכ\"מ."],["1590","41","ראה יהושע שם, יא ואילך. סנהדרין שם. וראה גם יהושע (כב, כ) \"עכן. . מעל. . ועל כל עדת ישראל הי' קצף\". ולהעיר מרש\"י לך יב, ח."],["1591","42","ראה סנהדרין שם."],["1590","41","ראה יהושע שם, יא ואילך. סנהדרין שם. וראה גם יהושע (כב, כ) \"עכן. . מעל. . ועל כל עדת ישראל הי' קצף\". ולהעיר מרש\"י לך יב, ח."],["1593","43","סקצ\"ז (הובא ברמב\"ן ובחיי כאן. וראה גם גו\"א ועוד)."],["1594","44","אוה\"ת ואתחנן ע' קי. ועוד."]]],[1301410253,"כות בית דוד — שדוד \"הקים עולה של תשובה\"<sup data-n=\"1595\">45</sup>, עד למלך המשיח — שאחד מהחידושים של משיח הוא, כמאמר ה­זהר<sup data-n=\"1596\">46</sup>, משיח אתא לאתבא צדיקייא ב­תיובתא, שגם צדיקים יגיעו למעלת ה­תשובה. וזה מרומז בשם \"פרץ\" — ע\"ש \"פרצת עליך פרץ\"<sup data-n=\"1597\">47</sup>, המורה על ענין של פריצת הגדר<sup data-n=\"1598\">48</sup>, שזהו ענינה של עבו­דת התשובה<sup data-n=\"1599\">49</sup>, שהיא \"בחילא\" בכלל ו­\"בחילא יתיר\"<sup data-n=\"1600\">50</sup>, למעלה ממדידה ו­הגבלה<sup data-n=\"1601\">51</sup> (\"בכל מאדך\").\nוהטעם שפרץ יצא תחילה והוא ה­בכור<sup data-n=\"1602\">52</sup> — כי עבודת התשובה היא למע­לה מעבודת הצדיקים, וכמאמר<sup data-n=\"1603\">53</sup> \"מקום שבעלי תשובה עומדין אין צדיקים גמורין יכולין<sup data-n=\"1604\">54</sup> לעמוד בו\".\nובזה מובן גם הרמז בסיפור אופן לידת פרץ וזרח:\nכיון שזרח (מצ\"ע) ענינו עבודת הצדיקים, לכן התחיל הוא לצאת תחילה, כי התחילה וראשית הכוונה היא, ש­כאו\"א יהי' במדרגת צדיק<sup data-n=\"1605\">55</sup>; אבל עי\"ז שיצא ממנו עכן, הוצרך להתגלות מעלת התשובה<sup data-n=\"1606\">56</sup> [וכפשוטו של ענין, שעכן הי' בעל תשובה, שהתודה על חטאיו ויש לו חלק לעוה\"ב<sup data-n=\"1607\">57</sup>] — וזהו מענינו של פרץ — \"פרצת עליך פרץ\", תיקונו של \"עכן\" על ידי פריצת הגדר, ע\"י עבודת ה­תשובה.\n<span data-k=\"q\">(משיחות ש\"פ וישב וש\"פ מקץ תשל\"א, תשמ\"ו) </span>",[["1595","45","ע\"ז ה, רע\"א."],["1596","46","הובא בלקו\"ת שמע\"צ (צב, ב), <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">שה\"ש (נ, סע\"ב</a>) ועוד. וראה זח\"ג קנג, ב."],["1597","47","פרשתנו לח, כט. — וראה אגדת בראשית ספס\"ג (ורש\"י לב\"ר פפ\"ה, יד) \"פרץ זה משיח שנאמר (מיכה ב, יג) עלה הפורץ לפניהם\"."],["1598","48","ראה ראב\"ע ורמב\"ן עה\"פ."],["1599","49","ראה בארוכה \"ספר המאמרים — מלוקט\" ח\"א ע' שסז ואילך. וש\"נ."],["1600","50","כ\"ה בכ\"מ, ע\"פ זח\"א קכט, ב (ושם: ברעותא דלבא יתיר ובחילא סגיא)."],["1601","51","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380873\" data-slug=\"likkutei-torah\" data-id=\"4001380873\">לקו\"ת תצא לט, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381332\" data-slug=\"likkutei-torah\" data-id=\"4001381332\">שה\"ש נא, א</a>. ובכ\"מ. — וראה שע\"ת ח\"ב חינוך פמ\"ח מעלת \"בכל מאדך\" דבע\"ת לגבי \"בכל מאדך\" דצדיקים."],["1602","52","וראה אגדת בראשית שם."],["1603","53","רמב\"ם הל' תשובה פ\"ז ה\"ד (כדעת ר' אבהו ברכות לד, ב)."],["1604","54","כ\"ה ל' (גירסת) הרמב\"ם (\"אין. . יכולין לעמוד\" — ולא \"אין עומדין\" כבש\"ס שם), והיינו שאין זה אפילו ביכולת שלהם. ובזח\"א שם: לית לון רשו לקיימא כו'."],["1605","55","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381306\" data-slug=\"likkutei-torah\" data-id=\"4001381306\">לקו\"ת שה\"ש (מד, ג</a> ואילך) ועוד — שדוקא ע\"י עבודת הצדיקים נעשה דירה בתחתונים. ולהעיר ממשנ\"ת (תו\"ח תולדות (יב, ג­ד. ובסוף הפרשה). שם ס\"פ וישלח. ועוד) במעלת צ\"ג שנעשה בע\"ת, \"שאין בע\"ת יכול להגיע לשם כלל\"."],["1606","56","ראה יריעות שלמה (מהרש\"ל) על פרש\"י כאן, ד\"ד' חרמים היינו נגד חוט השני שרומז על החטא שנאמר (ישעי' א, יח) אם יהיו חטאיכם כשנים כשלג ילבינו\" (וראה תו\"ש פרשתנו לח, כח אות קכה. וש\"נ. קהלת יעקב מערכת זרח)."],["1607","57","משנה סנהדרין שם."]]],[1301410254,"<h3>שיחה א</h3>\nא. בפסוק<sup data-n=\"1608\">1</sup> \"וירא יעקב כי יש שבר במצרים ויאמר יעקב לבניו למה תתראו\" פרש\"י<sup data-n=\"1609\">2</sup>: למה<sup data-n=\"1610\">3</sup> תראו עצמכם בפני בני ישמעאל ובני עשו כאלו אתם שבעים, כי באותה שעה עדיין הי' להם תבואה.\nוידועה התמי': מדוע נקט רש\"י \"למה תראו עצמכם בפני בני ישמעאל ובני עשו\", שלא גרו בארץ כנען (כמפורש בקרא, שבני ישמעאל שכנו \"מחוילה עד שור אשר על פני מצרים\"<sup data-n=\"1611\">4</sup>, ועשו ובניו ישבו בארץ שעיר<sup data-n=\"1612\">5</sup>) — ולא אמר שלא יראו עצמם בפני שכניהם בארץ כנען גופא<sup data-n=\"1613\">6</sup>?\nבמפרשים מצינו כמה תירוצים ע\"ז — אבל כולם דחוקים לכאורה, ולדוגמא:\nא) הרמב\"ן בפירושו תירץ \"ואולי היו בני ישמעאל ובני עשו באים מארץ אחוזתם אל יוסף לשבור והיו באים דרך ארץ כנען עוברים עליו ואמר להם שלא יראו עצמן שבעים בפניהם כי יחשדוהו שיש ליעקב תבואה ויבואו אליו לאכול עמו לחם בביתו\".\nאבל כבר תמה עליו הרא\"ם ד\"ארץ אדום וארץ מצרים שתיהן בדרומה של ארץ כנען. . והבא מארץ אדום לארץ מצרים אין לו לעבור בארץ כנען\"<sup data-n=\"1614\">7</sup>.\nועוד ועיקר<sup data-n=\"1615\">8</sup>: ביאורו זה של הרמב\"ן מיישב רק מדוע יש חשש גם מפני בני ישמעאל ובני עשו הרחוקים — אבל עיקר התמי' במקומה עומדת: מדוע נקט רש\"י \"בפני בני ישמעאל ובני עשו\" (שב­זה שולל שאר אומות), ולא כתב בלשון סתמי וכללי \"בפני האומות\" (או כלשון הרשב\"ם<sup data-n=\"1616\">9</sup> \"בפני האנשים\") — וכולם בכלל?\nב) הרא\"ם תי' שלא נקט בני ארץ כנען מפני \"שכל אנשי ארץ כנען הי' להם תבואה כמותם\", משא\"כ \"בני עשו וישמעאל השוכנים סביבות ארץ כנען (ש)לא הי' להם תבואה כאנשי כנען\".\nאבל גם זה קשה (כמו שהקשו במפר­שים<sup data-n=\"1617\">10</sup>): מפשטות לשון הכתוב לעיל<sup data-n=\"1618\">11</sup> \"ויהי רעב בכל הארצות\", וכן ממש\"נ לאח\"ז בעת הליכת בני יעקב למצרים \"ויבואו גו' בתוך הבאים כי הי' הרעב",[["1608","1","פרשתנו מב, א."],["1609","2","מתענית י, ב. וראה לקמן סעיף ב."],["1610","3","בדפוס ראשון ושני דרש\"י (וכן בל' רש\"י שברמב\"ן, חזקוני, רא\"ם ועוד) — \"אל\" (כבתענית שם). וראה השקו\"ט ברא\"ם ועוד מפרשי רש\"י. ואכ\"מ."],["1611","4","ס\"פ ח\"ש."],["1612","5","וישלח לו, ח. וראה ר\"פ וישלח. שם לג, טז."],["1613","6","ע\"ד לעיל (וישלח לד, ל) \"להבאישני ביושב הארץ גו' ונאספו עלי גו'\". וראה ג\"כ תולדות כו, יד (הובא לקמן בפנים)."],["1614","7","ומכש\"כ ארץ ישמעאל שהיא \"מחוילה עד שור אשר על פני מצרים\", כנ\"ל."],["1615","8","נוסף על הדוחק, לכאורה, בעצם סברתו ש­יעקב חשש ש\"יבואו אליו (בדרכם למצרים) לאכול עמו\" — דמה בכך? וממנ\"פ, אם יש לו די תבואה בטח יכניס האורחים ובפרט — ממשפחתו (ומובן שבשביל חשש זה שלא יבואו לביתו — לא ישלח בניו לשבור בר במצרים!)."],["1616","9","כאן. וראה גם רד\"ק."],["1617","10","נחלת יעקב כאן. וראה חדא\"ג מהרש\"א תענית שם."],["1618","11","מא, נד. — בראב\"ע ורמב\"ן שם שהכוונה רק להארצות אשר סביב ארץ מצרים. אבל מסתימת רש\"י שם מוכח שס\"ל דקאי על כל הארצות. וראה הערה 13."]]],[1301410255,"בארץ כנען\"<sup data-n=\"1619\">12</sup>, משמע, שבעת אמירתו של יעקב \"למה תתראו\" הי' הרעב בארץ כנען, ואנשי כנען באו לארץ מצרים לשבור בר<sup data-n=\"1620\">13</sup>.\nועוד זאת: עדיין אינו מתורץ (כמו שהקשה המהרש\"א<sup data-n=\"1621\">14</sup>) — מדוע נקט רש\"י בני ישמעאל ובני עשו דוקא, ולא \"עמון ומואב שהיו ג\"כ שכיני ארץ כנען\"? והעיקר (כנ\"ל): למה לי' לרש\"י בכלל לפרט שמות של אומות, ולא כתב סתם \"בפני האומות\" וכיו\"ב<sup data-n=\"1622\">15</sup>?\nג) בגור ארי' כתב ד\"מאחר כי עשו וישמעאל אחים לכם יאמרו לכם וחי אחיך עמך<sup data-n=\"1623\">16</sup> ולפיכך היו יראים מפני עשו וישמעאל ולא מאנשי כנען\".\nאבל גם סברא זו צ\"ע לפי פשוטו של מקרא (נוסף על הדוחק לומר שבני ישמעאל ובני עשו יבואו לתבוע מזון מיעקב ובניו) — כי רואים במוחש, שאדם דואג יותר משכניו שאינם קרוביו מאשר קרוביו<sup data-n=\"1624\">17</sup> שבמדינה אחרת<sup data-n=\"1625\">18</sup>.\nד) בכלי יקר<sup data-n=\"1626\">19</sup> מבאר שנקט בני ישמעאל ובני עשו \"כי שניהם סוברים שיצחק גזל הצלחת ישמעאל<sup data-n=\"1627\">20</sup> ויעקב גזל הצלחת עשו ע\"י השתדלות\" (כי יעקב לקח ברכותיו של עשו במרמה<sup data-n=\"1628\">21</sup>), ולכן הם מקנאים לישראל יותר מכל האומות, ומשום זה חשש יעקב לקנאת בני ישמעאל ובני עשו דוקא.\nאבל ג\"ז אינו מובן: אפילו את\"ל שבני ישמעאל ובני עשו היתה בהם מדה יתירה של קנאה מבשאר האומות, מ\"מ פשוט, שגם אנשי כנען קינאו ליעקב ו­בניו בראותם שהללו שבעים בשעה שהם רעבים [וע\"ד שמצינו לעיל ביצחק, ד­כאשר הקב\"ה ברכו והצליחו בארץ פלשתים בשנת רעבון<sup data-n=\"1629\">22</sup> באופן שהי' לו \"מקנה צאן גו' ועבודה רבה\"<sup data-n=\"1630\">23</sup>, הרי משו\"ז — \"ויקנאו אותו פלשתים\"<sup data-n=\"1630\">23</sup>].\nומכיון שכן, עיקר התמי' במקומה עומדת: מדוע נקט רש\"י \"בפני בני יש­",[["1619","12","מב, ה. — וברמב\"ן (שם, ו) מפרש שבני יעקב \"הם הראשונים אשר באו מארץ כנען\". אבל לכאורה אין כל רמז לזה בפרש\"י."],["1620","13","וראה גם ויגש מז, טו (ובפרש\"י שם, יג: תחלת שני הרעב) ובהמשך הכתובים שם."],["1621","14","בחדא\"ג תענית שם."],["1622","15","וכן קשה על תי' הנחלת יעקב ושל הדברי דוד (להט\"ז) — שכתבו טעמים רק ע\"ז שאין לחשוש מפני בני כנען, אבל לא — מדוע נקט רש\"י בני ישמעאל ובני עשו דוקא (נוסף על מה שיש להקשות על גוף תירוצם. ואכ\"מ)."],["1623","16","בהר כה, לו."],["1624","17","להעיר ממשלי (כז, י) טוב שכן קרוב מאח רחוק."],["1625","18","בחדא\"ג שם (וראה גם באר יצחק על פרש\"י כאן) ש\"הקנאה שנאמרה הכא לא שייכא רק באחים קרובים ומטעם שיהי' האדם עם אחיו בצרה\". ע\"ש.\nאבל צ\"ע אם גם ע\"ד הפשט אפ\"ל שההשתתפות בצרת אחרים היא רק באחים קרובים<sup data-n=\"e44\">*</sup>, ולא גם בצרת שכנים (וראה רש\"י נח ז, ז \"נאסרו כו' מפני שהעולם שרוי בצער\"). ובכל אופן דוחק גדול ל­פרש כן כוונת רש\"י שסתם ולא כתב טעם והסברה על \"למה תתראו\"."],["1626","19","דברים ב, ג."],["1627","20","כי \"ביצחק (דוקא) יקרא לך זרע\" (וירא כא, יב), ו\"ויתן אברהם את כל אשר לו ליצחק\" (ח\"ש כה, ה), וברש\"י שם: הברכות מסורות בידך. . מסרם ליצחק."],["1628","21","תולדות כז, לה. ועוד."],["1629","22","תולדות כו, יב ובפרש\"י."],["1630","23","שם, יד."],["1630","23","שם, יד."],["e44","*","ולהעיר, שגם בני מואב ועמון הם קרובים לבני יעקב, אף שיש לחלק בינם לבני ישמעאל ובני עשו שהם יו\"ח של אברהם ויצחק, כמובן. כן להעיר מבני קטורה (בני אברהם) שישבו ב\"ארץ קדם\" (ח\"ש כה, ו)."]]],[1301410256,"מעאל ובני עשו\", היינו שהחשש הוא רק מפני אומות אלו<sup data-n=\"1632\">24</sup>, ולא מפני שכניו ב­ארץ כנען?\nב. ויובן זה בהקדים כמה דיוקים ב­לשון רש\"י:\nא) לכאורה רש\"י סותר את עצמו, דבתחילה כתב \"למה תראו עצמכם. . כאלו אתם שבעים\"<sup data-n=\"1633\">25</sup>, שמשמעו שבאמת לא היו שבעים ורק הראו עצמם כאלו הם שבעים — וממשיך \"כי באותה שעה עדיין הי' להם תבואה\"<sup data-n=\"1634\">26</sup>?\nאשר ע\"כ צ\"ל, שכוונת רש\"י ב\"כאילו אתם שבעים\" היא<sup data-n=\"1635\">27</sup>, שבני יעקב הראו עצמם כאילו יש להם הרבה תבואה<sup data-n=\"1636\">28</sup> שתספיק להם לפרנס את עצמם זמן רב — ובאמת היתה להם תבואה רק \"באותה שעה\" [היינו רק לאותה שעה בלבד, ו­כמובן מהמשך הפרשה, ש\"כלו לאכול את השבר אשר הביאו ממצרים\"<sup data-n=\"1637\">29</sup> והוצ­רכו לירד עוה\"פ למצרים לשבר אוכל] — וע\"ז הזהירם יעקב \"למה תתראו\".\nאבל עדיין צ\"ע, מדוע יתנהגו בני יעקב באופן כזה, שיראו עצמם כאילו הם שבעים יותר מכפי כמות התבואה שבידם? וגם אם יש איזה טעם להנהגה כזו — מנ\"ל לרש\"י הא? והלא יכולים ללמוד בפשטות, שיעקב הזהירם \"למה תתראו\" על השובע של אותה השעה?\nב) מקורו של רש\"י הוא בגמ' תענית<sup data-n=\"1638\">30</sup> — ושם הלשון: אמר להם יעקב לבניו אל תראו עצמכם כשאתם שבעין לא ב­פני עשו ולא בפני ישמעאל כדי שלא יתקנאו בכם.\nויש להבין טעם השינויים בלשון רש\"י<sup data-n=\"1639\">31</sup>:\n(א) בגמ' מקדים עשו לישמעאל ורש\"י מהפך הסדר — \"בני ישמעאל ובני עשו\"<sup data-n=\"1640\">32</sup>.\n(ב) רש\"י משמיט<sup data-n=\"1641\">33</sup> סיום לשון חז\"ל \"כדי שלא יתקנאו בכם\"<sup data-n=\"1642\">34</sup>.",[["1632","24","ובעיון יעקב לע\"י תענית שם, שחשש מהם דוקא \"לפי שהם בני אבותיהם ולא יקויים בהם מהר­סיך ומחריביך ממך יצאו\". אבל אינו ע\"ד הפשט, כמובן."],["1633","25","בדפוס ראשון דרש\"י וכמה כת\"י רש\"י ש­תח\"י (וכן בל' רש\"י שברמב\"ן) ליתא תיבת \"כאילו\". אבל בדפוסים הנפוצים הוא כבפנים. וכ\"ה בדפוס שני וכמה כת\"י רש\"י שתח\"י. וכן הועתק ברא\"ם ועוד מפרשי רש\"י."],["1634","26","ומה שתי' בנחלת יעקב על פרש\"י כאן \"דנקט הכי משום הדיוק אלא תראו עצמכם כאלו אתם רעבים וצעורים\" — לכאורה דוחק הוא (ואין כל רמז לזה בפרש\"י)."],["1635","27","כפי' הדברי דוד (להט\"ז) כאן. וראה גם רא\"ם כאן."],["1636","28","ע\"ד מ\"ש ביפ\"ת (השלם) לב\"ר כאן (פצ\"א, ב) ש\"לא היו מדקדקים בצמצום הפרנסה\"."],["1637","29","מג, ב וברש\"י שם. וראה גם רש\"י שם, ח \"ולא נמות ברעב\"."],["1638","30","י, ב."],["1639","31","הטעם שמוסיף רש\"י בני ישמעאל ובני עשו מובן בפשטות, כי ישמעאל עצמו כבר מת. וגם בנוגע לעשו, החשש הוא לא רק מפני עשו עצמו אלא מפני (כל) בני עשו. ולהעיר שבפירוש (רש\"י?)<sup data-n=\"e45\">*</sup> ובתוס' תענית שם הגירסא בני עשו."],["1640","32","בל' רש\"י שברמב\"ן (וכן באחדים מכת\"י רש\"י שתח\"י) מקדים עשו לישמעאל. אבל בדפוס ראשון, כמה כת\"י רש\"י שתח\"י ודפוסים הנפוצים הוא כבפנים (ובדפוס שני דפרש\"י נשמט \"בני עשו\")."],["1641","33","אלא שבאחדים מכת\"י רש\"י שתח\"י הובא \"ויקנאו בכם\"."],["1642","34","וי\"ל (בדוחק עכ\"פ) שמובן מעצמו, ובפרט שכבר מצינו בקרא הקנאה בכגון דא — \"ויקנאו אותו פלשתים\", כנ\"ל.\nאבל להעיר שע\"ד הפשט לכאורה לאו מילתא דפשיטא היא דמי שנתברך מאת ה' יש לו \"להטמין\" הצלחתו כו' משום חשש הקנאה (גרידא) — שהרי, אדרבה, יצחק לא עזב מעצמו את המקום מחמת קנאת הפלשתים אלא רק מפני ששילחוהו משם (תולדות כו, טז); ויתירה מזו: מפורש בפרש\"י (דברים ב, ז) \"כי ה\"א ברכך גו', לפיכך לא תכפו (ס\"א תכפרו) את טובתו להראות כאלו אתם עניים אלא הראו עצמכם עשירים\" — הרי להדיא, שעל ה­מתברך מאת ה' להראות את עצמו עשיר (ולא לחשוש משום קנאה) דאל\"כ ה\"ה כפוי טובה (כקושיית הדברי דוד כאן. וחילוקו בין ברכה מועטת לברכה מרובה צ\"ע).\nועכ\"פ, גם את\"ל שרש\"י ס\"ל שבנדו\"ד החשש לקנאה עד כ\"כ<sup data-n=\"e46\">*</sup> שצ\"ל הזהירות ד\"למה תתראו\" — הו\"ל לכותבו בפירוש."],["e45","*","בש\"ס לפנינו. אבל בע\"י שם \"בפני עשו\"."],["e46","*","ראה נחלת יעקב כאן שיעקב חשש שלא יהרגום בני ישמעאל ובני עשו. ובנזר הקודש השלם לב\"ר כאן (פצ\"א, ב) שחשש מפני עין הרע (וראה גם תנחומא באבער כאן. ועוד) — ע\"ד פרש\"י (בעניננו) מא, ב. מב, ה.\n‑"]]],[1301410257,"ג. ויש לומר, ששאלות אלו מתורצות אחת בחברתה:\nע\"ד הפשט החשש ד\"למה תתראו\" אינו משום ענין הקנאה, כי מכיון שלא הי' ליעקב ובניו הרבה תבואה, כ\"א רק \"באותה שעה\" (כנ\"ל), הרי מעיקרא אין מקום לקנאה מצד העמים<sup data-n=\"1643\">35</sup> (ואין זה דו­מה להצלחתו הגדולה של יצחק באופן של \"ויגדל גו' הלוך וגדל גו' גדל מאד, ויהי לו גו' ועבודה רבה\"<sup data-n=\"1644\">36</sup>);\nוהחשש ד\"למה תתראו\" הוא (לא על עצם הצלחת בני יעקב, שהיתה להם תבואה בשעת הרעב, כ\"א) רק על זה שהראו עצמם כאלו הם שבעים, וחשש זה ד\"למה תתראו\" הוא ענין מיוחד ה­שייך רק לבני ישמעאל ובני עשו (כד­לקמן).\nוזהו גם טעם השינוי, שבגמ' מקדים עשו לישמעאל ורש\"י מהפך את סדרם: לפי המפורש בגמ', שטעם החשש הוא \"שלא יתקנאו בכם\", הרי מובן, שעיקר חששו של יעקב הי' מפני קנאתם של בני עשו אחיו, שלקח ממנו הברכות \"במר­מה\"<sup data-n=\"1628\">21</sup> — וכמפורש בכתוב<sup data-n=\"1646\">37</sup> \"וישטום עשו את יעקב על הברכה גו'\" — ופשוט שקנאת בני עשו היתה יותר גדולה פי כמה מקנאתם של בני ישמעאל<sup data-n=\"1647\">38</sup> על אשר \"יצחק<sup data-n=\"1648\">39</sup> גזל הצלחת ישמעאל\"; משא\"כ לפי פרש\"י אין החשש ד\"למה תתראו\" שייך לענין הקנאה (או נקמה), ולכן מונאם לפי סדר הדורות — בני ישמעאל ובני עשו.\nד. הסברת הענין:\nכבר מצינו בכתובים לפנ\"ז שהי' מצב של רעב בארץ כנען הן בימי אברהם והן בימי יצחק, ושניהם עזבו בגלל זה את מקומם — אברהם ירד מצרימה לגור שם<sup data-n=\"1649\">40</sup>, ויצחק הלך אל אבימלך מלך פלשתים גררה<sup data-n=\"1650\">41</sup> (ו\"הי' דעתו לרדת ל­מצרים כמו שירד אביו בימי הרעב\" אלא שהקב\"ה ציווה לו \"אל תרד מצ­רימה\"<sup data-n=\"1651\">42</sup>).\nוהטעם שסיבב הקב\"ה כך שהוצרכו לגלות ממקומם, אינו משום שלא היו ראויים ח\"ו שהקב\"ה יכלכל אותם גם",[["1643","35","כמ\"ש בדברי דוד."],["1644","36","תולדות כו, יג­יד. וראה פרש\"י שם."],["1628","21","תולדות כז, לה. ועוד."],["1646","37","תולדות כז, מא. וראה גם פרש\"י וישלח (לב, ו). תפארת יהונתן כאן."],["1647","38","ולהעיר שבפירוש (רש\"י?) לש\"ס (תענית שם) נקט רק עשו, ומשמיט ישמעאל. וראה כלי יקר הנ\"ל: אין לך אומה שמתקנאת בישראל כמו עשו."],["1648","39","לשון הכלי יקר הנ\"ל. — ולהעיר שיצחק לא עשה כלום ליקח הצלחת ישמעאל ממנו (כמו לקיחת הברכות ע\"י יעקב)."],["1649","40","לך יב, י."],["1650","41","תולדות כו, א."],["1651","42","שם, ב ובפרש\"י."]]],[1301410258,"בימי הרעב — והראי', שבהיות יצחק בגרר, למרות \"שהיתה שנת רעבון. . הארץ קשה והשנה קשה\"<sup data-n=\"1652\">43</sup>, בכ\"ז בירכו ה' בהצלחה נסית ש\"וימצא גו' מאה שערים גו' ויגדל האיש גו' עד כי גדל מאד\"<sup data-n=\"1653\">44</sup> — אלא צ\"ל שהליכתם ממקומם היתה מחמת סיבות צדדיות.\nוכמפורש גבי אברהם שזה הי' \"ל­נסותו אם יהרהר אחר דבריו של הקב\"ה שאמר לו ללכת אל ארץ כנען ועכשיו משיאו לצאת ממנה\"<sup data-n=\"1654\">45</sup>. ועד\"ז ביצחק, שזה שהקב\"ה לא כלכל אותו במקומו (כ\"א שהוצרך ללכת גררה) הי' בשביל ענין צדדי. ואולי ע\"ד באברהם. וא\"צ לפרש — כי מובן מעצמו.\nומעתה יובן תוכן הנהגתם של בני יעקב, שהראו עצמם כאילו הם שבעים:\nבני יעקב היו חזקים בבטחונם<sup data-n=\"1655\">46</sup> ש­הקב\"ה לא יעזוב את יעקב וב\"ב בימי הרעב. ובראותם שיש להם תבואה בעת שכל אנשי ארץ כנען רעבים מפני חוסר התבואה, הי' ברור להם שזכו לברכה (והצלחה) אלקית שלמעלה מן הטבע (ובאופן שהקב\"ה יכלכלם במקומם);\nולכן, אף שלמעשה היתה להם תבואה רק \"באותה שעה\" (ולא תבואה רבה, כנ\"ל) — מ\"מ לא הי' שום ספק בלבם ש­גם להבא ימשיך הקב\"ה לפרנסם באופן נסי (כהנהגת הקב\"ה עם האבות בכלל), ולכן הראו עצמם כאילו הם שבעים (ב­רב תבואות), כי כך הרגישו בבטחונם החזק בה', ועד אשר התבואה הרבה שעדיין לא היתה בידם נחשבה בעיניהם כאילו כבר ישנה בידם.\nועל הנהגה זו טען יעקב \"למה תת­ראו\" — \"למה תראו עצמכם בפני בני ישמעאל ובני עשו כאילו אתם שבעים\":\nהנהגה כזו, להראות \"עצמכם. . כאילו אתם שבעים\" (ואין צורך ללכת אל ארץ מצרים לשבר בר), יכולה ל­עורר קטרוגם של בני ישמעאל ובני עשו — יוצאי חלציהם של אברהם ויצחק: איך יתכן שיעקב ובניו יושבים בטח ב­ארץ כנען בשנות רעב אלו? — וכי טובים הם מזקניהם אברהם ויצחק ש­הוזקקו ללכת מארץ כנען בימי הרעב? שהרי בני ישמעאל ובני עשו לא ידעו הטעם האמיתי של יציאת אברהם ויצחק ממקומם.\nוטענה כזו בכוחה לעורר קטרוג וכו'<sup data-n=\"1656\">47</sup> עד שיצטרכו להטלטל ממקומם.\nה. ביאור הענין ע\"ד הרמז:\nדבר זה, שבעצם אין ישראל זקוקים לקבל תבואתם ממצרים (שלכן היו בני יעקב בטוחים שאין צורך לשבר בר ממצרים) משתלשל (ככל דבר) מהענין כפי שהוא בשרשו ברוחניות.\nוהביאור:\nהטעם לזה שארץ מצרים היתה מקור שפע התבואה והלחם לכל הארצות<sup data-n=\"1657\">48</sup>, הוא לפי שכ\"ה ברוחניות הענינים, שהיא היתה מקורה של ה\"תבואה\" הרוחנית.",[["1652","43","פרש\"י שם, יב."],["1653","44","שם, יב­יג."],["1654","45","פרש\"י לך שם (ודלא כפי' הרמב\"ן שם שזהו \"עון אשר חטא\")."],["1655","46","ראה רש\"י לעיל (וישלח לד, כה) בטוחים היו כו'."],["1656","47","ע\"ד קטרוג השטן על אברהם (רש\"י וירא כב, א) ועוד. — וראה של\"ה חלק תושב\"כ פרשתנו כאן (שג, ב)."],["1657","48","ראה רש\"י לך יג, י. — והרי בימי הרעב הלך אברהם למצרים (לך יב, י), וגם יצחק \"הי' דעתו לרדת למצרים\" (רש\"י תולדות כו, ב)."]]],[1301410259,"כלומר: \"תבואה\" רוחנית ענינה חכ­מה. וכמו שמצינו שהתורה נקראת בשם \"לחם\", \"כי<sup data-n=\"1658\">49</sup> כמו שהלחם הגשמי זן את הגוף כשמכניסו בתוכו וקרבו ממש ונהפך שם להיות דם ובשר כבשרו ואזי יחי' ויתקיים כך בידיעת התורה והשגתה בנפש האדם שלומדה היטב בעיון שכלו עד שנתפסת בשכלו ומתאחדת עמו והיו לאחדים נעשה מזון לנפש וחיים בקרבה כו'\". כלומר, השכל דתורה הוא הנקרא לחם, כי תכונת השכל היא, שהמושכל מתאחד עם כח השכל ונעשים לאחדים<sup data-n=\"1659\">50</sup>, כמו שהלחם הגשמי נכנס לתוך הגוף ונעשה דם ובשר כבשרו. ומזה מובן שמעין זה הוא להבדיל בכל חכמה ושכל<sup data-n=\"1660\">51</sup>.\nוזהו הטעם (הפנימי) שמכל הארצות באו לשבר בר (\"חכמה\") מארץ מצרים דוקא — כי מצרים היתה מקורה של \"חכמה\", כדאיתא בזהר<sup data-n=\"1661\">52</sup> ש\"היתה חכמת מצרים יותר מכל העולם\".\nאמנם, בד\"א — באומות העולם, אבל בנ\"י אינם זקוקים כלל לחכמת מצרים עבור לימוד החכמה, כי עם היות שכמה עניני תורה קשורים בידיעת חכמות העו­לם — ולדוגמא: המצוה לחשוב בחשבוני התקופות והמזלות בשביל קידוש החודש ועיבור השנה<sup data-n=\"1662\">53</sup>, ועוד<sup data-n=\"1663\">54</sup> — מ\"מ, בשנים כ­תיקונן, הידיעה בחכמות אלו באה מן התורה עצמה<sup data-n=\"1664\">55</sup> (ע\"ד המסופר בחז\"ל<sup data-n=\"1665\">56</sup> שר' יהושע בן חנני' למד זמן עיבור נחש מן הכתוב), ובעת מן העתים הדורש ידי­עה בחכמות אלו, נמצאות הן בשלימותן אצל חכמי ישראל<sup data-n=\"1666\">57</sup> ובספריהם ואין צורך ללומדן מחכמי האומות. וכמ\"ש ה­רמב\"ם<sup data-n=\"1667\">58</sup> בנוגע לחשבונות התקופות וה­מזלות, שבימי הנביאים חברו חכמי ישר­אל מבני יששכר ספרים בענינים אלו אלא שלא הגיעו לידינו<sup data-n=\"1668\">59</sup>.\nוזהו הטעם הפנימי לזה שבעצם לא היו בני יעקב צריכים לשבור בר ב­מצרים.\nו. עפ\"ז יובן גם התוכן הפנימי ב­טענת יעקב \"למה תתראו\" — כי דבר זה, שישראל אין נזקקים כלל ל\"חכמת מצרים\", יכול לגרום לטענה מצד ה­עמים. כי אף שגם האומות יודעים ש­הקב\"ה בחר בנו מכל העמים ונתן לנו את תורתו, ויש הבדל בין ישראל ל­עמים, מ\"מ הרי בהידיעה בעניני העולם — לכאורה דומים הם לבני ישראל, וגם אצלם ישנם חכמות אלו.\nויתירה מזו: יתכן שאליבא דאמת \"חכמה\" זו שבידי האומות היא אותה החכמה שאצל ישראל, ועד שאפשר לסמוך על מסקנת חכמי האומות להלכה למעשה, וכמ\"ש הרמב\"ם<sup data-n=\"1669\">60</sup> לענין חכמת",[["1658","49","<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>."],["1659","50","ראה גם מו\"נ ח\"א פס\"ח."],["1660","51","וראה לקמן סעיף ו."],["1661","52","ח\"א (מדרש הנעלם) קכה, סע\"א — הובא בלקו\"ת ס\"פ צו. וראה מ\"א ה, י."],["1662","53","שבת עה, א. וראה רמב\"ם כותרת להל' קדוש החודש. שם פ\"א ה\"ו­ז."],["1663","54","ראה בפרטיות אנציקלופדי' תלמודית ערך חכמות חיצוניות סעיף ה (וראה שם ס\"א), וש\"נ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121205\" data-slug=\"likkutei-sichot\" data-id=\"1300121205\">לקו\"ש חי\"ב ע' 197</a> ואילך."],["1664","55","ראה אנציקלופדי' תלמודית שם סוס\"א. וש\"נ."],["1665","56","בכורות ח, א (הובא בפרש\"י בראשית ג, יד). וראה מדרש תהלים מזמור יט (לענין חכמת המזלות כו'). ועוד."],["1666","57","ראה אנציקלופדי' שם סוס\"א וסוס\"ה וש\"נ."],["1667","58","הל' קדה\"ח ספי\"ז."],["1668","59","ואדרבה, ידוע שחכמי האומות הקדמונים קבלו חכמות אלו מחכמי ישראל (כוזרי מאמר ב אות סו. וראה סדר הדורות ג\"א תמב וש\"נ)."],["1669","60","הל' קדה\"ח שם. וראה הקדמת הרמב\"ם לשמונה פרקים \"שמע (קבל) האמת ממי שאמרו\"."]]],[1301410260,"התקופות כו', דהדברים שיש עליהם \"ראיות ברורות. . שאין בהם דופי ואי אפשר לאדם להרהר אחריהם אין חוש­שין למחבר בין שחברו אותם נביאים בין שחברו אותם האומות\", וכן ציוותה התורה<sup data-n=\"1670\">61</sup> \"ורפא ירפא\" וסומכין על רופא מומחה לרבים גם אינו יהודי בדיני פקו\"נ לדחות כל התורה כולה<sup data-n=\"1671\">62</sup>, ועוד —\nבכ\"ז אין בנ\"י זקוקים כלל (בשנים כתיקונם) לחכמי האומות אלא הכל בא מן התורה עצמה (ועכ\"פ מחכמי ישר­אל)<sup data-n=\"1672\">63</sup>, כי גם בידיעות אלו יש \"הבדלה\" בין ישראל לעמים. כלומר: ההבדל בין חכמות אלו כפי שהם בתורה לגבי ה­חכמות כפי שהם באומות אינו רק ב­מקורן (אם מקורן היא התורה, או שכל האדם) אלא גם בעצם הגישה לענין החכמה והידיעה ותכליתן<sup data-n=\"1673\">64</sup>, ובלשון רז\"ל<sup data-n=\"1674\">65</sup> \"יש חכמה בגוים תאמן. . יש תורה בגוים אל תאמן\".\nוהביאור:\n\"תורה\" היא לשון הוראה<sup data-n=\"1675\">66</sup>, כלומר ענינה של תורה הוא לא רק להסביר האמת שבכל דבר ודבר (תורת אמת), אלא להוציא את המסקנא וההוראה ל­מעשה, להורות לאדם את המעשה אשר יעשון כו', וכמחז\"ל<sup data-n=\"1676\">67</sup> גדול תלמוד ש­מביא לידי מעשה, שה\"גדלות\" של ת\"ת היא בזה<sup data-n=\"1677\">68</sup> שמביא לידי מעשה.\nמשא\"כ \"חכמה\" (סתם) — הנמצאת גם אצל האומות — אין ענינה להורות לה­אדם את המעשה אשר יעשון כו'<sup data-n=\"1678\">69</sup>, כ\"א רק לבאר ולהסביר את הענין כשל­עצמו<sup data-n=\"1679\">70</sup>, ואין ענינה בירור בגדרי טוב או רע.\nומטעם זה, התואר ד\"לחם\" ומזון יתכן רק בנוגע לחכמת התורה. כי כמו שה­לחם הגשמי שנכנס למעיו של אדם, הרי ע\"י שנהפך שם להיות דם ובשר כבשרו, ה\"ה מחי' את הגוף — כך הוא בענין החכמה, שהתואר \"לחם\" חל רק על חכמה זו שאינה מוגבלת רק לשכלו של האדם, אלא ענינה הוא \"להזין\" את ה­אדם. וזהו ענין התורה, שאינה רק חכמה",[["1670","61","משפטים כא, יט. וראה אנציקלופדי' תלמו­דית ערך חולה (ע' רמח ואילך). וש\"נ."],["1671","62","שו\"ע או\"ח ר\"ס תריח (ודאדה\"ז שם ס\"ב וס\"ו). וראה רמ\"א או\"ח סשכ\"ח ס\"י (ושו\"ע אדה\"ז שם). טושו\"ע יו\"ד סקנ\"ה ובנ\"כ שם."],["1672","63","ויש לקשר זה עם ימי חנוכה (שחלים תמיד בפ' מקץ) — כידוע הביאור בזה ש\"טמאו כל השמ­נים שבהיכל\" (שבת כא, ב), שיון הוא \"חכמה ד­קליפה חכמות חיצוניות\", ולכן \"טמאו כל השמנים של בחי' חכמה שבקדושה\" (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370185\" data-slug=\"torah-or\" data-id=\"3901370185\">תו\"א פרשתנו מא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370189\" data-slug=\"torah-or\" data-id=\"3901370189\">שערי אורה מב, א</a> ואילך. ובכ\"מ);\nואצל בנ\"י כל ענין של \"חכמה\" (שמן) צ\"ל — ב\"היכל\" (דקדושה), וחתום בחותמו של כה\"ג (שבת שם), שענינו של כהן הוא לעמוד לשרת לפני ה' (וכה\"ג אסור לצאת מירושלים — רמב\"ם הל' כלי המקדש פ\"ה ה\"ז)."],["1673","64","היינו שנוסף על החילוקים ביניהם מצד החילוק אם הן מצד הקדושה או דלעו\"ז (וראה ס' הליקוטים­דא\"ח דהצ\"צ ערך חכמות חיצוניות. וש\"נ) — הרי נפק\"מ גם בעצם תכליתה של החכמה, כבפנים."],["1674","65","איכ\"ר פ\"ב, יג."],["1675","66","זח\"ג נג, ב. גו\"א ר\"פ בראשית בשם הרד\"ק."],["1676","67","קידושין מ, א. וש\"נ."],["1677","68","עיין הל' ת\"ת לאדה\"ז פ\"ד ס\"ב­ג."],["1678","69","להעיר מהידוע שבקליפה אין מוח הדעת — ו\"לא עביד פירין\" (זח\"ב קג, א (ובמק\"מ שם). נת' באורך בסה\"מ עת\"ר ע' קלח ואילך. וראה הנסמן בס' הליקוטים (דהצ\"צ) ערך דעת ע' שלח ואילך)."],["1679","70","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211114\" data-slug=\"likkutei-sichot\" data-id=\"1300211114\">לקו\"ש חכ\"א (ע' 114</a>) שמטעם זה גם חכמת התורה היא באי\"ע לשאר חכמות, וכמש\"נ (ואתחנן ד, ו) \"כי היא חכמתכם ובינתכם לעיני העמים\". ע\"ש."]]],[1301410261,"לחוד, אלא היא הוראה המשפיעה ופו­עלת בכל חלקי הנפש שהנהגתם תהי' בהתאם להוראת התורה.\nוכ\"ה בענין החכמות השונות הנצרכות להבנת (חלקים מסויימים של) התורה — שאצל איש ישראל, ענינן של חכמות אלו הוא כדי שיביאו לידי הוראה ל­מעשה — לדעת כיצד לקדש החודש ולעבר השנה וכיו\"ב.\nולכן בשנים כתיקונן אין מקום לקבל חכמות אלו מחכמי אומות — מאחר שבעצם גדר הגישה לחכמות אלו יש הבדלה בין ישראל לעמים.\nורק מצד חושך הגלות נוצר המצב שיש צורך \"לשבור בר\" מחכמי ה­אומות<sup data-n=\"1680\">71</sup>,\nאבל \"באותו הזמן\", בבוא משיח צדקנו, שוב יחזרו כל חכמות אלו לחכ­מי ישראל (ולא יצטרכו לחכמי האומות), והידיעה בהן תבוא מן התורה עצמה — כי \"תרבה הדעה והחכמה\"<sup data-n=\"1681\">72</sup>, ו\"יהיו ישראל חכמים גדולים. . כי<sup data-n=\"1682\">73</sup> מלאה הארץ דעה את ה' כמים לים מכסים\"<sup data-n=\"1683\">74</sup>, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות ש\"פ מקץ ומוצאי זאת חנוכה תשמ\"א) </span>",[["1680","71","ראה אנציקלופדי' תלמודית ערך חכ' חיצוניות ס\"א. וש\"נ."],["1681","72","ל' הרמב\"ם הל' תשובה פ\"ט ה\"ב."],["1682","73","ישעי' יא, ט."],["1683","74","ל' הרמב\"ם בסיום וחותם (הל' מלכים —) ספרו משנה תורה."]]],[1301410262,"<h3>שיחה ב</h3>\nא. \"ויאמרו איש אל אחיו אבל אשמים אנחנו על אחינו אשר ראינו צרת נפשו בהתחננו אלינו ולא שמענו על כן באה אלינו הצרה הזאת. ויען ראובן אותם לאמר הלוא אמרתי אליכם לאמר אל תחטאו בילד ולא שמעתם וגם דמו הנה נדרש\"<sup data-n=\"1684\">1</sup>.\nוכתבו המפרשים<sup data-n=\"1685\">2</sup> בביאור דברי \"איש אל אחיו\" ומענת ראובן ע\"ז, שלדעת האחים הי' יוסף חייב מיתה ע\"פ תורה [וכפי שהאריכו<sup data-n=\"1686\">3</sup> בהטעמים על זה], ולכן הדגישו בדבריהם ש\"עיקר<sup data-n=\"1687\">4</sup> האשמה היא. . שלא שמעו בהתחננו אליהם. . ולא הזכירו שבקשו להרגו לפי שחשבו שמ­צד בקשת ההריגה או המכירה וההש­לכה לבור אין עליהם אשמה\". וע\"ז ענה להם ראובן: \"הלא<sup data-n=\"1687\">4</sup> אמרתי אל תחטאו בילד, מאחר שהוא כילד ואינו בר עונשין עדיין בב\"ד של מעלה א\"כ אין לו משפט מות וא\"כ יש בידכם שתי עבי­רות כי הקב\"ה דורש מכם מדת האכ­זריות. . ונוסף על זה גם דמו הנה נדרש\".\nוצריך להבין: מהי התועלת שאותה רצה ראובן להשיג באמרו עכשיו, שיש בידם לא רק חטא האכזריות אלא גם החטא של \"דמו גו'\" (דזה שמכרוהו נח­שב להם כאילו שפכו דמו)? דלכאורה, מאחר שהשבטים עומדים ומתוודים כי אשמים הם ומצדיקים על עצמם את הדין — מה מקום לבוא עתה בדברים ה­מוסיפים עוד חטא על חטאם (שלכן — גם עונשם חמור יותר)?\n— והרי כאשר מישהו נמצא באיזו צרה וצוקה ר\"ל המביאתו לשבירת הלב ולהכרה שהוא עצמו גרם לזה במעשיו כו' — הנהגה אנושית מחייבת להשתדל לדבר על לבו ולנחמו<sup data-n=\"1689\">5</sup> כו', ולא להיפך — להוסיף צער על צערו בדברים ה­מגדילים כובד אשמתו כו' — וכ\"ש וק\"ו, שאינה הנהגה המתאימה לראובן בכור ישראל, וכלפי אחיו!\nב. לכאורה אפשר לבאר כוונת ראו­בן בזה: כאשר האחים הביעו רק הכרת אשמתם שהיא הסיבה לצרתם ולכן הצ­דיקו עליהם את הדין<sup data-n=\"1690\">6</sup>, אשר \"א­ל אמונה ואין עול צדיק וישר הוא\"<sup data-n=\"1691\">7</sup> וכו', וכמו שאמרו \"על כן באה אלינו הצרה הזאת\" — בא ראובן להוסיף, שלא די רק להצ­דיק את הדין על צרתם, אלא עליהם גם לעשות תשובה, והיינו שהצרה שבאה עליהם היא בכדי שישובו<sup data-n=\"1692\">8</sup>. ובלשון ה­רמב\"ם<sup data-n=\"1693\">9</sup> ש\"מדרכי התשובה הוא שבזמן שתבוא צרה ויזעקו עלי' ויריעו ידעו הכל שבגלל מעשיהם הרעים הורע להן. . וזה הוא שיגרום להסיר הצרה מעלי­הם\".",[["1684","1","פרשתנו מב, כא­כב."],["1685","2","כלי יקר, ספורנו, אור החיים כאן. וראה גם רמב\"ן כאן (פסוק כא). אלשיך כאן. ועוד."],["1686","3","ראה מפרשים שבהערה הקודמת. מפרשי התורה ר\"פ וישב. ועוד."],["1687","4","ל' הכלי יקר כאן. וראה שאר המפרשים שבהערות לפנ\"ז."],["1687","4","ל' הכלי יקר כאן. וראה שאר המפרשים שבהערות לפנ\"ז."],["1689","5","ראה ויחי נ, כא — בנוגע להנהגת יוסף עם אחיו."],["1690","6","רלב\"ג עה\"ת כאן \"התועלת הי'\". ש\"ך עה\"ת עה\"פ. וראה מדרש הגדול כאן."],["1691","7","האזינו לב, ד."],["1692","8","ראה רמב\"ם הל' תעניות פ\"א ה\"ג."],["1693","9","הל' תעניות שם ה\"ב."]]],[1301410263,"[ויש לומר, שזהו ג\"כ דיוק לשון ה­כתוב \"ויען ראובן אותם לאמר\"<sup data-n=\"1694\">10</sup>, ש­כוונת ראובן בזה היתה לרמז שעליהם (על האחים) \"לאמר\" — להתוודות שחטאו בילד (וכאילו אמר: הלא אמרתי לכם אל תחטאו גו' ולא שמעתם גו', לכן עליכם \"לאמר\" ולהתוודות שחטאתם ול­שוב בתשובה) — כי זה ש\"באה. . הצרה הזאת\" הוא בכדי שיתוודו על חטאם ויעשו תשובה על זה].\nולכן הוכרח להדגיש ש\"שתי עבירות\" בידם — לא רק \"מדת האכזריות\", אלא גם העובדא דמכירת יוסף (\"אל תחטאו בילד. . וגם דמו הנה נדרש\") — כדי שישובו גם על חטא זה.\nאמנם עדיין אין הענין מתיישב ב­לשונו של ראובן — דאם כוונתו רק להודיע שחטאו בהנהגתם (שלכן עליהם להתוודות ולשוב) הול\"ל בקיצור: \"הלא חטאתם בילד וגם דמו גו'\" וכיו\"ב — ומהו טעם האריכות: \"הלא אמרתי אליכם לאמר אל תחטאו בילד ולא שמעתם\", שנראה כאילו בא להוכיח להם את צדקתו, דעכשיו הרי רואים שהוא צדק בדבריו והם היו אלה שחטאו (שלא שמ­עו לדבריו)<sup data-n=\"1695\">11</sup>!\nותמוה ביותר: כיצד יתכן, אשר ב­שעה שאחיו אומרים: \"אבל אשמים אנחנו וגו'\" ומצדיקים עליהם את הדין — יבוא ראובן בטענה של הדגשת שבח עצמו לעומת חטא אחיו כו'?\nג. ויש לומר נקודת הביאור בזה:\nגם כוונת השבטים באמרם \"אבל אשמים אנחנו גו'\" היתה לא (רק) ל­הצדיק עליהם את הדין (שהצרה הזאת באה עליהם בדין), אלא (בעיקר) אמירת תשובה<sup data-n=\"1696\">12</sup> — וראובן, באמרו להם \"הלא אמרתי גו' ולא שמעתם\", התכוון לחדש ולבאר את אופן התשובה הרצוי' הנד­רשת מהם<sup data-n=\"1697\">13</sup>.\nויובן זה בהקדם דברי הרמב\"ם בהל' תשובה, דלאחרי שמבאר בכמה פרקים פרטי עניני תשובה (החייבים בה, מהותה, אופנה, זמנה, דברים המעכבים בה וכו') ממשיך לאח\"ז (בפ\"ה) שכל מעשי האדם הם בבחירתו החפשית, ומתחיל \"רשות לכל אדם נתונה אם רצה להטות עצמו לדרך טובה ולהיות צדיק הרשות בידו ואם רצה להטות עצמו לדרך רעה ולהיות רשע הרשות בידו\", ומסיים (שם בה\"ב) \"וכיון שכן הוא (\"שאין הבורא גוזר על האדם להיות טוב ולא להיות רע\") נמצא זה החוטא הוא הפסיד את עצמו. ולפיכך ראוי לו לבכות ולקונן על חטאיו ועל מה שעשה לנפשו וגמלה רעה. הוא שכתוב<sup data-n=\"1698\">14</sup>. . מה יתאונן אדם חי וגו'. וחזר ואמר הואיל ורשותנו ב­ידינו ומדעתנו עשינו כל הרעות ראוי לנו לחזור בתשובה ולעזוב רשענו שה­רשות עתה בידינו הוא שכתוב אחריו<sup data-n=\"1699\">15</sup> נחפשה דרכינו ונחקורה ונשובה וגו'\".",[["1694","10","כמו שהקשה באור החיים (ועוד) כאן — מהי הכפלת \"לאמר\"."],["1695","11","ופשיטא שקשה לפי' האוה\"ח כאן, שכל ה­דו\"ד הי' עד\"ז — שלטעם שאמרו הם \"יכנס גם ראובן (בהאשמה, ו)לזה ענה ואמר כו' כי הוא לא יחשבו לו עוון ע\"ז כי הלא אמרתי כו'\"."],["1696","12","ראה גם רד\"ק עה\"פ כאן."],["1697","13","לכאורה י\"ל שבזה התכוון ראובן לאמר, ד­זה שהתרה אותם בשעת מעשה מגדיל חטאם (ול­העיר מאברבנאל כאן), ובמילא נדרשת מאתם תשו­בה גדולה יותר. אבל אין זה ביאור מספיק, כי דוחק לומר שרק מפני חילוק זה בגודל חטאם (שהיתה התראה בשעת מעשה) יאמר להם ראובן \"הלא אמרתי לכם גו' ולא שמעתם\" כאשר הם עומדים ומתוודים כו' (ובפרט שזהו לשון המשתמע כאילו בא להוכיח צדקתו כו'), כנ\"ל בפנים."],["1698","14","איכה ג, לט."],["1699","15","שם, מ."]]],[1301410264,"ולכאורה יש לדייק — מדוע כותב הרמב\"ם ע\"ד בחירה חפשית בסוף ספר המדע שכותב בו \"כל המצות שהם עיקר דת משה רבינו ע\"ה\"<sup data-n=\"1700\">16</sup> (בהלכות תשובה)? והרי ענין הבחירה הוא (כלשון ה­רמב\"ם<sup data-n=\"1701\">17</sup>) \"עיקר גדול. . והוא עמוד התורה והמצוה\" — היינו שהוא \"עיקר\" ו\"עמוד\" של כל התומ\"צ (וביניהם גם של תשובה)!\nוי\"ל, כי השייכות בין בחירה לתשו­בה היא בעצם מהותם. כלומר: זה ש­בחירה חפשית ה\"ה \"עיקר גדול\" בכל התורה הוא בזה, שלולא ענין הבחירה לא יתכן ענין הציווי ולא הענין דשכר ועונש (כפי שביאר הרמב\"ם שם<sup data-n=\"1702\">18</sup>), אבל תתכן המעשה של מצוה; משא\"כ תשובה, הרי בחירה חפשית שייכת לגוף עשיית התשובה, דאם אין האדם מרגיש את עצמו אשם במעשיו, הרי אין מקום ל­חרטה (מלאה) על מעשיו הלא טובים.\nאבל יש לומר, שהרמב\"ם מרמז בזה ענין עמוק יותר, כדלקמן.\nד. תשובה לאמיתתה היא כאשר ה­אדם מתעורר מצ\"ע לשוב אל ה', ולא מפני סיבה מבחוץ שהכריחה (או עכ\"פ גרמה) שיעשה תשובה (כגון שעושה תשובה \"מיראה\" או \"מכשלון כח\"<sup data-n=\"1703\">19</sup>), כי כיון שענין התשובה הוא עד ש\"יעיד עליו יודע תעלומות שלא ישוב לזה ה­חטא לעולם\"<sup data-n=\"1704\">20</sup>, הרי אם הייתה סיבה חיצונית לתשובתו אין כאן \"בטחון\" גמור \"שלא ישוב לזה החטא לעולם\".\nולכן מאריך הרמב\"ם כאן אודות ענין בחירה חפשית, כי תשובה אמיתית באה רק מצד בחירתו החפשית של האדם ו­\"לא מיראה ולא מכשלון כח\"<sup data-n=\"1703\">19</sup>, לא מאי­זה סיבה צדדית<sup data-n=\"1706\">21</sup>.\nוזהו דיוק לשון הרמב\"ם, שלאחר ש­מאריך בב' פרקים (פרק ה­ו) ע\"ד בחירה חפשית של האדם כ' (ברפ\"ז) \"הואיל ורשות כל אדם נתונה לו כמו שביארנו ישתדל אדם לעשות תשובה ולהתוודות בפיו מחטאיו ולנעור כפיו מחטאיו כו'\" — דמ\"ש כאן דוקא לשון זה, הוא מפני שכוונתו היא לאופן התשובה שהתחיל לבאר (בפ\"ה), שבאה אך ורק מבחירתו החפשית של האדם, ולכן \"ישתדל אדם לעשות תשובה\", כלומר ענין התשובה צ\"ל תוצאה מהשתדלותו ורצונו של ה­אדם מצ\"ע, בחירתו החפשית לגמרי (כנ\"ל), שהאדם מצ\"ע מנער כפיו מ­חטאיו<sup data-n=\"1707\">22</sup>, ופשיטא שאינו בא מחמת שהכ­ריחו אותו (מלמעלה) לעשות תשובה<sup data-n=\"1708\">23</sup>.\nה. וזהו גם ההסבר בעניננו — אמירת השבטים \"אבל אשמים אנחנו גו' על כן",[["1700","16","ל' הרמב\"ם בהקדמתו לספר היד (ב\"מנין המצות על סדר הלכות הרמב\"ם\") בזה שכולל בספר ראשון ספר המדע."],["1701","17","שם פ\"ה ה\"ג."],["1702","18","שם ה\"ד."],["1703","19","ל' הרמב\"ם שם רפ\"ב."],["1704","20","רמב\"ם שם פ\"ב ה\"ב."],["1703","19","ל' הרמב\"ם שם רפ\"ב."],["1706","21","ראה לקו\"ש נשא תש\"נ ס\"ד (ליקוט פירו­שים לאגה\"ת (קה\"ת, תשמ\"ו) פ\"א — ע' סז), שי\"ל שזהו טעם הפנימי להסברא (מנ\"ח מצוה שסד) שאין מצוה וחיוב לעשות תשובה, ורק כשהאדם בוחר לעשות תשובה אזי חלה עליו חובת ומצות וידוי (וכמו בענין שחיטה, גירושין והדומה). ע\"ש."],["1707","22","דלשון \"ולנעור כפיו מחטאיו\" מתאים לומר (בעיקר) כאשר זה בא מהאדם עצמו, בדוגמת ניעור מאבק שעליו, שרגיל (ועיקר הפעולה והנפעל) דני­עור הוא לא כאשר שני מנערו מעליו, כ\"א כאשר הוא מנער את עצמו."],["1708","23","וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271223\" data-slug=\"likkutei-sichot\" data-id=\"1300271223\">לקו\"ש חכ\"ז ע' 209</a> ואילך. ועיין שם ע' 16­215, שי\"ל שזהו מכוונת הרמב\"ם שם ה\"ה \"וכבר הבטיחה תורה שסוף ישראל לעשות תשובה בסוף גלותן\", שבנ\"י יעשו תשובה זו, שבאה מצד בחירתם עצמם, ולא מצד יסורי הגלות."]]],[1301410265,"באה אלינו הצרה הזאת\" ומענה ראובן \"הלא אמרתי אליכם אל תחטאו גו' ולא שמעתם גו'\":\nאמירת השבטים \"אבל אשמים אנחנו וגו'\" היא אמנם ענין של תשובה ו­התוודות על חטא, אבל תשובתם זו היא תוצאה מהצרה שבאה עליהם<sup data-n=\"1709\">24</sup> (כפי ש­משמע גם מהמשך דבריהם \"אשמים אנח­נו גו' על כן באה אלינו הצרה הזאת\"), ואין בהתעוררות תשובה כזו הוכחה ש­רוצה לעשות תשובה ולשוב מחטאיו מ­בחירתו החפשית. וכ\"ה בפשטות, אשר דברי וידוי שהאדם אומר ע\"י ומתוך מצב של צרה וצוקה, אינם מגלים (כ\"כ) פנימיות רצונו לעשות תשובה, אלא שה­יסורין \"מכניעין לבו של אדם\"<sup data-n=\"1710\">25</sup>.\nובסגנון אחר: כשיש להתשובה סיבה צדדית (ופשיטא — כאשר היא באה ע\"י צרה ויסורין), והיא המעוררת בו חרטה ותשובה, אזי אין התשובה מתייחסת (לגמרי) להאדם; אמיתית התשובה היא דוקא כאשר באה כתוצאה מבחירתו ה­חפשית של האדם, שבוחר לשוב ולהת­קרב אל ה', שאז הרי היא מתייחסת כולה להאדם, שתשובתו היא בכוונה ל­שוב באמת אליו ית'<sup data-n=\"1711\">26</sup>.\nוי\"ל שזהו מה ש\"ויען ראובן אותם לאמר הלוא אמרתי אליכם לאמר אל תחטאו בילד ולא שמעתם\":\nראובן שהוא \"פתח בתשובה תחי­לה\"<sup data-n=\"1712\">27</sup>, לכן הוא הוא זה שלימדם דרכה של תשובה אמיתית<sup data-n=\"1713\">28</sup>. והיינו, אשר תשו­בה שסיבתה היא הצרה שבאה עליהם, אינה התשובה הנדרשת, ופשיטא שאין זה אמיתית ענין התשובה, אלא עליהם לזכור ולהכיר במה שאמר להם (ראובן) כל הזמן (\"לאמר\") \"אל תחטאו בילד ולא שמעתם\", כלומר, עליהם לחזור בתשובה מחמת עצם (גודל) החטא שהסביר להם אז.\n[וי\"ל דזהו מה שהוסיף \"וגם דמו הנה נדרש\", לרמז, שצרה זו שבאה עליהם עכשיו ה\"ז ענין נוסף, \"וגם (בו' המוסיף)",[["1709","24","ואף שמצינו שהתחרטו כבר לפנ\"ז, ב­ירידתם למצרים (פרש\"י פרשתנו מב, ג) — הרי ענין זה, ופשיטא דיבור של חרטה, אינו מפורש בתורה, עד שבאה עליהם \"הצרה הזאת\". ועכצ\"ל שכמה דרגות ב\"מתחרטין\", וכשירדו למצרים התחרטו על המכירה בפועל — אף שאז לא חשבו שעשו עוולה, אלא שמצד סיבות אחרות (צערו של יעקב וכדומה) היו מתחרטים על מעשיהם. משא\"כ כשבאה עליהם הצרה הזאת, הרגישו רגש של \"אשמה\" עד שבא בדיבור והתוודו. וע\"פ כ\"ז מובן, דמה שאח\"כ \"שמע (יוסף) שהיו מתחרטין\" (פרש\"י כאן מב, כד) — הוא אותו הלשון אבל במובן עמוק יותר."],["1710","25","ע\"ד ל' הכתוב (בחקותי כו, מא) \"אז יכנע לבבם הערל\". וראה בארוכה לקו\"ש חכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271223\" data-slug=\"likkutei-sichot\" data-id=\"1300271223\">שם (ע' 209</a> ואילך)."],["1711","26","להעיר מצפע\"נ על הרמב\"ם הל' תשובה (פ\"ב ה\"ב — ח, א) ד\"יש נפק\"מ בין ג' תשובות, א' מאהבה הוה כמו חכם עוקר והב' מיראה דהיא כמו מכה ורפואה. . חיילין ובטלין כו' והג' ע\"י יסורין דזה הוי מכאן ולהבא כו'\". וע\"ש ביאור החילוקים שבכ\"א מהן. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171185\" data-slug=\"likkutei-sichot\" data-id=\"1300171185\">לקו\"ש חי\"ז ע' 185</a> ואילך."],["1712","27","ב\"ר פפ\"ד, יט. וראה ב\"ר שם ופרש\"י וישב (לז, כט) שהי' עסוק בשקו ותעניתו כמה שנים לאחרי שבלבל יצועי אביו."],["1713","28","עפ\"ז מובן בפשטות מה שאמר הקב\"ה דוקא לראובן (ב\"ר שם) \"מעולם לא חטא אדם לפני ועשה תשובה ואתה פתחת בתשובה תחלה\" — אף שגם אדה\"ר וכן קין עשו תשובה, כבב\"ר ספכ\"ב (ראה הגהות הרש\"ש לפפ\"ד שם), כי \"מעולם לא חטא אדם ועשה תשובה\" — \"תשובה\" שלימה מצ\"ע, לשוב אל ה' על חטאו כראובן שעשה תשובה בבחי­רתו החפשית (בלי כל ענין צדדי), משא\"כ באדה\"ר וקין שעשו תשובה אחר שהי' עונש ונזיפה מהקב\"ה וכיו\"ב (ראה יפ\"ת השלם ופי' מהרז\"ו לב\"ר פפ\"ד שם. של\"ה בית גדול (לז, א)). וראה הערה הבאה."]]],[1301410266,"דמו הנה נדרש\", לא כפי אמרם \"אבל אשמים אנחנו גו' על כן באה אלינו הצרה הזאת\", שמחפשים להסביר סיבת הצרה].\nו. וי\"ל בעומק יותר, ובהקדם דיוק בלשון הרמב\"ם הנ\"ל \"וחזר ואמר הואיל ורשותנו בידינו ומדעתנו עשינו כל הרעות ראוי לנו לחזור בתשובה ולעזוב רשענו שהרשות עתה בידינו הוא שכתוב אחריו נחפשה דרכינו ונחקורה ונשובה\", די\"ל שכוונתו כאן היא לא רק להביא הראי' והמקורות בהפסוקים שאמר ירמי' (באיכה) לכל דבריו שכתב לפנ\"ז (כפש­טות לשונו) — אלא (גם) להוסיף עוד הדגשה, שלא רק שהתשובה האמיתית היא בבחירתו החפשית של האדם, אלא שבשעת התשובה עליו להכיר שגם ה­חטא הי' בבחירתו החפשית, ובלשונו (של הרמב\"ם) \"ומדעתנו עשינו כל ה­רעות\".\nוהביאור:\nכל זמן שיש לאדם תירוץ ואמתלא וכו' לתלות בהם (סיבת) חטאו (אפילו בדקות דדקות), ואפילו אם מכיר שהוא אשם בזה אלא שחושב שהיו גם גורמים אחרים שהשפיעו והביאו אותו (במקצת) שיחטא (אם מצד סביבתו בכלל, או מחמת מצב או סיבה פרטית שאירע לו, ולכן לא הי' יכול להנצל מהחטא, ו­כיו\"ב) — אין תשובתו של האדם תשובה אמיתית, שירצה לעזוב רשעו ולשוב אל ה' באמת ובלב שלם, מאחר שאין אצלו הכרה ברורה בחטאו<sup data-n=\"1714\">29</sup>, שהוא מדעתו, ומרצונו עזב את ה'.\nורק כאשר ישנה אצלו הכרה ברורה בחטאו, \"מדעתנו עשינו כל הרעות\", אזי יכול לחזור באמת בתשובה ולעזוב רשעו, ודוקא אז ה\"ז תשובה בבחירתו החפשית, \"שהרשות עתה בידינו\", שת­שובה כזו היא כל כולה של האדם, שהוא הוא העוזב רשעו ושב אל ה' באמת ובלב שלם.\nוכמו שהביא הרמב\"ם הראי' \"הוא ש­כתוב אחריו נחפשה דרכינו ונחקורה ונשובה וגו', ש\"נשובה\" בא עי\"ז ש­\"נחפשה דרכינו ונחקורה\", ואז גם אם מתחילה הי' נדמה בעיניו שאין החטא באשמתו לגמרי, יראה ויכיר שבאמת מדעתנו עשינו כל הרעות (כי גם אם היו סיבות וגורמים להחטא, הרי כיון שגם אז ניתנו לו הכחות להתגבר על הסיבות והמניעות, הרי סו\"ס עשיית הרעות היא מדעתו ומבחירתו)<sup data-n=\"1715\">30</sup>.\nוזהו גם ביאור דברי ראובן \"הלוא אמרתי אליכם לאמר אל תחטאו בילד ולא שמעתם\": נוסף על זה שעליהם לעשות תשובה מעצמם ולא מפני הצרה הזאת שבאה עליהם, הרי עוד זאת, שה­תשובה צריכה להיות מתוך הכרה ברו­רה, ש(גם) החטא הי' מדעתם ומרצונם, \"אמרתי אליכם לאמר אל תחטאו בילד ולא שמעתם\".\nז. ביאור השייכות בין שני הענינים —",[["1714","29","ראה מדרש תהלים (מזמור ק) \"מכסה פשעיו לא יצליח (משלי כח, יג). . זה אדם הראשון שאמר להקב\"ה (בראשית ג, יב) האשה אשר נתת עמדי לא ביקש לעשות תשובה כו'\". וראה בארוכה עקרים מאמר ד' פכ\"ו דמהדברים המונעים וה­מעכבים את התשובה — העלמת החטא (שצ\"ל ידיעה ברורה שחטא) והתנצלות, ע\"ש בארוכה."],["1715","30","ע\"פ המבואר לעיל הערה 26 מהצפע\"נ החילוקים דג' דרגות בתשובה מובן מה שדוקא ע\"י תשובה כזו, שעושה בבחירתו החפשית, ומכיר שחטא מדעתו — \"נעקר עוונו מתחלתו\" (ל' רש\"י יומא פו, סע\"א ד\"ה כאן מאהבה — לענין תשובה מאהבה)."]]],[1301410267,"בחירה חפשית ותשובה — בפנימיות הענינים:\nידועים דברי הרמב\"ם בהל' תשובה כאן<sup data-n=\"1716\">31</sup> שעל ענין הבחירה נאמר<sup data-n=\"1717\">32</sup> \"הן ה­אדם הי' כאחד ממנו\", ומבאר רבינו הזקן<sup data-n=\"1718\">33</sup> דהוא מפני שהבחירה שרשה \"מ­בחי' גבוה מאד\", דכמו שהקב\"ה \"אין מעכב על ידו\" כך היא \"הבחירה שניתן לאדם עד שאין מי שמעכב על ידו\", כלומר: מכיון ש\"הנפש השנית בישראל היא חלק אלוקה ממעל ממש\"<sup data-n=\"1719\">34</sup>, לכן הרי הוא \"כאחד ממנו\", בדומה להקב\"ה כביכול, וכשם שהקב\"ה \"אין מעכב על ידו\", כך יש להאדם בחירה חפשית ב­מעשיו.\nו(עיקר) גילוי כח זה של בחירה חפשית לגמרי — אין מעכב על ידו — הוא בעבודת התשובה דוקא. דכאשר האדם הוא מרוחק מהשם, עד שהפריד את עצמו ח\"ו מכל עניני קדושה, הרי לכאורה מצבו אינו נותן מקום ואפשריות שיוכל (ע\"פ טבע כו') להתקרב אל ה' ולתורתו ולמצותיו; אלא שע\"י זה שיש לו בחירה חפשית, ש\"אין מי שמעכב על ידו\", ביכולתו להתגבר ולחדש בעצמו תנועה של התקרבות לה' (היפך מצבו שפרק מעליו עול מלכותו ית').\nויש לקשר זה עם תוכן ענין חנוכה — שלעולם חל (חלק מימי) חנוכה בפרשת מקץ — ע\"פ המבואר על הפסוק<sup data-n=\"1720\">35</sup> \"כי נר מצוה ותורה אור ודרך חיים תוכחות מוסר\" — דלכאורה, \"איזה דרך חיים הוא מלבד התורה והמצות האמורה ל­מעלה בפסוק\"<sup data-n=\"1721\">36</sup>? — אלא ש\"דרך חיים\" קאי על עבודת התשובה<sup data-n=\"1722\">37</sup> (שזהו ההמשך \"ודרך חיים תוכחות מוסר\"), שעל ידי תשובה שלימה מעומק הלב מתגלים חיים מפנימיות הנשמה (הקשורה ב­הקב\"ה, חיי החיים).\nוזהו גם כן ענינם של נרות חנוכה — שאינם רק ענין של אור בלבד, \"נר מצוה ותורה אור\"<sup data-n=\"1723\">38</sup>, אלא יש בהם גם העילוי של \"ודרך חיים תוכחות מוסר\", כי זהו תוכן נס חנוכה — האור הבא מתוך ה­חושך דוקא<sup data-n=\"1724\">39</sup>, שלאחרי שגברה מלכות יוון הרשעה, ו\"טמאו כל השמנים שב­היכל\"<sup data-n=\"1725\">40</sup>, התגברות החושך ביותר, עד ש\"בטלו דתם ולא הניחו אותם לעסוק בתורה ובמצות\"<sup data-n=\"1726\">41</sup> — הנה \"גברו בני חש­מונאי\"<sup data-n=\"1727\">42</sup>, ועמדו במסירת נפש להלחם נגד גבורים ורבים, וגם פעלו באנשי דורם למסור נפשם על קדה\"ש<sup data-n=\"1728\">43</sup> שלא לעבור על הדת בשום אופן, שתוקף זה בא מפנימיות נפשם ש\"אין מי שמעכב על ידו\", דפנימיות זו זהו ה\"דרך חיים תוכחות מוסר\" שלמעלה מ\"נר מצוה ותורה אור\".\n<span data-k=\"q\">(משיחות ש\"פ מקץ תשמ\"א, ש\"פ עקב תשכ\"ח) </span>",[["1716","31","רפ\"ה."],["1717","32","בראשית ג, כב."],["1718","33","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380239\" data-slug=\"likkutei-torah\" data-id=\"4001380239\">לקו\"ת אמור לח, ב</a>."],["1719","34","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["1720","35","משלי ו, כג."],["1721","36","תו\"א פרשתנו ד\"ה ענין חנוכה (לב, ב)."],["1722","37","ראה בארוכה בכ\"ז שערי אורה בהקדמה."],["1723","38","ראה פרש\"י שבת כג, ב (ד\"ה בנים)."],["1724","39","ראה בארוכה דרושי חנוכה בתו\"א, שערי אורה, אוה\"ת וכו' בביאור הפסוק (ש\"ב כב, כט) \"והוי' יגי' חשכי\", ושייכותו לחנוכה."],["1725","40","שבת כא, ב."],["1726","41","רמב\"ם ריש הל' חנוכה."],["1727","42","ל' הרמב\"ם שם. ובגמ' שם \"כשגברה מלכות בית חשמונאי\". וראה רמב\"ם שם \"והעמידו מלך כו' וחזרה מלכות לישראל\". ואכ\"מ."],["1728","43","ראה בארוכה שערי אורה בהקדמה, שעיקר המסירת נפש מצד המקבל היתה בחנוכה. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251247\" data-slug=\"likkutei-sichot\" data-id=\"1300251247\">לקו\"ש חכ\"ה ע' 247</a> ואילך."]]],[1301410268,"<h3>שיחה א</h3>\nא. בענין זמנו של נצחון המלחמה בנס חנוכה מצינו ב' שיטות בראשונים: א) דעת הרמב\"ם שהי' בכ\"ה בכסלו, וב­לשונו<sup data-n=\"1729\">1</sup> \"וכשגברו ישראל על אויביהם ואבדום בחמשה ועשרים בחודש כסליו הי'<sup data-n=\"1730\">2</sup> ונכנסו להיכל כו'\". ב) דעת המאירי<sup data-n=\"1731\">3</sup> ש\"תגבורת זה הי' בכסלו בכ\"ד בו\"<sup data-n=\"1732\">4</sup>.\nוהנה ידוע שיש ב' דיעות<sup data-n=\"1733\">5</sup> בנוגע ל­גדרם של ימי חנוכה, אם קבעום רק להלל ולהודאה ולא למשתה ושמחה<sup data-n=\"1734\">6</sup>, או שקבעו אותם אף למשתה ושמחה<sup data-n=\"1735\">7</sup>, ובלשון הרמב\"ם<sup data-n=\"1736\">8</sup> \"שמונת ימים האלו שתחלתן (ליל<sup data-n=\"1737\">9</sup>) חמשה ועשרים בכסליו ימי שמחה<sup data-n=\"1738\">10</sup> והלל\"<sup data-n=\"1739\">11</sup>.\nולכאורה יש לומר שזה קשור עם הפלוגתא הנ\"ל (באיזה יום הי' נצחון ה­מלחמה), ובהקדם משנ\"ת במ\"א<sup data-n=\"1740\">12</sup>, שה­פלוגתא אי ימי חנוכה הם ימי שמחה, תלוי' בטעם קביעת ימי חנוכה: להדעות שימי חנוכה הם רק ימי הלל והודאה נקבע היו\"ט (בעיקר) על נס הנרות, דכיון שזהו (בעיקר) ענין רוחני, לכן גם חגיגת היו\"ט היא על ידי הלל והודאה להשם (ענין רוחני); משא\"כ לדעת הרמב\"ם (עיקר) קביעת ימי חנוכה הוי מפני נצחון המלחמה, ולכן תקנו חכמים שיהיו גם ימי שמחה, שמחה גשמית וגופנית, כמו שנצחון המלחמה הי' הצלה גופנית, וזה",[["1729","1","הל' חנוכה פ\"ג ה\"ב. וראה גם כל בו ואבודרהם שבהערה 15."],["1730","2","כן מפורש בפר\"ח או\"ח ר\"ס עת\"ר, שמדברי הרמב\"ם מוכח בהדיא שנצחו ביום כה (ועיי\"ש (וב­ברכ\"י שם ובכמה מפרשים) — השקו\"ט בזה שאנו מדליקים בליל כה ולא בליל כו)."],["1731","3","שבת כא, ב."],["1732","4","וכ\"ה במאמרי אדה\"ז תקס\"ג (ע' נז). שערי אורה ד\"ה בכ\"ה בכסלו פנ\"ג. סהמ\"צ להצ\"צ מצות נ\"ח (עא, א). ועוד. וכן מוכח ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380140\" data-slug=\"likkutei-torah\" data-id=\"4001380140\">לקו\"ת צו טז, א</a>. תו\"א סוף פ' וישב."],["1733","5","ב' הדיעות הובאו בהשלמה לשו\"ע אדה\"ז (לבעל דברי נחמי') סי' עת\"ר ס\"ג. וש\"נ."],["1734","6","מהר\"ם מרוטנבורק ז\"ל, הובא במרדכי ל­פסחים פ\"ד (סתר\"ה). טור או\"ח סעת\"ר. שו\"ע שם ס\"ב."],["1735","7","מרדכי הארוך הובא בד\"מ או\"ח שם. תוד\"ה הלכה — תענית יח, ב (\"אחנוכה ואפורים. . דיום משתה ושמחה כתיב\"). שו\"ת הרשב\"א ח\"א סתרצ\"ט (\"שמחה ועונג\"). ועוד. וראה לקמן הערה 11."],["1736","8","שם ה\"ג."],["1737","9","כ\"ה ברמב\"ם הוצאת פרענקל. ולפנינו ליתא \"ליל\"."],["1738","10","כן מפרש ביש\"ש לב\"ק פ\"ז סל\"ז (וראה גם ב\"ח או\"ח שם ד\"ה ומ\"ש משום) בדעת הרמב\"ם \"ו­אותן סעודות שעושין בימי חנוכה נראה שהן סעודות מצוה ולא כדברי מהר\"ם כו' אלא כדברי הרמב\"ם שהן ימי שמחה והלל כו'\" (ומדייק כן גם מגמ': וב­תלמודא משמע דנתקנו נמי למשתה ושמחה מד­אמרינן. . לשנה אחרת קבעו ועשאום יו\"ט כו'). וראה גם נמוקי מהרא\"י על הרמב\"ם שם. ובבנין שלמה מפרש ברמב\"ם ד\"מצוה לאכול בו. . שקב­עוהו לשמחה\", היינו למשתה כמו שאמרו ביו\"ט אין שמחה אלא בבשר. ובב\"ח שם בסופו (מהר\"ש מאוסטרייך) ד\"יש לנהוג שמחה ומשתה. . והוכיחו קצת מרבינו יואל. . ולא סגי בלא פת\". וראה השלמה לשו\"ע אדה\"ז שם עה\"ג."],["1739","11","ולענין הלכה כתב ברמ\"א שם \"שיש קצת מצוה בריבוי הסעודות\". ומציין למהר\"א מפראג ש­הוא (מהר\"א מפראג) המקור שהביא בד\"מ שם ד\"קבעו משתה ושמחה\". ובהשלמה לשו\"ע אדה\"ז שם: ולענין מעשה מנהג קדום הוא להרבות בסעודה בימים אלו וכן נוהגין במדינות אלו."],["1740","12","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101142\" data-slug=\"likkutei-sichot\" data-id=\"1300101142\">לקו\"ש ח\"י ע' 142</a> ואילך."]]],[1301410269,"שנקבעו (גם) להלל והודאה שהוא ענין רוחני, י\"ל שזהו ענין נוסף בשביל נס הנרות (ענין רוחני).\nועפ\"ז יש לומר, ששני הענינים שכתב הרמב\"ם — (א) שימי חנוכה הם ימי שמחה, (ב) (גם) נצחון המלחמה הי' בכ\"ה — שייכים זל\"ז, כי לדעתו קביעת היו\"ט דחנוכה היא לזכר שני הענינים שאירעו באותו היום; משא\"כ הדיעה שעיקר קבי­עת היו\"ט דחנוכה (שתחלתו בליל כ\"ה) היא מפני נס הנרות ולא בשביל ניצוח המלחמה — י\"ל שהיא בהתאם להדיעה שנצחון המלחמה הי' ביום שלפניו (כ\"ד בחודש), ובכ\"ה בכסלו אירע (רק) נס הנרות.\nועפ\"ז מדוייק לשון המאירי<sup data-n=\"1731\">3</sup>, כש­מבאר תוכן חגיגת הלילה הראשון (שלא הי' בו לכאורה שום נס בהשמן), שכ' \"מברכין על הגאולה ועל הודאת מציאת הפך\" — והיינו, שלא הסתפק בזה שמבר­כין \"על הגאולה\" (נצחון המלחמה) אלא מוסיף גם \"על הודאת מציאת הפך\" — כי מצד הגאולה עצמה היו קובעים את היו\"ט ביום כ\"ד (יום נצחון המלחמה), ולכן מוסיף שהטעם ליום ראשון דחנוכה הוא גם מצד מציאת הפך (הקשורה עם הדלקת המנורה דליל כ\"ה).\nב. אמנם כד דייקת אין הדברים מוכרחים, שהרי בפורים מצינו במפורש שהיו\"ט הוא בשביל נצחון המלחמה, \"אשר ישלטו היהודים המה בשונאי­\nהם\"<sup data-n=\"1742\">13</sup>, ומ\"מ נקבע היו\"ט (לא ביום ה­נצחון אלא) ביום המנוחה, \"ונוח בארבעה עשר. . בחמשה עשר בו ועשה אותו יום משתה ושמחה\"<sup data-n=\"1743\">14</sup>. וא\"כ גם בחנוכה אפ\"ל כן, דאף שנצחון המלחמה הי' ביום כ\"ד בחודש, מ\"מ נקבע היו\"ט (על נצחון זה) ביום שלאח\"ז, כ\"ה בכסלו, שהוא יום המנוחה (וכידוע גם הרמז בשם חנוכ\"ה<sup data-n=\"1744\">15</sup> — \"חנו בכ\"ה\"<sup data-n=\"1745\">16</sup>, היינו שכ\"ה הוא יום המנוחה<sup data-n=\"1746\">17</sup>).\nוכן נקט אדמו\"ר הזקן<sup data-n=\"1747\">18</sup> ד\"יו\"ט דפסח הוא ביום שנעשה הנס, משא\"כ בחנוכה ופורים שהן ביום המנוחה\" (וכדלקמן סעיף ד)<sup data-n=\"1748\">*17</sup>.\nועפ\"ז נמצא, שלדעת הרמב\"ם, דס\"ל שנצחון המלחמה הי' ביום כ\"ה, וס\"ל ש­קביעת היו\"ט היא על שם נצחון המל­חמה כנ\"ל (ולדעת הפר\"ח<sup data-n=\"1749\">19</sup>, לשיטת ה­רמב\"ם יום ראשון דחנוכה הוא רק ע\"ש נצחון המלחמה) — הרי היו\"ט דחנוכה הוא (לא ביום המנוחה שלאח\"ז, כב­פורים, אלא) ביום הנצחון, כמו בפסח; משא\"כ לדעת המאירי שנצחון המלחמה הי' בכ\"ד, הרי קביעות היו\"ט (שהיא גם על הגאולה) היא ביום המנוחה (כב­פורים).\nויש לומר שהפלוגתא אם חנוכה הוי ביום המנוחה או ביום הנצחון, תלוי' בהסברת השייכות דנצחון המלחמה לה­יו\"ט דחנוכה.",[["1731","3","שבת כא, ב."],["1742","13","מג\"א ט, א."],["1743","14","שם ט, יז­יח."],["1744","15","שבלי הלקט סקפ\"ט. ר\"ן לרי\"ף שבת פ\"ב. כל בו סמ\"ד. טאו\"ח סעת\"ר. אבודרהם סדר הדלקת נר חנוכה. לבוש שם. ובכ\"מ."],["1745","16","וכ\"ה בתקו\"ז תי\"ג (כט, א); חנו כ\"ה."],["1746","17","ולהעיר מלשון האבודרהם שם שכתב שם לפנ\"ז (ע\"ד לשון הרמב\"ם) \"וגברו בני חשמונאי ונצחום יום כה בכסלו\", ובכל בו \"וכשגברו ישראל על אויביהם ואבדום בכ\"ה יום בכסלו הי'\". ועד\"ז בהשלמה לשו\"ע אדה\"ז שם (ס\"ב) הביא ב' הלשונות (בתחלת הסעיף ובסופו). ואכ\"מ."],["1747","18","לקו\"ת (וראה גם תו\"א) שבהערה 4."],["1748","*17","וראה בארוכה ס' השיחות תשמ\"ט ח\"א ע' 113 ואילך."],["1749","19","או\"ח סעת\"ר. וראה גם בנין שלמה על ה­רמב\"ם כאן. ועוד."]]],[1301410270,"כלומר: לכו\"ע היו\"ט דחנוכה שייך הן לנצחון המלחמה והן לנס הנרות, אלא דפליגי אם הנס דנצחון המלחמה אינו אלא הקדמה והכשרה לנס הנרות, שהוא הגמר ושלימות, וזהו סיבת קביעת החג, או שנצחון המלחמה לא נחשב כהקדמה בלבד, אלא דומה בתוקפו לנס הנרות בשייכות לקביעת ימי חנוכה.\n[ולכן להדיעה שנצחון המלחמה הוא רק הקדמה והכשרה, ויו\"ט דחנוכה הוא על זה שטהרו את המקדש והדליקו נרות — נס הנרות, הרי ימי חנוכה אינם ימי שמחה, משא\"כ לדעת הרמב\"ם שנצחון המלחמה שווה בתוקפו בתור סיבת קבי­עת ימי חנוכה, יש בחנוכה שני ענינים, גם \"ימי שמחה\"].\nג. והביאור בזה:\nימים טובים שנקבעו לזכרון על נס שאירע לבנ\"י בזמן מסויים, יש בהם ב' אופנים ופרטים: (א) היו\"ט נקבע על הצלת וגאולת ישראל, ולא על אופן ה­הצלה והגאולה, (ב) קביעת היו\"ט היא לא רק על עצם ההצלה וגאולת ישראל, אלא גם על אופן הגאולה, שהיתה באופן מיוחד.\nויש לומר, שלדעת הרמב\"ם, זהו אחד החילוקים בין פורים וחנוכה, דאף שב­שניהם היתה הצלת וגאולת ישראל מיד אויביהם ושונאיהם [ואדרבה, עיקר הצלת וגאולת ישראל בגלוי היתה בימי הפורים, שאז ניצלו מגזירת המן ש\"בקש להשמיד להרוג ולאבד את כל היהודים מנער ועד זקן טף ונשים ביום אחד\"<sup data-n=\"1750\">20</sup>], הרי בפורים עיקר קביעת היו\"ט הוא על התוצאה, הצלת וגאולת ישראל<sup data-n=\"1751\">21</sup>, וטעם הדבר הוא, כי ההצלה ונצחון המלחמה גופא לא היו ע\"י נס גלוי, אלא ע\"י נס המלובש בדרכי הטבע; משא\"כ בחנוכה, שקביעת החג היא לא רק על התוצאה, ישועת והצלת ישראל, כ\"א גם על אופן הנס, \"ועל הנסים כו' מסרת גבורים ביד חלשים ורבים ביד מעטים\"<sup data-n=\"1750\">20</sup>.\nולכן בפורים נחשב נצחון המלחמה רק כעין הכשרה והקדמה להעיקר — ישועת ישראל, ולכן נקבע החג לא ביום שבו הי' נצחון המלחמה אלא ביום ה­מנוחה שבו מודגשת הצלת ישראל; משא\"כ בחנוכה שגם הנצחון הוא מעצם הנס ושייך להיו\"ט, הרי קביעת היו\"ט היא באותו יום שהי' הנצחון.\nד. והנה הובא לעיל שרבינו הזקן נקט כשיטת המאירי<sup data-n=\"1753\">22</sup>, ומבאר שחנוכה אינו כמו פסח, שחנוכה נקבע ביום המנו­חה (והנצחון הי' ביום שלפניו), משא\"כ בפסח שהיו\"ט נקבע ביום שנעשה הנס [וכמו שמבאר שם הטעם ע\"פ פנימיות הענינים<sup data-n=\"1754\">23</sup>, דכאשר הנצחון והיו\"ט הם בשני ימים ה\"ז מורה שנצחון האויב הוא ענין נפרד מהיו\"ט עצמו (ורק הכנה אליו), משא\"כ בפסח שהי' הנס על ידי שנגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו, שלמעלה מחילוקי דרגות, לכן היו שני הדברים ביחד, בלי התחלקות בין נגוף למצרים ורפוא לישראל].\nאבל י\"ל, שתוכן ביאור אדמו\"ר הזקן מתאים גם לשיטת הרמב\"ם (שנצחון ה­",[["1750","20","נוסח ועל הנסים."],["1751","21","ראה מנות הלוי למג\"א ט, כ­כב (רט, א)."],["1750","20","נוסח ועל הנסים."],["1753","22","מובן שאין מכאן הכרח שאדה\"ז מכריע (ל­הלכה) כדיעה זו שהי' בכ\"ד, וכידוע בכ\"מ בפני­מיות התורה, שמבארים ענין לדיעה אחת אף שאינו להלכה (דהרי אלו ואלו דברי אלקים חיים — עירובין יג, ב), ולדוגמא הביאור ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380899\" data-slug=\"likkutei-torah\" data-id=\"4001380899\">לקו\"ת (נצבים מה, סע\"א</a>. וכ\"ה בכ\"מ) בענין \"שופר של יעל פשוט\" אף שאינו להלכה (טושו\"ע ודאדה\"ז ר\"ס תקפו). אבל עכ\"פ בנוגע לעניננו — הביאור בהמאמר הוא (בעיקר) לדיעה זו."],["1754","23","לקו\"ת שם טז, ב."]]],[1301410271,"מלחמה הי' בכ\"ה), כי אינו דומה חנוכה לפסח, שבפסח היו שני הדברים — נגוף למצרים (מכת בכורות) ורפוא (גאולה) לישראל — בנושא אחד, כמ\"ש אדמו\"ר הזקן<sup data-n=\"1754\">23</sup> (ומוסיף \"ומ\"ש בספרים שזה הי' קודם חצות וזה לאחר חצות אינו אלא הכל בזמן אחד\"); משא\"כ בחנוכה, אף שגם נצחון המלחמה הוי בכלל הנס ש­עליו נקבע היו\"ט, מ\"מ, עיקר הנס דחנו­כה הי' נס השמן והנרות, שבזה הי' נס גלוי ממש, ש\"לא<sup data-n=\"1731\">3</sup> הי' בו אלא להדליק יום אחד נעשה בו נס והדליקו ממנו שמונה ימים\", ועוד זאת, שנס הנרות מורה על הצלת דת ישראל (היפך ביטול דתם וכו'<sup data-n=\"1757\">24</sup>) — וא\"כ היו כאן ב' נסים שונים שארעו בשני זמנים שונים, נצחון המלחמה ונס פך השמן (שהוא שלימות הצלת וגאולת ישראל).\n[ותוכן פלוגתת הרמב\"ם והמאירי אי נצחון המלחמה בחנוכה הי' בכ\"ד או בכ\"ה י\"ל: להמאירי, אף שביחס לפורים נחשב נצחון המלחמה דחנוכה בכלל הנס, מ\"מ, עיקר הנצחון דחנוכה הוא נצחון הדת (ובפרט שנצחון המלחמה לא הי' נס גלוי כנס פך השמן, שהרי הי' לנצחון זה אחיזה בטבע), והנס דנצחון המלחמה נחשב רק כהכשרה להעיקר<sup data-n=\"1758\">25</sup>, ולכן ס\"ל דגם בחנוכה היו\"ט הוא (לא ביום נצחון המלחמה, כ\"א) ביום המנוחה, כמו בפורים [ועפ\"ז מובן מה שמדייק המאירי שבלילה הראשון \"מברכין על הגאולה<sup data-n=\"1759\">26</sup> ועל הודאת מציאת הפך\" כנ\"ל]; משא\"כ הרמב\"ם ס\"ל, שגם נצחון המלחמה (וההצלה הגשמית) הוא ענין עיקרי בחנוכה (אף שגם הרמב\"ם ס\"ל שאחד הדברים העיקריים שבנצחון ד­חנוכה הוא הצלת הדת)].\nולפי זה יוצא, שלדעת הרמב\"ם — ג' חלוקות בדבר: בפורים קביעת היו\"ט אינה ביום הנצחון אלא ביום המנוחה; בחנוכה קביעת היו\"ט היא ביום שהיו בו ב' הדברים — נצחון המלחמה וגם הנס דפך השמן, שהם ב' דברים שונים שהיו בשני זמנים; ובפסח היו שני הדברים (נגוף למצרים ורפוא לישראל) בנושא אחד.\nולפי המבואר בכ\"מ (בפנימיות התו­רה) שגדרו של יום טוב הוא, דהוי יום מיוחד שבו היתה (וישנה) התגלות והמ­שכת קדושה (נוספת) בעולם, י\"ל, ש­שלשת אופנים אלה מורים על ג' אופנים בגילוי קדושתו של הקב\"ה בעולם:\nבפורים היתה התגלות הקדושה בעי­קר בהצלת וישועת ישראל, ואיבוד המן ונצחון המלחמה הם כעין הקדמה להת­גלות זו; בחנוכה גם בנצחון המלחמה הי' התגלות הקדושה, אבל דרגת הקדו­שה אינה בשווה להתגלות הקדושה שב­נס פך השמן; ובפסח היתה התגלות קדו­שה אלקית נעלית כ\"כ שגילוי' הי' בב' הענינים בשווה, שגם ב\"נגוף למצרים\", מכת בכורות, היתה התגלות קדושה השווה לקדושה שמתגלית ע\"י גאולת ישראל.\nה. והנה כל הדברים הללו ישנם גם בעבודת האדם, שסדר עבודתו הוא \"סור מרע ועשה טוב\"<sup data-n=\"1760\">27</sup>, ובעבודה זו דסור מרע (נצחון המלחמה) שבכאו\"א מישראל ישנם ג' אופנים:",[["1754","23","לקו\"ת שם טז, ב."],["1731","3","שבת כא, ב."],["1757","24","ראה רמב\"ם שם ה\"א. וראה ב\"ח שם: מצוה אחת יש בידן כו' הדלקת מנורה כו'."],["1758","25","ראה לקו\"ש ח\"י שם הערה 18. חכ\"ה ע' 237 ואילך."],["1759","26","ולא נצחון המלחמה. ולהעיר ממהר\"ץ חיות לשבת שם (וראה גם העמק שאלה לשאילתות שאילתא כו סוסק\"א וסק\"ז), שר\"ל שאין מברכין על נס הנצחון כיון שאינו יוצא מדרך הטבע."],["1760","27","תהלים לד, טו."]]],[1301410272,"א) \"סור מרע\" שענינו ביעור הרע מקרבו שיהא כלי נקי וראוי להשראת השכינה, שבאופן זה הסור מרע אינו אלא הכשר והכנה לעיקר עבודתו שהוא קיום מצות ה' — עשה טוב, \"ע\"ד משל המלך שרוצה להיות לו דירה בבית חדש אזי מתחלה צריך לנקותה מכל טינוף ולכלוך\"<sup data-n=\"1761\">28</sup>, כן בעבודת האדם שתחלה צריך \"לבער הרע ובערת הרע מקרבך<sup data-n=\"1762\">29</sup> שלא יהי' שום לכלוך וטינוף ח\"ו\"<sup data-n=\"1763\">30</sup> שהו\"ע סו\"מ, ואח\"כ אפשר להיות קיום מ\"ע שהוא \"עד\"מ תיקון וסידור כלים נאים שעי\"ז תהי' הדירה בתח­תונים\" ע\"י המשכת קדושתו ית' בעולם<sup data-n=\"1763\">30</sup>.\nב) למעלה מזה הוא כאשר האדם אינו צריך לנקיון מטינוף ולכלוך, להיותו זהיר בקיום מצות ל\"ת, ובמילא ה\"ה כלי נקי — דמ\"מ צריך להיות אצלו העבודה דסור מרע, שהו\"ע של אתכפיא וקבלת עול, שכופה א\"ע ומבטל א\"ע לקיים רצון הבורא. כי ע\"י זה שהאדם הוא יש ומציאות בפ\"ע, הרי בזה גופא הוא סותר כביכול להשראת השכינה, שאין הקב\"ה שורה אלא על דבר שבטל אצלו ית'<sup data-n=\"1765\">31</sup> ודוקא כאשר האדם כופה ומבטל א\"ע, דהיינו תנועה דסו\"מ, אפשר להיות בו השראת הקדושה<sup data-n=\"1766\">32</sup>, וע\"י אופן זה העבו­דה ד\"סור מרע\" אינה רק הכשרה והקד­מה, אלא זהו חלק מהשראת קדושתו ית'.\nג) למעלה מזה הוא אופן ששניהם שווים:\nגם כשהאדם נקי מכל לכלוך, והענין ד\"סור מרע\" אצלו הוא באופן של כפי' וביטול, שעי\"ז אינו בבחי' יש ומציאות בפ\"ע, מ\"מ ישנו עדיין הפרש אצלו בין העבודה דסו\"מ והעבודה דוע\"ט, שבעשה טוב נרגש אצלו שמקיים רצון העליון שבזה ממשיך עליו קדושתו ית', ובסו\"מ מרגיש שלילת המניעה, שכופה ומבטל א\"ע כי אם לאו ה\"ז סתירה להשראת השכינה;\nאבל יש מדריגה עליונה יותר בעבו­דה, שביטולו לרצון העליון הוא מוחלט עד כ\"כ שאינו מרגיש את החילוק בין הדרכים שעל ידם מביא השראת ה­שכינה, אם זהו ע\"י מניעת השלילה או ע\"י המשכת הקדושה, להיותו בטל ל­רצון העליון ומקיימו בלי שום חשבונות (וע\"ד מאמר ר' עקיבא<sup data-n=\"1767\">33</sup> שישראל אמרו בשעת מ\"ת על הן הן ועל לאו הן, שבין במ\"ע בין במל\"ת הי' נרגש אצלם ציווי (הכללי) של הקב\"ה), ודוקא ע\"י ביטול מוחלט זה שלמעלה מחשבון, המשכת הקדושה עי\"ז היא בתכלית השלימות<sup data-n=\"1768\">34</sup>.\n<span data-k=\"q\">משיחות ש\"פ וישב, ערב חנוכה, תשכ\"ו, תשמ\"ו) </span>",[["1761","28","לקו\"ת שם טז, סע\"א ואילך. ועד\"ז בלקו\"ת שבהערה 30."],["1762","29","ל' הכתוב פ' ראה יג, ב. שופטים יז, ז. ועוד."],["1763","30","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, ג</a>."],["1763","30","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, ג</a>."],["1765","31","<a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו (י, ב</a>)."],["1766","32","בכללות הו\"ע היראה והקב\"ע לא (רק) בשביל קיום מצות ל\"ת המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא</a> פ\"ד, אלא גם בשביל עשה טוב — תוכן המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא רפמ\"א</a>. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071193\" data-slug=\"likkutei-sichot\" data-id=\"1300071193\">לקו\"ש ח\"ז ע' 180</a> ואילך. וש\"נ."],["1767","33","מכילתא יתרו כ, א. ונת' בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061130\" data-slug=\"likkutei-sichot\" data-id=\"1300061130\">לקו\"ש ח\"ו ע' 119</a> ואילך."],["1768","34","והביאור בזה: נברא מצ\"ע, הרי להיותו בגדר נברא הוא שלא בערך כלל לגבי הבורא, ולכן גם אם עבודתו של הנברא היא בתכלית העילוי והשלימות, כולל רגש של כפי' וביטול ע\"פ חשבון, הרי אינו בערך להבורא, ובמילא השראת הקדושה שעי\"ז היא בהגבלה.\nורק כאשר הוא סר מרע ומקיים מצות בפשיטות שלמעלה מטעם ודעת, ולמעלה מכל חשבונות, גם למעלה מרגש הכפי' והביטול הבא מתוך חשבון (בשביל השראת השכינה), כ\"א מתוך פשטות ותמי­מות לקיים רצון הבורא, דוקא אז נמשך רצון הבורא.\nויש להאריך בכ\"ז. ואכ\"מ."]]],[1301410273,"<h3>שיחה ב</h3>\nא. בתפלת \"ועל הניסים\" שאומרים בימי חנוכה \"מסרת גבורים ביד חלשים ורבים ביד מעטים וטמאים ביד טהורים ורשעים ביד צדיקים וזדים ביד עוסקי תורתך\"<sup data-n=\"1769\">1</sup>. וכבר תמהו מפרשי התפלות, ששלשת הסוגים האחרונים (\"וטמאים כו' ורשעים כו' וזדים כו'\") \"לכאורה<sup data-n=\"1770\">2</sup> אין זה מפעולת הנס, דטומאה וטהרה ורשעים וצדיקים וזדים ועוסקי תורה אינם מ­עניני גבורה וחולשה לחשוב התגברות הטהורים על הטמאים לנס\".\nיש שתירצו<sup data-n=\"1771\">3</sup> ע\"פ מאמר חז\"ל<sup data-n=\"1772\">4</sup> \"מאן חולין רבנן\" (\"דאפילו<sup data-n=\"1773\">5</sup> בבריאותן הן תשושי כח מפני שהתורה מתשת כחם\"<sup data-n=\"1774\">6</sup>), ונמצא ש\"יש גם בענינים אלו גבורה וחולשה וגברו מכח הנס החלשים על הגבורים\" [ולפ\"ז אין כאן אלא תוספת ביאור על לפנ\"ז \"גבורים ביד חלשים\", שזה שבנ\"י היו חלשים אינו מפני שכן הי' טבע גופם, אלא להיותם \"עוסקי תו­רתך\", שהתורה מתשת כחו של אדם].\nאמנם (נוסף לזה שלפי זה אין זה מדגיש גודל הנס, ולמאי נפק\"מ מהי סיבת החולשה והגבורה, הרי גם בגוף הענין) לפי פשוטו קשה לפרש כן, כי ענין זה שייך רק לאלה שתורתם אומנתם עד ש\"התורה מתשת כחם\", כנ\"ל, וא\"כ, מלבד זאת שעדיין אינו מבואר טעם אמירת \"טמאים ביד טהורים ורשעים ב­יד צדיקים\", שלא מודגשת בהם מעלתם בתור לומדי תורה<sup data-n=\"1775\">7</sup> — הרי גם בנוגע ל­\"זדים ביד עוסקי תורתך\" קשה לפרש כן, כי דוחק לומר ש(כל) אנשי הצבא של מתתיהו ובניו היו \"רבנן\" ש\"תורתם אומנתם\"!\n[ובפרט ע\"פ מחז\"ל<sup data-n=\"1776\">8</sup> ש\"אילמלא דוד (שהי' עוסק בתורה<sup data-n=\"1777\">9</sup>) לא עשה יואב מל­חמה\" (\"זכותו של דוד (שעסק בתורה) עומדת לו ליואב במלחמותיו של דוד\"<sup data-n=\"1777\">9</sup>), שמזה מובן, שבעת המלחמה — על תל­מידי חכמים (\"רבנן\") החוב להתחזק עוד יותר בלימוד התורה, כדי שזכותם תגן על אנשי הצבא הנלחמים, ואדרבה, דוקא בזה תלוי נצחון המלחמה].\nולכאורה צ\"ל, שאין הפירוש ב\"זדים ביד עוסקי תורתך\", שכל אנשי הצבא היו \"רבנן\" ש\"תורתם אומנתם\", אלא ש­מנהיגי המנצחים במלחמה היו \"עוסקי תורתך\".\nויותר נ\"ל, ש\"עוסקי תורתך\" כאן היינו (לא רק אלו ש\"תורתם אומנתם\",",[["1769","1","ראה הנוסחאות בזה בסידור אוצר התפלות. ועוד."],["1770","2","ל' פירוש \"דובר שלום\" בסידור הנ\"ל."],["1771","3","דובר שלום שם."],["1772","4","נדרים מט, סע\"א."],["1773","5","ל' הר\"ן."],["1774","6","סנהדרין כו, ב."],["1775","7","בפרמ\"ג או\"ח סתרפ\"ב (משב\"ז) סק\"א (נעתק בעץ יוסף בסידור הנ\"ל) \"וטמאים ביד טהו­רים ע\"פ מ\"ש בזוה\"ק מפני מה עכו\"ם גבורים כו' בודאי ע\"פ נס הי'\" [וראה גם שיחת ש\"פ מקץ תשכ\"א — ע\"פ ע\"ח (שמ\"ב ספ\"ד — הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו (י, סע\"ב</a>). <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">פכ\"ד (ל, א</a>). ועוד) \"כל מעשה עוה\"ז קשים ורעים והרשעים גוברים בו\"]. — אבל לכאורה אין זה פשוטו (שהרי פשוט שהיו גבורים מבנ\"י (ובמשך כל הדורות) כו') אלא ע\"פ פנימיות ה­ענינים."],["1776","8","סנהדרין מט, א."],["1777","9","ל' רש\"י שם."],["1777","9","ל' רש\"י שם."]]],[1301410274,"אלא) כל לומדי תורה (גם בעלי עסק הקובעים עתים לתורה), שכולם נקראים \"עוסקי תורתך\". וכדמוכח מזה שכאו\"א מישראל חייב בברכות התורה, כולל הברכה \"לעסוק<sup data-n=\"1779\">10</sup> בדברי תורה\".\n[ועוד יש לומר, שהלשון \"עוסקי תור­תך\" (ולא \"לומדי תורתך\") כאן לא בא להדגיש אופן ההתעסקות בלימוד התו­רה, אלא כולל גם עסק המצוות<sup data-n=\"1780\">11</sup> שהוא תכלית הלימוד (לימוד המביא לידי מעשה). וזהו שנק' \"עוסקי\" (לא \"לומדי\"), כי \"לומדי תורתך\" היינו אלו הלומדים תורה, שזה שייך לשכלו והבנתו של האדם; משא\"כ עסק בתורה<sup data-n=\"1781\">12</sup> מורה שה­אדם בכל עניניו וכוחותיו עסוק בתורה, והיינו כשלומד ע\"מ לעשות, באופן שכל עשיותיו בכל רמ\"ח אבריו יהיו ע\"פ הוראות התורה.\nועפ\"ז מתורצת בפשיטות קושיית ה­מפרשים<sup data-n=\"1782\">13</sup> \"למה אומר זדים ביד עוסקי תורתך ולא אומר דבר והיפוכו כמו ש­אמר בכל האחרים\" — כי לפי הנ\"ל גם בבא זו היא \"דבר והיפוכו\", ד\"עוסקי תורתך\" הם המקיימים את מצוות התורה, היפך ה\"זדים\", העוברים בזדון<sup data-n=\"1783\">14</sup> על ציוויי התורה].\nוהדרא קושיא לדוכתה — מהו הנס ב\"מסרת. . טמאים ביד טהורים ורשעים ביד צדיקים וזדים ביד עוסקי תורתך\"?\nב. לכאורה י\"ל, דמ\"ש \"וטמאים ביד טהורים כו'\" קאי על מ\"ש לפנ\"ז — \"כש­עמדה מלכות יון הרשעה על עמך ישר­אל להשכיחם תורתך ולהעבירם מחוקי רצונך\", דהיינו (לא מלחמה כפשוטה, אלא) גזירות על הדת, מלחמה רוחנית; ומזה מובן, שתיאור נצחונם של ישראל שלאח\"ז, צריך לכלול לא רק את נצחון מלחמת אנשי הצבא, אלא גם (ואדרבה, בעיקר) את הנצחון הרוחני, התגברות על הגזירות וביטולן. ולכן אומרים \"וטמאים ביד טהורים ורשעים ביד צדיקים וזדים ביד עוסקי תורתך\", להדגיש ולתאר את נצחונם הרוחני של ישראל (אף ש\"אין זה מפעולת הנס\").\nאבל לכאורה דוחק לפרש שפרטים",[["1779","10","כפי נוסח אשכנז (טור או\"ח סמ\"ז. מג\"א או\"ח שם סק\"ג) — משא\"כ נוסח ספרד (וכן הוא נוסח אדה\"ז בסידורו) \"על דברי תורה\".\nבב\"ח שם ד\"לעסוק בדברי תורה\" קאי על \"ה­עמל והטורח\" בד\"ת (ובט\"ז או\"ח שם סק\"א \"דרך משא ומתן של פלפול כו'\". וראה פרמ\"ג שבהערה 7). אבל עכצ\"ל דקאי על אופן העמל והטורח שהוא בהישג ידו של כאו\"א מישראל (שכאו\"א חייב בברכה זו).\nובכל אופן מצינו בכ\"מ הל' \"עוסק בתורה\" ב­נוגע ללימוד סתם (ראה לדוגמא סנהדרין צט, סע\"א (הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>). ועוד)."],["1780","11","ולהעיר מהנוסח בסידור רס\"ג \"ומזידים ב­כף עושי תורה\". וברמב\"ם סדר תפלות (בסוף ס' אהבה) — ע\"פ מהדורת קאפח — \"ופושעים ביד עושי תורתך\"."],["1781","12","אבל להעיר מאבודרהם (הובא בב\"י ל­טאו\"ח שם) בהחילוק בין ב' הנוסחאות \"לעסוק בדברי תורה\" או \"על דברי תורה\"."],["1782","13","ארחות חיים (הל' חנוכה אות כב), הובא בב\"י לטאו\"ח סתרפ\"ב. ועוד.\nומה שתירץ שזהו \"דרך הפסוק. . דכתיב (תהלים קיט, נא) זדים הליצוני עד מאד מתורתך לא נטיתי\" — הא גופא צ\"ב: (א) מדוע נקט כתוב זה דוקא. (ב) מדוע לא נקט הקרא דבר והיפוכו (ראה דברים אחדים להחיד\"א דרוש ל\"ב — קסז, ד ואילך).\nוראה עוד תירוצים באלי' רבה, פר\"ח ועוד או\"ח שם."],["1783","14","בפר\"ח שם (בשם הא\"ח וב\"י) \"ולא אמר. . זדים ביד ענוים\", ומשמע שמפרש ד\"זדים\" היינו גסי הרוח. אבל לכאורה בפשטות קאי על העושים במזיד כו' נגד התורה (כבפנים). וראה נוסח הרס\"ג והרמב\"ם הנ\"ל הערה 11."]]],[1301410275,"אלו שאומרים בהמשך ל\"ועל הנסים כו'\" אינם בכלל הנסים והנפלאות \"שעשית לאבותינו בימים ההם\".\nויש לומר הביאור בזה: ידוע מדברי הימים ההם, שאף שהגזירות נגד דת ישראל (\"להשכיחם תורתך ולהעבירם מחוקי רצונך\") נגזרו ע\"י \"מלכות יון הרשעה\", שהם \"גזרו גזירות על ישראל ובטלו דתם ולא הניחו אותם לעסוק ב­תורה ובמצות כו'\"<sup data-n=\"1784\">15</sup>, מ\"מ היו כו\"כ מבנ\"י (המתיוונים) שהצטרפו להיוונים (נוסף על אלה שעשו כן מפני האונס), ועד שמיעוט מבנ\"י נשארו שלימים בגלוי עם ה' ותורתו.\nואולי י\"ל, שהכוונה בשלשת הענינים הנ\"ל (\"טמאים ביד טהורים ורשעים ביד צדיקים וזדים ביד עוסקי תורתך\") היא למתיוונים מבנ\"י<sup data-n=\"1785\">16</sup>, היינו, שנוסף על הנס שבני חשמונאי גברו על מלכות יון (ב­אופן ד\"מסרת גבורים ביד חלשים ורבים ביד מעטים\"), הנה עוד זאת, שנמסרו לידם גם ה\"טמאים. . ורשעים. . וזדים\" מבנ\"י גופא<sup data-n=\"1786\">17</sup>.\nוזה מגדיל ביותר את הנס — ומשתי הבחינות: הן נצחון המלחמה כפשוטו, וכמובן בפשטות גודל הנס כאשר מבנ\"י היו לצידם של היוונים, ומ\"מ נצחו ה\"טהורים. . צדיקים. . עוסקי תורתך\"; והן מצד רוחניות הענינים, זה שהקב\"ה עשה לישראל נס זה [שזהו תוכן אמירת \"ועל הניסים\", להדגיש שלא הי' זה נצחון טבעי אלא נס שנעשה ע\"י הקב\"ה, \"ואתה ברחמיך הרבים עמדת להם בעת צרתם רבת כו' דנת כו' נקמת כו' מסרת כו'\"] — דאע\"פ שכמה מישראל לא היו ראויים לנס זה, מ\"מ התחשב הקב\"ה עם המיעוט שהיו \"טהורים. . צדיקים. . עוסקי תורתך\" ועשה להם נס זה.\nג. ולפי פירוש זה (ש\"מסרת כו' טמאים כו' ורשעים כו' וזדים כו'\" קאי על המתיוונים מבנ\"י), יש לבאר ג\"כ הא דנקט ג' תוארים אלו דוקא, באופן של \"דבר והיפוכו\" (כנ\"ל ס\"א) — \"טמאים ביד טהורים ורשעים ביד צדיקים וזדים ביד עוסקי תורתך\" — כי הניגוד בג' דברים אלה<sup data-n=\"1787\">18</sup> שייך (לאמיתתו) רק בבנ\"י גופא (ולא בהיחס שבין ישראל לעמים).\nכלומר: בהיחס בין ישראל לעמים, לא מתאים כ\"כ לתאר האומות כ\"טמאים. . רשעים. . זדים\" בניגוד לבנ\"י שהם \"טהורים. . צדיקים. . עוסקי תורתך\" — כי גדר טהרה וצדקות ועסק התורה אצל בנ\"י הוא מסוג אחר לגמרי מכפי שהם אצל ב\"נ ואין זה בגדרם כלל (כדלקמן), ובמילא לא שייך לומר שהם מנגדים לישראל בענינים אלו (מצד זה שהם \"טמאים. . ורשעים. . וזדים\"), דכשם",[["1784","15","ל' הרמב\"ם ריש הל' חנוכה."],["1785","16","ובאלי' רבה (או\"ח שם) פי' כן התיבות \"זדים ביד עוסקי תורתך\", ד\"זדים\" קאי על פריצי ישראל שבאותו זמן."],["1786","17","אלא מפני כבודם של ישראל לא מזכירים בפירוש שקאי על בנ\"י."],["1787","18","משא\"כ בפ\"ע, שהרי העכו\"ם נק' טמאים ורשעים וזדים, כמו שהביא באבודרהם כאן (סדר תפלת חנוכה ופירושה) מקראי \"העכו\"ם נקראים רשעים שנאמר (עקב ט, ד) וברשעת הגוים האלה וישראל נקראים צדיקים שנאמר (ישעי' ס, כא) ועמך כולם צדיקים. . העכו\"ם נק' טמאים שנא' (ישעי' נב, א) כי לא יוסיף יבא בך עוד ערל וטמא וישראל נק' טהורים וטהרתם (יחזקאל לו, כה), וזדים ביד עוסקי תורתך ע\"ש (תהלים קיט, סט) טפלו עלי שקר זדים\".\nאבל ע\"פ המבואר לקמן בפנים (והערה 27) י\"ל, שעיקר גדרם של תוארים אלה שייכים בישראל דוקא, ובקראי הוא שם המושאל כו'."]]],[1301410276,"שלא שייך אצלם הענין ד\"טהורים. . צדיקים. . עוסקי תורתך\" כפי שהם בבנ\"י, כך לא שייך לומר שהם מנגדים לדברים אלו ועושים הפכם.\nוהביאור בזה:\nגדר טומאה וטהרה (\"טמאים ביד טהורים\") — ע\"פ הלכה — שייך רק ב­ישראל, כי הגוי אינו מיטמא, ובלשון הרמב\"ם<sup data-n=\"1788\">19</sup> \"עכו\"ם שנגע במת כו' ה\"ה כמי שלא נגע הא למה זה דומה לבהמה שנגעה במת כו' ולא בטומאת המת בלבד אלא בכל הטומאות כולן אין העכו\"ם ולא הבהמה מתטמאין בהן\", שכוונת הרמב\"ם באריכות לשונו (\"ה\"ה כמי שלא נגע הא למה זה דומה לבהמה כו'\") היא, דזה שהעכו\"ם אין מתטמאין, אין הפירוש בזה שרק נפקעו בפועל מדין טומאה, אלא שאינם בגדר טומאה וטהרה, דל­ענין זה אינם מציאות<sup data-n=\"1789\">20</sup> שיכול לחול עלי' שם טומאה, וכמו בהמה שאינה בגדר זה כלל;\nענין הצידקות (והפכו) בבנ\"י תלוי בקיום תרי\"ג מצות שניתנו לישראל דוקא, משא\"כ ב\"נ, שענין הצידקות וה­רשעות הוא רק בקיום ז' מצות שלהם, שהחילוק בין תרי\"ג מצות של ישראל וז' מצות ב\"נ אינו רק במספר המצות (ז' או תרי\"ג) אלא הם שני סוגים שונים ב­החלט, כמבואר במ\"א בארוכה<sup data-n=\"1790\">21</sup>,\n[שלכן מצינו שעיקר הענין דשכר ועונש הוא רק בישראל<sup data-n=\"1791\">22</sup>, כמ\"ש<sup data-n=\"1792\">23</sup> \"רק אתכם ידעתי מכל משפחות האדמה על כן אפקוד עליכם את כל עוונותיכם\", \"איננו<sup data-n=\"1793\">24</sup> חושש עליהם אם ייטיבו או יריעו. . וכן ארז\"ל<sup data-n=\"1794\">25</sup> שאני עכו\"ם דלא מפקיד דינא עלייהו\" (\"אין ממהרין מן השמים לפקוד עוונותם עליהם\"<sup data-n=\"1795\">26</sup>), והיינו שאין מעשיהם חשובים לפני המקום לה­חשב חטא, וכמו שארז\"ל עה\"פ<sup data-n=\"1796\">27</sup> \"חטא חטאה ירושלים\" — \"אוה\"ע כו' אע\"פ ש­חוטאין אינן כלום\"];\n\"זדים ביד עוסקי תורתך\" — השם \"עוסקי תורתך\" שייך רק בבנ\"י, שהרי \"עכו\"ם שעוסק בתורה חייב מיתה\"<sup data-n=\"1797\">28</sup> [דאף שב\"נ חייבים ללמוד ההלכות ד­\"שבע מצות דידהו\"<sup data-n=\"1797\">28</sup> — מ\"מ אינם בגדר \"עוסקי תורתך\", שהם רק העוסקים ב­תורת ה' שניתנה לישראל דוקא], וכיון שאין העכו\"ם בגדר \"עוסקי תורתך\", הרי מובן, שאינם גם בגדר \"זדים\" המנגדים ל\"עוסקי תורתך\".",[["1788","19","הל' טומאת מת פ\"א הי\"ג."],["1789","20","ראה גם ראב\"ד הל' אבות הטומאות (פ\"ב ה\"י) \"העכו\"ם הם כבהמות ואין מטמאין ואין מיטמאין עם הדומה לחמור כו' ואת כולם ישא רוח כו'\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181175\" data-slug=\"likkutei-sichot\" data-id=\"1300181175\">לקו\"ש חי\"ח ע' 166</a>."],["1790","21","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051171\" data-slug=\"likkutei-sichot\" data-id=\"1300051171\">לקו\"ש ח\"ה ע' 159</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241165\" data-slug=\"likkutei-sichot\" data-id=\"1300241165\">חכ\"ד ע' 165</a>. ועוד."],["1791","22","וראה (ע\"ד החסידות) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540666\" data-slug=\"torat-chaim\" data-id=\"2300540666\">תו\"ח שמות קעא, א</a> ואילך. מאמרי אדמו\"ר האמצעי דברים ח\"א ע' נא ואילך. ועוד."],["1792","23","עמוס ג, ב."],["1793","24","רד\"ק עמוס שם. וראה גם ראב\"ע שם."],["1794","25","סוטה כא, רע\"א. ולהעיר ממחז\"ל (ב\"ק לח, א) \"ז' מצות. . עמד והתירן להן. . כמי שאינו מצווה ועושה\"."],["1795","26","רש\"י סוטה שם. וראה גם ע\"ז ד, א (וברש\"י שם ד\"ה נפרע ממנו)."],["1796","27","איכה א, ח. איכ\"ר שם. וראה אוה\"ת לנ\"ך (ח\"ב) עה\"פ (ע' א'סב) [ושם \"שלכן נק' ישראל עברים ששייך בהם עבירה ותשובה\", שמזה מובן שהענין ד\"רק אתכם ידעתי גו'\" אינו רק לענין שכר ועונש, אלא לעצם שם עבירה והפכו]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071032\" data-slug=\"likkutei-sichot\" data-id=\"1300071032\">לקו\"ש ח\"ז ס\"ע 32</a> ואילך."],["1797","28","סנהדרין נט, א. רמב\"ם הל' מלכים פ\"י ה\"ט."],["1797","28","סנהדרין נט, א. רמב\"ם הל' מלכים פ\"י ה\"ט."]]],[1301410277,"ד. ומכאן עידוד וחיזוק גדול לבנ\"י בדורנו זה, שנוסף לזה ש\"אתם המעט מכל העמים\"<sup data-n=\"1799\">29</sup>, הנה גם מבנ\"י גופא, הרי שומרי תומ\"צ בשלימות (ולכל פרטיהן) הם לע\"ע מיעוט לגבי שאר אחבנ\"י שליט\"א, וההתבוננות במצב זה יכולה להביא את האדם לידי יאוש ח\"ו, או עכ\"פ לגרום חלישות — דכיצד יזכו בנ\"י לגאולה האמתית והשלימה שתלוי' בתשובה (דאין ישראל נגאלין אלא בתשובה<sup data-n=\"1800\">30</sup>), כאשר כמה מישראל עדיין רחוקים מזה?\nוע\"ז ישנו הלימוד בכ\"ש וק\"ו מימי חנוכה, דכמו בימי חנוכה שאז היו \"טמאים. . ורשעים. . וזדים\", ומ\"מ ניצחו ה\"טהורים. . צדיקים. . עוסקי תורתך\", ועד\"ז בדורנו, כאשר כמה מ­ישראל שאינם שומרי תומ\"צ בשלימות לע\"ע הרי הם \"תינוקות שנשבו\" — וה\"טהורים. . צדיקים. . עוסקי תורתך\" עומדים על משמרתם במס\"נ על שמירת התומ\"צ, הרי הקב\"ה עוזרם וכו' ועד שמביא ישועה והצלה לעולם.\nועוד זאת — שניתן להם הכח להת­גבר על אלו שאינם \"טהורים כו'\", כי זה שהטהורים כו' הם המיעוט, זהו בכמות, אבל באיכות הרי הטהורים כו' העיקר, כי להם יש התוקף של קדושה שמקורה בקדושתו של מקום, ואילו תוקפם של \"טמאים. . ורשעים. . וזדים\" הוא גשמי בלבד.\nולכן סו\"ס הם המנצחים באופן של \"מסרת\", שלא זו בלבד שצד הקדושה מ­נצח, אלא עוד זאת, שהצד שכנגד נמסר ביד הקדושה, שהם נהפכים לטוב, \"נכב­שים\" תחת שליטת הקדושה, עד שנ­הפכים להיות \"טהורים. . צדיקים. . עוסקי תורתך\".\nה. כשם שהוא בנוגע לכלל ישראל — כמו\"כ הוא אצל כל אחד ואחת:\nאחז\"ל<sup data-n=\"1801\">31</sup> \"הרבה עשו. . כרשב\"י ולא עלתה בידם\", דרוב בנ\"י אינם יושבי אהל אלא בעלי עסק, שרוב היום עסו­קים הם בצרכיהם הגשמיים, ומיעוט ה­יום עוסקים הם בדברים שבקדושה ממש — תפלה, קביעות עתים לתורה וקיום המצות.\nוגם שעושים כל מעשיהם \"לשם שמים\"<sup data-n=\"1802\">32</sup> ו\"בכל דרכיך דעהו\"<sup data-n=\"1803\">33</sup> — הרי נקראים \"מעשיך\" ו\"דרכיך\", אלא שנע­שים \"לשם שמים\".\nואולי אפשר שתעלה בלבו של אדם מחשבת \"מרה שחורה\", דכיצד יש ב­יכולתו לקיים הציווי \"ועשו לי מקדש ושכנתי בתוכם\"<sup data-n=\"1804\">34</sup> — בתוך כאו\"א מישר­אל, שקדושתו ית' תשרה בתוכו ובתוך ביתו ממש — כאשר רוב זמנו בענינים גשמיים?\nובזה הלימוד מימי חנוכה, דזה ש­מדמה בנפשו שרק \"מיעוטו\" מושקע בטהרה וצדקות ועסק התורה — ה\"ז רק בכמות, אבל באיכות — עיקרו הם אותם השעות שעוסק בתפלה ובתורה ובמצות, והם הם הקובעים את מציאותו האמיתית.\nועוד זאת: ע\"י הכרה זו גופא, זוכה ל\"מסרת כו' וטמאים ביד טהורים ו­רשעים ביד כו'\" — שגם בעת עסקו",[["1799","29","ואתחנן ז, ז."],["1800","30","סנהדרין צז, ב. רמב\"ם הל' תשובה פ\"ז ה\"ה."],["1801","31","ברכות לה, ב."],["1802","32","אבות פ\"ב מי\"ב."],["1803","33","משלי ג, ו."],["1804","34","תרומה כה, ח.‑!‑!?‑!¯‑!?‑!?‑!?‑!ג‑!ס‑!ץ‑!$‑!-‑!צ‑!ק‑!אָ‑!?‑!3‑!4‑!›‑!?‑!"]]],[1301410278,"בדברים גשמיים, נרגש אצלו שכל זה אינו העיקר שלו, והם טפלים לעיקרו ומהותו האמיתית, שהיא עבודת ה'.\nומכאן למדנו ג\"כ עידוד לאלו החוזרים בתשובה, שגם אם כמה ימים בעבר היו ר\"ל במצב של \"טמאים\", ועוד זאת — \"רשעים. . וזדים\", יצרם התגבר עליהם אז — ומרגישים עצמם \"חלשים\" ו\"מעטים\" — הנה עליהם לידע, שהם לאמתתם \"טהורים. . צדיקים. . עוסקי תורתך\", וזהו עיקר מציאותם, ועי\"ז יתגברו על העבר שלהם,\nוכאו\"א יבנה את \"מקדשו\" הפרטי — בתחילה מטהר את עצמו מכל עניניו הבלתי רצויים, \"ופנו את היכלך וטהרו את מקדשך\", ואח\"כ מדליק נר נשמתו (נר ה' נשמת אדם) — \"והדליקו נרות בחצרות קדשך\", עד שזוכה \"להודות ולהלל לשמך הגדול\".\n<span data-k=\"q\">(משיחת ש\"פ מקץ תשל\"ב) </span>"],[1301410279,"<h3>שיחה א</h3>\nא. בריש פרשתנו בדברי יהודה ל­יוסף מדוע הוא נכנס למריבה עבור בנימין יותר משאר אחיו, נקט הכתוב לשון של \"ערבות\", \"כי עבדך ערב את הנער\"<sup data-n=\"1805\">1</sup>, וכן הוא גם לעיל בפ' מקץ<sup data-n=\"1806\">2</sup> (בדברי יהודה ליעקב), \"אנכי אערבנו\".\nבמהותה וגדרה של ערבות זו מצינו פלוגתא בש\"ס<sup data-n=\"1807\">3</sup>: א\"ר הונא מנין לערב דמשתעבד (באמירה בעלמא בלא קנין. רשב\"ם) דכתיב אנכי אערבנו מידי תבק­שנו, מתקיף לה רב חסדא הא קבלנות היא דכתיב<sup data-n=\"1808\">4</sup> תנה אותו על ידי ואני אשיבנו (כלומר כאילו קבלתיו<sup data-n=\"1809\">5</sup> בידי אחזירנו לך. רשב\"ם) אלא אמר רבי יצחק מהכא לקח<sup data-n=\"1810\">6</sup> בגדו כי ערב זר גו' ואומר<sup data-n=\"1811\">7</sup> בני אם ערבת לרעך תקעת לזר כפיך כו'\".\nוהנה, אף שמפשטא דגמ' משמע ש­נדחו דברי ר\"ה, מצינו בכ\"מ<sup data-n=\"1812\">8</sup> שדין ערב (שערב משתעבד מן התורה) נלמד מ­ערבות יהודה שאמר אנכי אערבנו [וגם במדרשים<sup data-n=\"1813\">9</sup> ריש פרשתנו סמך דיני ער­בות לערבות דיהודה].\nומבואר במפרשים<sup data-n=\"1814\">10</sup> דרב הונא ורב חסדא אזלי לטעמייהו לקמן בגמ'<sup data-n=\"1815\">11</sup> בדין האומר \"הלוהו ואני פורע\", \"הלוהו ואני נותן\", שלדעת ר\"ה לשון ערבות הן, ולדעת ר\"ח לשון קבלנות הן, ולכן ר\"ה לטעמי' ס\"ל דיהודה הי' ערב<sup data-n=\"1816\">12</sup>, ולכן נקטו כמה פוסקים כן להלכה (שלמדים דין ערבות מיהודה), כי גם רבא ס\"ל בגמ' שם ש\"כולן לשון ערבות הן\"<sup data-n=\"1817\">13</sup>.\nויש להבין: לכאורה קושיית רב חסדא אינה רק ש\"הא (דיהודה) קבלנות היא\" (כלשון הרשב\"ם \"כאילו קבלתיו",[["1805","1","פרשתנו מד, לב ובפרש\"י. וראה תנחומא פרשתנו ה. תנחומא באבער שם ד. ועוד."],["1806","2","מג, ט."],["1807","3","ב\"ב קעג, ב."],["1808","4","מקץ מב, לז. והוא מדברי ראובן ולא מדברי יהודה. וראה חדא\"ג מהרש\"א שם. וראה גם על הגליון ב\"מסורת הש\"ס\" — משאילתות שהובא לקמן בפנים. עץ יוסף לתנחומא ריש פרשתנו."],["1809","5","הגהות הב\"ח ברשב\"ם."],["1810","6","משלי כ, טז."],["1811","7","שם ו, א."],["1812","8","רש\"י גיטין נ, א ד\"ה כיון \"וערב משתעבד מה\"ת דכתיב אנכי אערבנו\" (ועד\"ז ברש\"י כתובות קב, סע\"א). [ודוחק לומר שרש\"י נקט דרשה הרא­שונה ולא נחית להביא מסקנת הגמ', כדרכו בכ\"מ (כידוע שרש\"י פרשן ולא פסקן — ובפרט בפירושו עה\"ת), כי כותב \"משתעבד מה\"ת\" (\"שעבודא דאורייתא\"), ולדרשה הב' הרי נלמד ממ\"ש במשלי (כתובים)<sup data-n=\"e47\">*</sup>]. וכן מפורש ביד רמ\"ה ב\"ב שם. מרדכי ב\"מ פ\"ז (צד, א). מדרש שכל טוב מקץ מג, ט (בפעם הב'). וכן הביא הב\"י בטחו\"מ ר\"ס קכט. וראה גם לבוש חו\"מ שם."],["1813","9","תנחומא. ב\"ר."],["1814","10","יד רמ\"ה ב\"ב שם. ט\"ז שם סקכ\"ט ס\"ב. ועוד. וראה פרישה לטחו\"מ שם. וראה תו\"ש מקץ שם אות יג."],["1815","11","ב\"ב קעד, א."],["1816","12","ועפ\"ז מובן זה שהביא ר\"ה מהכתוב לא רק \"אנכי אערבנו\" אלא גם \"מידי תבקשנו\" (אבל ראה דק\"ס מכ\"י שהובא רק \"אנכי אערבנו\", וכבפרש\"י גיטין וכתובות הנ\"ל)."],["1817","13","וגם ב\"תן לו ואני פורע\", \"תן לו ואני חייב\", שלדעת ר\"ה לשון קבלנות הן — הרי \"רבא אמר כולן לשון ערבות הן בר מתן לו ואני נותן\" (ולהעיר מרבינו גרשום שם)."],["e47","*","וראה גם פרישה שבהערה 10."]]],[1301410280,"בידי אחזירנו לך\"), אלא כגירסת ה­שאילתות<sup data-n=\"1818\">14</sup> בקושיית ר\"ח ד\"יהודה גופי' לוה הוא דכתיב<sup data-n=\"1819\">15</sup> שלחה הנער אתי\"<sup data-n=\"1820\">16</sup>, ובכגון דא הרי גם רב הונא ס\"ל לכאו­רה שאינו לשון ערבות?\nוגם דברי רב הונא טעונים ביאור, דמה ענין דין ערבות בממון לערבות דיהודה, שלכאורה לא שייך בזה דין ערבות — ואינו חיוב ממון<sup data-n=\"1821\">17</sup> (ושעבוד ד­דין ערבות)<sup data-n=\"1822\">18</sup>.\nולכן נ\"ל, שאין כוונת ר\"ה שאצל יהודה הי' דין ושיעבוד של ערבות, אלא כיון שיהודה הגדיר הבטחתו ליעקב ב­שם \"ערבות\" — למדין מזה דין ערבות בממון, כדלקמן.\nב. ביאור הדבר:\nשעבודו של ערב יש לבארו בשני אופנים: א) השעבוד שייך רק להחוב, ד­משעבד נפשי' לשלם חובו של הלוה, ב) הערב עומד במקום הלוה, ולכן שעבוד הגוף שעל הלוה לשלם חובו (ופריעת בע\"ח מצוה), חל על הערב<sup data-n=\"1823\">19</sup> (העומד במקומו)<sup data-n=\"1824\">20</sup>.\nויש לומר, שזוהי כוונת רב הונא שלומד דין ערבות מערבות הנאמר ביהודה, כי ס\"ל ששעבוד (הגוף של) ה­ערב (בכל ערב<sup data-n=\"1825\">21</sup>) הוא (לא רק על החוב, אלא הוא) כשעבוד הגוף שעל הלוה, כי הוי כאילו הערב בעצמו קיבל המעות מיד המלוה<sup data-n=\"1826\">22</sup>. וע\"ז שפיר יש להביא סמוכין מערבות דיהודה, שהי' באופן ש­שעבד נפשו לגמרי (\"ואני נתקשרתי בקשר חזק להיות כו'\"<sup data-n=\"1827\">23</sup>), \"אנכי אערבנו מידי תבקשנו\".\nמשא\"כ ר\"י ס\"ל שדין ערבות נלמד ממ\"ש \"בני אם ערבת לרעך תקעת לזר כפיך גו'\", משום שלדעתו דין ערבות ד­ממון שייך רק להממון דהחוב שמתחייב לשלם ממון, ואין זה שעבוד הגוף כמו הלוה [ולסברא ודיעה זו הקשה ר\"ח ד­ערבות דיהודה \"הא קבלנות היא\", או כגירסת השאילתות \"התם יהודה גופי' לוה הוא\", כי אופן הערבות דיהודה ל­החזיר את בנימין הוא ע\"י שהעמיד עצמו במקומו (לא השתדלות וחיוב להחזיר את בנימין), לא ערב סתם אלא כמו קבלן או לוה, משא\"כ ר\"ה ס\"ל דגם בחוב דממון בפשטות השעבוד הוא משום שחובו של חבירו הלוה הריהו כשלו, וממילא מ­שעבד נפשו]. ולכן למד ר\"י מהכתוב \"בני אם ערבת לרעך תקעת לזר כפיך וגו'\", שמודגש בהכתוב<sup data-n=\"1828\">24</sup> שהוא אדם זר, אלא שנעשה ערב לו.",[["1818","14","שאילתא לא (פ' מקץ) — הובא במסורת הש\"ס ב\"ב שם. וראה שאילת שלום לשאילתות שם."],["1819","15","מקץ מג, ח."],["1820","16","ולהעיר מתנחומא ריש פרשתנו: איזהו ערב שהוא חייב לשלם האומר הלוהו ואני נתן [כ\"ה בתנחומא] לך ונשא ונתן ביד הערב חייב ומי הי' זה הערב זה יהודה שאמר תנה אותו על ידי ואני אשיבנו כו'. וראה עץ יוסף שם."],["1821","17","להעיר מרמב\"ם הל' מלוה ולוה פכ\"ה הי\"ד ובראב\"ד שם. ובארוכה בשו\"ת שואל ומשיב מהדורא ד' ח\"א סמ\"ה."],["1822","18","וראה בארוכה העמק שאלה לשאילתות שם. תו\"ש שם."],["1823","19","ולפ\"ז, זה שאינו גובה מן הערב אלא א\"כ גובה תחילה מן הלוה (ב\"ב קעג, ב ואילך) הוא כעין תנאי בערב ולא מעצם גדרו. ואכ\"מ."],["1824","20","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261147\" data-slug=\"likkutei-sichot\" data-id=\"1300261147\">ראה גם ע\"ד</a> השקו\"ט בגדר שעבוד הערב — לקו\"ש חכ\"ו ע' 147. וש\"נ."],["1825","21","לא רק בקבלן."],["1826","22","ראה תוס' רי\"ד קדושין ח, ב. ובהנסמן בלקו\"ש שם."],["1827","23","רש\"י פרשתנו שם (מד, לב)."],["1828","24","ראה פירוש הרלב\"ג ומצו\"ד משלי שם (ו, א)."]]],[1301410281,"ג. ויש להוסיף ביאור בזה ששעבוד הערב (לדעת רב הונא) הוא באופן ש­עומד במקום הלוה ממש — שזהו מצד דין ערבות הכללי של כל ישראל, דכל ישראל ערבים זה בזה<sup data-n=\"1829\">25</sup>:\nכשם שמצינו לענין ברכת המצות<sup data-n=\"1830\">26</sup>, \"שאף מי שאינו מחויב בדבר מפני ש­כבר יצא י\"ח יכול לברך למי שעדיין לא יצא. . לפי שבמצות שהן חובה כל ישראל ערבים זה בזה וגם הוא נקרא מחויב בדבר כשחבירו לא יצא י\"ח עדיין\"<sup data-n=\"1831\">27</sup> — והיינו מפני ש\"גדר דערבות משום שכל ישראל הוה כמו מין יחיד\"<sup data-n=\"1832\">28</sup>, \"גוף אחד<sup data-n=\"1833\">*28</sup> ומציאות אחת\"<sup data-n=\"1834\">29</sup> (כי כל ישראל הם גדר ציבור, שאינו רק צירוף של ריבוי פרטים אלא שכל הציבור הוא מציאות אחת)<sup data-n=\"1835\">30</sup>,\n[וכמבואר בספרים<sup data-n=\"1836\">31</sup> הפירוש ב\"כל ישראל ערבין זב\"ז\" — ש\"ערבין\" הוא גם מלשון מעורבים, שכל ישראל מעורבים זה בזה, דכל ישראל ביחד נקראים אדם אחד והם קומה אחת, ולפיכך הם ערבים זה לזה כי כשנעשה פגם ברגל עד\"מ כל הגוף מרגיש<sup data-n=\"1837\">32</sup>],\nובמילא החיוב שעל חבירו חל גם עליו עד ש\"גם הוא נקרא מחויב בדבר\",\nכמו\"כ הוא לענין חיוב ממון, שמצד דין ערבות דכל ישראל ערבין זב\"ז, חיוב<sup data-n=\"1838\">33</sup> תשלומין שעל הלוה חל על חבירו הערב כאילו הוא לוה המעות ונתחייב בתשלום חוב זה<sup data-n=\"1839\">34</sup>.\nועפ\"ז יש לבאר פלוגתא הנ\"ל במקור דין ערבות בעומק יותר — שתוכן",[["1829","25","שבועות לט, סע\"א. סנהדרין כז, סע\"ב. וראה סוטה לז, ב ובפרש\"י ותוס' שם. פרש\"י סנהדרין מג, ב ד\"ה עד שעברו. ועוד."],["1830","26","רש\"י ר\"ה כט, סע\"א."],["1831","27","ל' אדה\"ז בשו\"ע או\"ח סקס\"ז סכ\"ג. ועד\"ז הוא שם סקצ\"ז ס\"ו מתוד\"ה עד ברכות מח, סע\"א בסופו (ע\"ב), במה שהגדול יכול להוציא אחר בברהמ\"ז גם כשלא אכל כלל. ולהעיר מריטב\"א קידושין כז, א ד\"ה גמרא אמר עולא, לענין גלגול שבועה ד\"בעלמא קיי\"ל דאין ב\"ד פותחין לו לגלגל (שבועה) עד דטעין תובע. . שאני סוטה דהוי איסורא וכל ישראל ערבין זל\"ז ומחייבי לאפרושי מאיסורא ובעלי דבר חשיבי\". וראה קרית ספר להמבי\"ט בהקדמה פ\"ז הדרך הא'."],["1832","28","צפע\"נ סנהדרין מג, ב (בגמ' ד\"ה לפי שלא)."],["1833","*28","ראה ירושלמי נדרים פ\"ט ה\"ד."],["1834","29","צפע\"נ מכות כד, א (סד\"ה בגמ' משה אמר ובגוים)."],["1835","30","וראה גם צפע\"נ מהד\"ת צ, ב (נעתק ב­צפע\"נ מכות שם)."],["1836","31","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380444\" data-slug=\"likkutei-torah\" data-id=\"4001380444\">לקו\"ת בהעלותך לג, ג</a>. וראה גם שם שה\"ש לה, ד."],["1837","32","וראה בארוכה אוה\"ת ריש פרשתנו (כרך ה' תתקפא, ב ואילך)."],["1838","33","ולדיעה זו דין ערבות דישראל שנעשה ערב לעכו\"ם הוא רק התחייבות לשלם החוב (כדעת ר\"ח בכל ערב), אבל אינו כאילו עומד במקום הלוה ממש."],["1839","34","ולפ\"ז צ\"ל דמ\"ש בגמ' (ב\"ב שם קעג, ב) \"בההיא הנאה כו' גמר ומשתעבד נפשי'\" הוא ה­טעם<sup data-n=\"e48\">*</sup> שהערב מסכים לשעבד את נפשו, אבל ה­שעבוד בפועל הוא לא רק התחייבות תשלום ממון מצד ההנאה כו', אלא שעבוד נפשי לעמוד במקום הלוה. וצ\"ע.\nולהעיר מנמוק\"י ב\"ב שם ועוד, דשעבוד הערב הוא מצד זה שהמלוה הוציא ממון על פיו. ודברי ר\"א בההיא הנאה הוא רק טעם ע\"ז דלא הוי אסמכתא. ועד\"ז הוא לכמה דיעות — ראה לקו\"ש חכ\"ו שם."],["e48","*","או י\"ל דמאמר ר\"א בגמ' בההיא הנאה כו' הוא רק לפי לימוד דר\"י דלמדין מ\"בני אם ערבת גו'\".\nאבל במדרש שכל טוב שבהערה 8 מבאר טעם דר\"א בההיא הנאה כו' לגבי יהודה — \"ובההיא ה­נאה דקא האמין לי' שעבד נפשי' בנידוי כל הימים\", וממשיך אח\"כ \"ואע\"ג דר\"ח כו' אנן סבירא לן כרב הונא כו'\". ע\"ש. וראה גם מרדכי שבהערה 8."]]],[1301410282,"פלוגתתם היא, אם הגדר דערבות ממון שייך ובא מזה שכל ישראל ערבין זב\"ז.\nביאור הדבר:\nסיבת אחדות זו שבישראל שכל ישר­אל מעורבים זה בזה (ומשום כך הם מציאות אחת) היא מפני נשמתם, ששרשה \"בה' אחד\"<sup data-n=\"1840\">35</sup> (שלכן אין דין ציבור ב­ב\"נ<sup data-n=\"1841\">36</sup>), משא\"כ מצד גופם, הרי \"הגופים מחולקים\"<sup data-n=\"1842\">37</sup> [וכפי שמבאר רבינו הזקן<sup data-n=\"1840\">35</sup>, שמטעם זה \"קיום מצות ואהבת לרעך כמוך לכל נפש מישראל למגדול ועד קטן\" הוא ע\"י שהאדם עושה נשמתו עיקר<sup data-n=\"1844\">38</sup>].\nובזה פליגי, אם האחדות שבישראל (שכולן מציאות אחת ו\"מעורבים זב\"ז\"), היא רק בעניני נשמתו (כמו בקיום מ\"ע או חיוב תוכחה ומחאה על עון וכו'<sup data-n=\"1845\">39</sup>), או שאחדות זו שייכת גם לממונו של האדם:\nלדיעה הא', כיון שענינם של ישראל הוא מה שהם \"גוי אחד בארץ\", כפירוש רבינו הזקן<sup data-n=\"1846\">40</sup> שגם בעניני \"ארץ\" (ענינים ארציים וגשמיים) מגלים אחדות הוי', לכן אפשר לגלות גם בעניני ממון את האחדות שבישראל שהם ערבים ומעור­בים זב\"ז,\nאבל לפי הדיעה הב' (שמפשטות המשך הגמ' משמע שכ\"ה המסקנא) — \"התורה על הרוב תדבר\"<sup data-n=\"1847\">41</sup>, ואי אפשר לרוב ישראל שתפעול (ע\"י שתתגלה) אחדות כזו (הפועלת ענין הערבות דכל ישראל ערבין ומעורבין זב\"ז) גם ב­דברים גשמיים ועניני ממון<sup data-n=\"1848\">42</sup> של הזולת, ולכן ס\"ל שהוא דין בפ\"ע, שהערב מ­שעבד את עצמו לשלם חוב חבירו.\nד. עפ\"ז יש לבאר הטעם (הפנימי) שדין ערבות בממון נלמד (לדעת ר\"ה) מערבות דיהודה דוקא — דיש לומר, ש­ערבותו על בנימין מורה על אופן מיוחד בערבות, שהיא תוצאה מאופן נעלה ביותר באחדות ישראל, ומצד דרגא זו באחדות נמשכת האחדות גם בעניני ה­רשות (והגשמיים) של ישראל.\nויובן זה בהקדם תוספת ביאור בהא דכל ישראל ערבים ומעורבים זב\"ז, ד­נת\"ל שהוא כמו האדם שיש לו ראש ורגל כך כל ישראל ביחד נקראים אדם אחד וקומה אחת — שכשם שה\"אחדות\" שבאברי הגוף יש בה כמה אופנים כ\"ה גם באחדות דישראל:\nא) שלימות הגוף תלוי' בזה שישנם בו כל האברים, כי כשחסר אחד מהם, אף אם הוא האבר הפחות ותחתון ביותר, כל הגוף אינו גוף שלם.\nב) למעלה מזה הוא — שכל אברי הגוף משלימים זא\"ז, כי כולם צריכים זל\"ז, וכמו שעל ידי הקזת הדם ברגל יתרפא הראש, וכן הרגל מעמיד את הראש ומוליך אותו, אשר מצד ענין זה נק' הרגל ראש והראש רגל (כי בענין זה מקבל הראש מן הרגל), וכל אבר הוא \"ראש\" מצד מעלתו הפרטית שהוא",[["1840","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."],["1841","36","נזיר סא, ריש ע\"ב. צפע\"נ שבהערה 28; 30."],["1842","37","ל' אדה\"ז ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא שם</a>. וכלשון זה כתב הרדב\"ז להל' ממרים פ\"ב ה\"ד. ע\"ש."],["1840","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."],["1844","38","ראה גם רדב\"ז שם."],["1845","39","ראה רא\"ש ברכות פ\"ג סוסי\"ג. ריטב\"א שבהערה 27 וכן בע\"ז ו, ב. שו\"ע אדה\"ז או\"ח סקצ\"ז ס\"ו. סתמ\"ג ס\"ז. סתר\"ח ס\"ה. שו\"ת חת\"ס יו\"ד סי\"ט. חו\"מ סקע\"ז (ד\"ה ומ\"ש פר\"מ ואילך). קרית ספר להמבי\"ט שם. ועוד."],["1846","40","אגה\"ק ס\"ט (קיד, רע\"א)."],["1847","41","ראה מו\"נ ח\"ג פל\"ד."],["1848","42","כדברי הריטב\"א דלעיל הערה 27, שמחלק בזה בין איסורא לממונא."]]],[1301410283,"משפיע בשאר כל האברים, ועד באופן ש\"לא ימצא בהם ראש וסוף\"<sup data-n=\"1849\">43</sup>.\nאבל בשני אופנים אלו עדיין ישנה התחלקות בין האברים, דלא מיבעי באופן הא', ששלימות הגוף תלוי' בזה שישנם רמ\"ח אברים, שזהו דוקא כשיש­נם רמ\"ח אברים מחולקים, היינו שיש בו כל הרמ\"ח מעלות פרטיות של כל ה­רמ\"ח אברים, שעל ידי כולם יחד נוצרת \"קומה אחת שלימה\"; אלא גם לפי האופן הב', שלא ניכרת כ\"כ מעלתו של אבר אחד על זולתו, שהרי כולם הם \"ראש\" — מ\"מ, מעלתו של כל אבר היא רק בענינו הפרטי, במה שהוא מחולק מחבירו.\nאבל אמיתית האחדות שבקומת הגוף היא, כאשר כל אבר מרגיש שעיקר מציאותו וענינו אינו תכונותיו הפרטיות אלא בזה שהוא חלק מגוף האדם בכל­לותו, שענין זה הוא בכל האברים ב­שווה, שכולם הם חלק מקומה זו בשווה, ומצד זה הרי הם בהתאחדות גמורה<sup data-n=\"1850\">44</sup>.\nוכן הוא גם בהתאחדות דישראל, שכל ישראל ערבין ומעורבים זב\"ז, ל­היותם קומה אחת שלימה, שישנם בזה שלשת אופנים אלו:\nא) השלימות דכלל ישראל היא כ­אשר ישנם כל הסוגים מ\"ראשיכם שבטי­כם גו'\" עד \"שואב מימיך\"<sup data-n=\"1851\">45</sup>.\nב) למעלה מזה — שכל סוג מבנ\"י משפיע ממעלתו לשאר כל ישראל, ב­אופן שכל ישראל צריכים זל\"ז ומשלי­מים זה את זה, עד שלא ימצא בהם ראש וסוף.\nג) האחדות הכי עליונה, זה שכל ישראל הם חלק מכלל ישראל, שזהו מצד נקודת היהדות שבכל אחד ואחד מישראל, שזהו בשווה ממש אצל כולם, וזהו אמיתית הענין דכל ישראל ערבין ומעורבין זב\"ז<sup data-n=\"1852\">46</sup>, שאין בזה התחלקות כלל (דראש ורגל), וכולם הם כמו נקודה אחת ממש<sup data-n=\"1853\">47</sup>.\nה. ויש לומר, שזהו אחד מהטעמים<sup data-n=\"1854\">48</sup> שדוקא יהודה הי' ערב על בנימין:\nערבותו של יהודה, שנתקשר \"בקשר חזק להיות כו' בשני עולמות\", היא ערבות עמוקה ביותר, הבאה מצד זה שכל ישראל הם עצם אחד ממש, כנקודה אחת.\nולכן היתה ערבות זו אצל יהודה דוקא, כי עיקר ענינו של יהודה הוא — מלכות [שיהודה הי' מלך שבשבטים<sup data-n=\"1855\">49</sup>,",[["1849","43","ראה לקו\"ת ר\"פ נצבים. וראה לקו\"ש ח\"ד (ע' 1141 ואילך) בביאור ב' האופנים שבלקו\"ת (שם) \"לאחדים\" \"כאחד\", שלנגד זה אומר בלקו\"ת \"כולן צריכים זל\"ז\", \"כל ישראל קומה אחת שלימה\". וראה הערה הבאה."],["1850","44","ע\"פ המבואר בהערה הקודמת י\"ל, שגם בלקו\"ת בהעלותך (שבהערה 31) בביאור ענין מקשה דהמנורה — נכללו כמה דרגות: א) נעשה מה שלמטה למעלה ונתערב הכל עליון בתחתון ותחתון בעליון, ב) קומה אחת, ג) עד ירכה עד פרחה כולם מקשה א'."],["1851","45","נצבים כט, ט­י."],["1852","46","וי\"ל שע\"פ אופן הג' הנ\"ל בהתאחדות ישר­אל שייך ערבות גם כלפי מומר, כמובן מסנהדרין מג, סע\"ב ואילך. וראה בארוכה שו\"ת עין יצחק אה\"ע ס\"א. ואכ\"מ."],["1853","47","ראה גם צפע\"נ לסנהדרין שם \"הגדר ד­ערבות משום שכל ישראל הוה כמו מין יחיד מין פרטי נקודה\"."],["1854","48","ראה ע\"ד הקבלה והחסידות — אוה\"ת פר­שתנו שם תתקפב, א."],["1855","49","ראה רש\"י ויחי (מט, ט) שיהודה נמשל לארי — \"מלך שבחיות\" (חגיגה יג, ב). וראה רש\"י וישב לח, א \"הורידוהו. . מגדולתו\"."]]],[1301410284,"וכן נתברך<sup data-n=\"1856\">50</sup> \"לא יסור שבט מיהודה גו' עד כי יבא שילה\", שממנו באה מלכות בית דוד שהיא \"עיקר המלכות\"<sup data-n=\"1857\">51</sup> שב­ישראל] — ומצד ענין המלכות מתגלה אמיתית האחדות של ישראל, שהם נקודה אחת שלמעלה מהתחלקות.\nוכמבואר במ\"א, שהמלך לא זו בלבד שהוא כולל את כל העם (שהוא מלך עליהם), אלא שעל ידו נעשים כל העם למציאות אחת (ולהעיר מלשון ה­רשב\"א<sup data-n=\"1858\">52</sup> \"המלך כצבור שהצבור וכל ישראל תלויין בו\"), ומצד זה אין הת­חלקות בעם ישראל<sup data-n=\"1859\">53</sup>, וכל מציאותם היא רק מציאות המלך<sup data-n=\"1860\">54</sup>.\nו. ע\"פ כהנ\"ל מובן גם הטעם, שה­קשר בין דין ערבות בממון להא שכל ישראל ערבין זב\"ז נסמך אקרא דערבות יהודה על בנימין:\nהכח להמשיך ענין האחדות (שמצד הנשמה) גם בעניניו הגשמיים ודברי ה­רשות של האדם, בא מהרגשת עומק אמיתית הענין דאחדות ישראל, שכל ישראל הם חד ממש,\nוע\"ד הנ\"ל בענין המלכות — שכח המלכות הוא לא רק על בני אדם, אלא כל הדברים, גם הדצ\"ח, שבמדינתו, הם תחת שליטתו וממשלתו.\nולכן, דוקא מערבות יהודה על בנ­ימין, שבזה בא לידי גילוי האופן הכי עליון באחדות ישראל (כנ\"ל סעיף ה), למדין שדין ערבות בממון שייך להא דכל ישראל ערבין זה בזה.\nז. פ' ויגש קוראים בכל שנה בסמי­כות לצום העשירי, היום שבו \"סמך מלך בבל. . על ירושלים והביאה במצור ובמצוק\"<sup data-n=\"1861\">55</sup>, וע\"פ המבואר בשל\"ה<sup data-n=\"1862\">56</sup> מובן שיש שייכות ביניהם:\nנת' במ\"א<sup data-n=\"1863\">57</sup>, ד\"סמך מלך בבל על ירו­שלים\" הוי בגדר הקדמת רפואה למכה (של גלות), דהרי סיבת תוקף הגלות היא מצד העון דשנאת חנם<sup data-n=\"1864\">58</sup>, והרפואה — ה­גאולה מן גלות — היא על ידי פעולה הפכית, אהבת חנם עד לאחדות ישראל",[["1856","50","ויחי מט, יו\"ד ובפרש\"י שם (מרז\"ל)."],["1857","51","רמב\"ם הל' מלכים פ\"א ה\"ח. וראה שם ה\"ט."],["1858","52","שו\"ת ח\"א סקמ\"ח."],["1859","53","ראה צפע\"נ סנהדרין שם ש\"הנשיא מצרף לעשות גדר ציבור\"."],["1860","54","ועפ\"ז מובן דיוק אדה\"ז באגה\"ק סכ\"ט (קמח, ב) \"לבד מצות התלויות במלך שהוא מוציא כל ישראל כי הוא כללות כולם\", כי בכתבי ה­אריז\"ל (ס' הגלגולים פ\"ד. ועוד) מבואר שכל אדם מישראל צריך לקיים את כל תרי\"ג מצות התורה במחשבה דיבור ומעשה, וע\"כ צריך לבוא בגלגולים רבים עד שיקיים את כולן, ובזה נכלל גם מצות כהנים לויים ומצות דכה\"ג שצריך לבוא בגלגול או בבחי' עיבור. אבל בנוגע למצות המלך משנה<sup data-n=\"e49\">*</sup> אדה\"ז וכותב \"שהוא מוציא כל ישראל כי הוא כללות כולם\", ולא כבמשנת חסידים (מס' חיוב הנשמות פ\"ב מ\"א) שמפני חשיבותו כל המצות הראויים לו עולים לכל ישראל. וראה גם לקו\"ת יוהכ\"פ סט, א. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181201\" data-slug=\"likkutei-sichot\" data-id=\"1300181201\">לקו\"ש חי\"ח ע' 192</a> סוף הערה 55."],["1861","55","ל' הרמב\"ם הל' תעניות פ\"ה ה\"ב. וראה מ\"ב כה, א­ב. ירמי' נב, ד­ה. יחזקאל כד, ב."],["1862","56","ר\"פ וישב. ועוד."],["1863","57","בכל הבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251267\" data-slug=\"likkutei-sichot\" data-id=\"1300251267\">לקו\"ש חכ\"ה ע' 267</a> ואילך."],["1864","58","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380666\" data-slug=\"likkutei-torah\" data-id=\"4001380666\">יומא ט, ב</a> ובחדא\"ג מהרש\"א שם. לקו\"ת מטות פו, א. ועוד. בגמ' שם הוא לגבי חורבן בית שני, אבל מובן שיש לזה שייכות גם לבית ראשון (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251268\" data-slug=\"likkutei-sichot\" data-id=\"1300251268\">לקו\"ש שם ע' 268</a> ובהערות שם)."],["e49","*","כי בס' הגלגולים שם כולל ביחד \"מצות לכהנים. . ללויים. . למלכים. . לדיינים וכיוצא\"."]]],[1301410285,"בשלימותה. ואחדות זו נעשית באופן טבעי על ידי מצור, שאז \"אין יוצא ואין בא\"<sup data-n=\"1865\">59</sup>, שכל הנמצאים במצור נמצאים תמיד ביחד בעיר; ויתירה מזו: ענינו של מצור הוא לא רק שאין יוצא ואין בא מאנשי העיר, אלא כן הוא בכל עניני העיר וכל חפצי העיר, והמכוון של המצור הוא לא (רק) שהאנשים שבתוך העיר לא יצאו אלא שלא יהי' ביכלתם להוציא ולהביא צרכי העיר, אכו\"ש ונשק וכו'.\nוהיינו שהמצור על עיר (ובפרט על עיר שהיא מוקפת חומה מצד עצמה) עושה את כל הדברים בהעיר וכל אשר בעיר מעין מציאות אחת.\nוזהו תוכן הענין דמצור על ירושלים בפרט, עיר שחוברה לה יחדיו<sup data-n=\"1866\">60</sup>, שמ­חברת את כל ישראל, שבנ\"י הם מוכר­חים בדרך הטבע להיות באחדות יחד בירושלים, הם וכל אשר להם [ובאם הי' זה מביא לאחדות אמיתית בבנ\"י, לכאו­רה הי' אז הקדמת רפואה למכה בפועל, והיתה מתבטלת המכה מלכתחילה, ו­נבוכדנאצר לא הי' יכול לשלוט עליהם. ובמכש\"כ וק\"ו מהמצב ד\"חבור עצבים אפרים\", דכשהיו<sup data-n=\"1867\">61</sup> ב\"חבור\" אף שהי' \"עצבים\" יורדין למלחמה ונוצחין].\nולכן עיקר העבודה כאשר נמצאים בזמן הגלות, בעקבתא דעקבתא דמשי­חא, הוא לחזק ולפעול ביותר בהענין דכל ישראל ערבין זב\"ז, מעורבין זב\"ז, לחזק ולפעול באהבת ישראל ובאחדות ישראל,\nופשוט שאין הכוונה ח\"ו לוותר או אפילו לעשות פשרות ח\"ו בעניני תורה ומצוות, ואדרבה, זה שכל ישראל ערבים זב\"ז מחייב את כל אחד מישראל להפ­ריש את חבירו מאיסור ומעון<sup data-n=\"1845\">39</sup>, \"הוכח תוכיח את עמיתך. . ואהבת לרעך כ­מוך\"<sup data-n=\"1869\">62</sup> [כהנהגת אהרן הכהן, כהן גדול<sup data-n=\"1870\">63</sup> \"אוהב שלום ורודף שלום אוהב את הבריות ומקרבן לתורה\", ולא שמקרב את התורה ח\"ו להבריות, פשרות וויתו­רים בקיום התורה לפי רוח הזמן וה­מקום ח\"ו].\nוהוספת ותוס' פעולה ומרץ באהבת ואחדות ישראל, תביא תיכף ומיד ממש ביאת משיח צדקנו, כמפורש בהפטרת פרשתנו<sup data-n=\"1871\">64</sup>, ויקויים ענין הגשת יהודה ליוסף בשלימות, שב' העצים (דיהודה ויוסף) \"היו לאחדים בידך. . ומלך אחד יהי' לכולם\", כי \"עבדי דוד מלך עליהם. . נשיא להם לעולם\", במהרה בימינו ממש.\n<span data-k=\"q\">(ממאמר ושיחת ש\"פ ויגש תשל\"ב; שיחת ט\"ו בשבט תשמ\"ה) </span>",[["1865","59","ל' הכתוב יהושע ו, א."],["1866","60","תהלים קכב, ג. ולהעיר מירושלמי (עה\"פ) חגיגה פ\"ג ה\"ו. וראה חגיגה כו, א."],["1867","61","הושע ד, יז. וראה ב\"ר פל\"ח, ו. תנחומא צו ז. ועוד. ירושלמי פאה פ\"א ה\"א (בנוגע לדור אחאב). תו\"א ס\"פ נח. תו\"ח שם עד, סע\"ד ואילך. אוה\"ת שם (כרך ג) תרסח א­ב. ועוד."],["1845","39","ראה רא\"ש ברכות פ\"ג סוסי\"ג. ריטב\"א שבהערה 27 וכן בע\"ז ו, ב. שו\"ע אדה\"ז או\"ח סקצ\"ז ס\"ו. סתמ\"ג ס\"ז. סתר\"ח ס\"ה. שו\"ת חת\"ס יו\"ד סי\"ט. חו\"מ סקע\"ז (ד\"ה ומ\"ש פר\"מ ואילך). קרית ספר להמבי\"ט שם. ועוד."],["1869","62","קדושים יט, יז­יח."],["1870","63","אבות פ\"א מי\"ב."],["1871","64","יחזקאל לז, טו ואילך."]]],[1301410286,"<h3>שיחה ב</h3>\nא. על הפסוק<sup data-n=\"1872\">1</sup> \"וירא את העגלות אשר שלח יוסף גו' ותחי רוח יעקב אבי­הם\" איתא במדרש<sup data-n=\"1873\">2</sup> (והובא בפרש\"י על התורה<sup data-n=\"1874\">3</sup>) שזה הי' סימן ששלח יוסף ל­יעקב, שאם לא יאמין להם יעקב ש\"עוד יוסף חי\", יאמרו לו שיוסף מסר לומר: \"בשעה שפרשתי ממך. . בפרשת עגלה ערופה הייתי עוסק\" (וזהו \"וירא את ה­עגלות אשר שלח יוסף\"<sup data-n=\"1875\">4</sup>); ובהמשך לזה מפרש המדרש<sup data-n=\"1876\">5</sup> (מש\"נ בפסוק שלאח\"ז<sup data-n=\"1877\">6</sup>) \"ויאמר ישראל רב עוד יוסף בני חי\", ש­אמר יעקב \"רב כחו של יוסף בני שכמה צרות הגיעוהו ועדיין הוא עומד בצדקו הרבה ממני כו'\". ובפשטות כוונת ה­מדרש<sup data-n=\"1878\">7</sup> לפרש \"עוד יוסף בני חי\" שהוא חי נוסף על חיים גשמיים, גם ובעיקר חיים רוחניים, חיים המתאימים לבנו של יעקב — \"עוד יוסף בני חי\"<sup data-n=\"1879\">8</sup>.\nוהנה מזה שהמדרש סמך שני הענינים זל\"ז — הסימן שמסר יוסף לאביו ש\"עוד יוסף חי\" בפשטות, ואשר יעקב הכיר שיוסף \"עומד בצדקו\" ואלה הם חייו (זהו ה\"חיים\" שלו) — מסתבר, שב' הענינים שייכים זל\"ז, כלומר: הסימן שמסר יוסף — נוסף על שהי' להודיע ליעקב שעוד הוא חי בגשמיות, בא בעיקר להוכיח שהוא \"עומד בצדקו\".\nוכמובן גם בפשטות — שזה שיוסף זוכר באיזו פרשה בתורה הי' עוסק ב­שעה שפירש מיעקב (מלפני כ\"ב שנה), ה\"ז הוכחה שתורתו שמורה אצלו והוא עומד בצדקתו כמקדם<sup data-n=\"1880\">9</sup>.\nאבל עדיין צריך ביאור: מובן ופשוט שכל מעשי האבות והשבטים (ובפרט אלה המסופרים בתורה) מדוייקים בתכ­לית. וכן בעניננו, שהסימן שמסר יוסף ליעקב שעוד הוא חי, לא הי' סתם סימן בעלמא (בענין צדדי), אלא שגם תוכן הסימן (פרשת עגלה ערופה) שייך לה­הודעה ש\"עוד יוסף חי\" (וכמו שהאריכו במפרשים בביאור השייכות שביניהם<sup data-n=\"1881\">10</sup>). ולפי הנ\"ל, שכוונת הסימן היתה להוכיח ליעקב שהוא עומד בצדקו, מובן שה­תוכן דפרשת עגלה ערופה שייך גם ל­הודעה זו.\nב. ויש לומר בזה:\nענינה של עגלה ערופה מבואר ב­פשטות הכתובים: \"כי<sup data-n=\"1882\">11</sup> ימצא חלל ב­אדמה. . נופל בשדה לא נודע מי הכהו, ויצאו זקניך ושופטיך (סנהדרי גדולה<sup data-n=\"1883\">12</sup>) ומדדו גו' והורידו זקני העיר ההיא את העגלה גו' וכל זקני העיר ההיא גו'",[["1872","1","פרשתנו מה, כז."],["1873","2","ב\"ר פצ\"ד, ג. ועד\"ז תנחומא פרשתנו יא."],["1874","3","עה\"פ (בשינוי לשון)."],["1875","4","ראה בארוכה מפרשי המדרש ומפרשי רש\"י שם."],["1876","5","ב\"ר שם."],["1877","6","מה, כח."],["1878","7","ראה גם פי' מהרז\"וו לב\"ר שם."],["1879","8","ראה אלשיך וכלי יקר כאן. ש\"ך עה\"ת ואוה\"ח לקמן מו, ל. ועוד."],["1880","9","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101161\" data-slug=\"likkutei-sichot\" data-id=\"1300101161\">לקו\"ש ח\"י ע' 161</a>."],["1881","10","לפי פשטות הענין, שהי' סימן שהוא (יוסף ש)חי כפשוטו (ראה רבותינו בעה\"ת, ריב\"א ורע\"ב עה\"ת, כלי יקר ועוד מפרשים כאן)."],["1882","11","פ' שופטים כא, א ואילך."],["1883","12","רש\"י עה\"פ (שם, ב), מסוטה מד, ב ואילך (וש\"נ)."]]],[1301410287,"ירחצו את ידיהם גו' וענו ואמרו ידינו לא שפכו את הדם הזה גו'\". ומבואר הטעם בדבר<sup data-n=\"1884\">13</sup> — כדי שיתפרסם המאורע שהי' \"חלל. . נופל בשדה\", אשר עי\"ז יהי' נקל יותר למצוא את הרוצח כו', ועוד (וגם זה עיקר) — כדי ש\"ישמעו ו­יראו גו'\" (כמובא בנוגע לכמה ענינים<sup data-n=\"1885\">14</sup>), היינו, לשלול מלכתחילה את האפשרות ד\"חלל. . בשדה\".\nוביאור הענין — בעבודת ה':\n\"חלל\" במובן רוחני הוא זה שנפסקה דביקותו בהקב\"ה, שהוא מקור חיותו, וכמש\"נ<sup data-n=\"1886\">15</sup> \"ואתם הדבקים בה' אלקיכם חיים כולכם היום\". והגורם לזה הוא להיותו נמצא \"בשדה\" (\"נופל בשדה\"<sup data-n=\"1887\">16</sup>) — מקומו של \"עשו. . איש שדה\"<sup data-n=\"1888\">17</sup>, שמת­נכל לאותם שנמצאים \"בשדה\" (ולא ב­אהלה של תורה ויהדות) לנתקם ח\"ו מדביקותם באלקים חיים מקור חיותם ו­להפילם חללים ר\"ל — \"חלל. . בשדה\", או עכ\"פ להחליש בהם את הענין ד­\"ואתם הדבקים בה\"א גו'\".\nוע\"ז באה הוראת התורה — \"ויצאו זקניך ושופטיך גו'\", שזהו מתפקידם ואחריותם של זקני ושופטי ישראל ב­כלל, כולל ב\"ד הגדול שבירושלים, לע­שות את כל התלוי בהם לתקן המצב ולשלול מכל וכל את המציאות ד\"חלל. . בשדה\"<sup data-n=\"1889\">18</sup>. וכמודגש גם בהכרזתם<sup data-n=\"1890\">19</sup> \"ידינו לא שפכו את הדם הזה\" — \"לא<sup data-n=\"1891\">20</sup> ראינוהו ופטרונוהו בלא מזונות ובלא לוי'\", דהיינו, שזוהי חובתם של זקני העיר ללות כל איש מישראל היוצא מה­עיר (אל השדה) ולהספיק לו צידה ל­דרך — מזון, זו תורה שנק' מזון<sup data-n=\"1892\">21</sup>, וכן לבושים — מצות [כדאיתא בתנא דבי אליהו רבה<sup data-n=\"1893\">22</sup> עה\"פ<sup data-n=\"1894\">23</sup> \"כי תראה ערום וכסיתו\" — \"אם ראית אדם שאין בו ד\"ת הכניסהו לביתך ולמדהו ק\"ש ותפלה כו' וזרזהו במצות לפי שאין לך ערום בי­שראל אלא מי שאין בו תורה ומצות\"], כדי לחזקו ולהגין עליו מכל הסכנות ה­אורבות לו בהיותו \"בשדה\".\nועפ\"ז יש לבאר הטעם (הפנימי) לזה, שבשעה שפירש יוסף מיעקב היו עוס­קים בפרשת עגלה ערופה דוקא:\nלפני ירידתו<sup data-n=\"1895\">24</sup> של יוסף למצרים,",[["1884","13","מו\"נ ח\"ג פ\"מ, הובא ברמב\"ן ובחיי פ' שופטים שם. וראה גם אברבנאל שם. חינוך מצוה תקל. — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241126\" data-slug=\"likkutei-sichot\" data-id=\"1300241126\">לקו\"ש חכ\"ד ע' 126</a> ובהערה 55 שם."],["1885","14","פ' ראה יג, יב. פ' שופטים יז, יג. יט, כ. ועוד. וראה בעניננו — בחיי פ' שופטים כא, א (\"ויש שפירש\")."],["1886","15","ואתחנן ד, ד."],["1887","16","ראה בחיי שם \"חלל. . מלשון חולין שחללו רוח הטומאה מחוץ לעיר בשדה זהו שאמר נופל בשדה\"."],["1888","17","תולדות כה, כז. וראה בארוכה אוה\"ת עה\"פ (קמב, ב ואילך). ד\"ה ואם בשדה במאמרי אדה\"ז — תקס\"ב (ח\"א ע' סו ואילך), אוה\"ת ח\"ש (הוספות לכרך ב — תמח, ב ואילך). ועוד."],["1889","18","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241130\" data-slug=\"likkutei-sichot\" data-id=\"1300241130\">לקו\"ש שם ע' 130</a> ואילך."],["1890","19","שופטים שם, ז."],["1891","20","רש\"י שם. וראה סוטה מה, סע\"ב במשנה (ועל הגליון שם). ספרי עה\"פ."],["1892","21","כמ\"ש ותורתך בתוך מעי (תהלים מ, ט. <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>). וראה חגיגה יד, א. תדבא\"ר שבהערה הבאה. ועוד."],["1893","22","פכ\"ז. — וראה רש\"י בראשית ג, ז (מב\"ר פי\"ט, ו). ועוד."],["1894","23","ישעי' נח, ז."],["1895","24","כי כלפי שמיא גליא שפרידתו מיעקב אז ה\"ז תחלת ירידתו למצרים. ואע\"פ דיעקב לא ידע זה, מזלי' חזי וכיו\"ב. וראה רש\"י וישב (לז, יד): מעצה עמוקה של אותו צדיק כו'.\nולהעיר מהמבואר במפרשים (ראה הנסמן בהערה 10), דמש\"נ (וישב שם) \"וישלחהו גו'\" היינו שיעקב ליווה את יוסף, ולכן עסקו אז בפרשת עגלה ערופה שתוכנה \"לא פטרנוהו כו' ובלא לוי'\". ע\"ש."]]],[1301410288,"\"ערות הארץ\"<sup data-n=\"1896\">25</sup>, שהי' שם באופן של \"נשבה לבין הגוים\"<sup data-n=\"1897\">26</sup> — הרי בזמן ההוא הי' צריך להוספת כח רוחני כדי לעמוד שם בצדקו — וזהו שלמד אתו יעקב פרשת עגלה ערופה, שבה מוזהרים זקני העיר על תפקידם להתעסק בלויית ה­איש ההולך ל\"שדה\" ולתת לו את כל צרכיו כל זמן היותו בשדה, כנ\"ל — שזוהי הנתינת כח ליוסף לעמוד בצדקו גם במצרים.\nולכן, כאשר רצה יוסף להוכיח ל­יעקב שהוא חי (גם) במובן הרוחני, מסר ע\"י אחיו \"סימן\" זה ליעקב, ש\"פרשת עגלה ערופה\" היתה לנגד עיניו, ובכח זה לא הושפע כלל מהסביבה במצרים ונשאר שלם בתורתו וצדקתו; וכאשר ראה יעקב \"את העגלות גו' — ותחי רוח יעקב אביהם\", שנמשכה חיות חדשה ברוחניותו (רוח) של יעקב, ובפרט ש­חיים (הרוחניים) של יעקב תלוי' בחייהם של זרעו<sup data-n=\"1898\">27</sup>, כמאמר<sup data-n=\"1899\">28</sup> \"מה זרעו בחיים אף הוא בחיים\".\nג. אמנם עדיין צריך להבין: במדרש שם מפרש דברי יעקב \"רב עוד יוסף בני חי\" — \"רב כחו של יוסף בני. . הוא עומד בצדקו הרבה ממני שחטאתי ש­אמרתי<sup data-n=\"1900\">29</sup> נסתרה דרכי מה'\" [כמבואר ב­מדרש<sup data-n=\"1901\">30</sup> בדברי יעקב לבניו<sup data-n=\"1902\">31</sup> \"למה הר­עותם לי להגיד לאיש העוד לכם אח\" — \"כך אמר הקב\"ה, אני עוסק להמליך את בנו במצרים והוא אומר למה הרעותם לי. . נסתרה דרכי מה'\"] — דלכאורה, ל­מאי נפק\"מ כאן, שיוסף \"עומד בצדקו הרבה ממני\"?\nגם צריך ביאור: ע\"פ מנהג ישראל — ש\"תורה הוא\" — מסיימים ל\"שלישי\" (ולכמה מנהגים<sup data-n=\"1903\">32</sup> — ל\"רביעי\") של קרי­את הפרשה בפסוק \"וידברו גו' וירא את העגלות גו' ותחי רוח יעקב אביהם\", ובפסוק שלאח\"ז — \"ויאמר ישראל רב עוד יוסף בני חי גו'\" — מתחיל ל\"רביעי\" (או ל\"חמישי\"). ואינו מובן — מדוע מפסיקים באמצע ענין?\nוהוא הדבר בתחילת \"שלישי\", ה­מתחיל באמצע דברי יוסף אל השבטים \"ועתה<sup data-n=\"1904\">33</sup> לא אתם שלחתם אותי הנה כי האלקים וישימני לאב לפרעה ולאדון לכל ביתו ומושל בכל ארץ מצרים\" — דלכאורה ה\"ז המשך מודגש לפסוקים שלפנ\"ז<sup data-n=\"1905\">34</sup> (שיוסף אמר לאחיו) \"אני יוסף גו' ועתה אל תעצבו ואל יחר בעיניכם כי מכרתם אותי הנה כי למחי' שלחני אלקים לפניכם, כי זה שנתיים הרעב גו' וישלחני אלקים לפניכם לשום לכם שארית בארץ ולהחיות לכם לפליטה גדולה\" (ובזה מסתיים \"שני\", ובפסוק שלאח\"ז מתחיל \"ועתה לא אתם שלחתם גו'\") — שמפסיקים באמצע דברי יוסף לאחיו העוסקים בתוכן אחד (שירידתו למצרים היתה בשליחות השם)?\nגם אינו מובן: הדגשת השלילה —",[["1896","25","מקץ מב, ט. שם, יב. וראה קה\"ר עה\"פ (א, ד) והארץ לעולם עומדת."],["1897","26","ל' רש\"י ויחי מז, לא (וראה רש\"י מקץ מג, ל) — ומסיים \"וה\"ה עומד בצדקו\"."],["1898","27","ובפרט של יוסף — ראה זהר ויחי רטז, ב. ביאוה\"ז שם (כז, סע\"ב ואילך. ולהצ\"צ — ס\"ע רנח ואילך). אוה\"ת ויחי ד\"ה בן פורת וביאורו. ועוד."],["1899","28","תענית ה, ב."],["1900","29","ישעי' מ, כז."],["1901","30","ב\"ר פצ\"א, י."],["1902","31","מקץ מג, ו."],["1903","32","שסוף \"שלישי\" הוא לעיל בפסוק (מה, יח) וקחו גו' ואכלו את חלב הארץ."],["1904","33","מה, ח."],["1905","34","מה, ד­ז. וכאמרו \"ועתה\" בוא\"ו המוסיף ומחבר."]]],[1301410289,"\"לא אתם שלחתם אותי הנה כי האלקים\" — שייכת יותר לעיל, בתור טעם ל­אמירת יוסף לאחיו \"אל תעצבו ואל יחר בעיניכם כי מכרתם אותי הנה\", מפני ש­\"לא אתם שלחתם אותי הנה כי האלקים\" — ומדוע נאמרה הדגשה זו דוקא אח\"כ (לאחר הפסקת \"שלישי\") בהמשך אחד עם \"וישימני לאב לפרעה ולאדון לכל ביתו ומושל בכל ארץ מצרים\"?\nד. ויש לומר הביאור בכל זה:\nהטעם לזה שיוסף הוא הראשון מבני ישראל שירד מצרימה — וזה הי' סיבה והתחלה<sup data-n=\"1906\">35</sup> לירידת כל ישראל למצרים — הוא מפני שהירידה למצרים שייכת לחידוש המיוחד שבעבודת יוסף:\nמבואר בכ\"מ<sup data-n=\"1907\">36</sup> הטעם שהאבות וה­שבטים בחרו להיות רועי צאן, כי הת­עסקות זו — שאין בה טירדא (יתירה) ונמצאים במצב של התבודדות מעניני העולם — לא הפריעה אותם מלהיות במצב של דביקות תמידית באלקות; אבל יוסף שונה בעבודתו מהאבות ושאר השבטים, שגם בהיותו עסוק בעניני העולם, הן בבית פוטיפר כאשר הפקידו \"על ביתו וכל יש לו נתן בידו\"<sup data-n=\"1908\">37</sup>, ועד\"ז בבית הסוהר, שנתן בידו \"את כל ה­אסירים. . ואת כל אשר עושים שם הוא הי' עושה\"<sup data-n=\"1909\">38</sup>, וכ\"ש כשנעשה משנה למלך וניהל כל עניני מצרים (\"ועל פיך ישק כל עמי. . ובלעדיך לא ירים איש גו'\"<sup data-n=\"1910\">39</sup>) — כל הטירדות העצומות הללו לא בלבלו אותו ולא הטרידוהו והי' בתכלית הדביקות באלקות.\nובזה יובן הטעם (הפנימי) שהתחלת ירידת בנ\"י למצרים היתה על ידי ירי­דתו של יוסף, כי יוסף (בעבודתו שם) הוא שנתן כח בבני ישראל<sup data-n=\"1911\">40</sup> להחזיק מעמד גם בהיותם בגלות, בארץ לא ל­הם, במצרים.\nוזו היתה כוונת יוסף באמרו לאחיו — \"למחי' שלחני אלקים לפניכם. . וישלחני אלקים לפניכם לשום לכם שארית ב­ארץ\", שירידתו למצרים היתה שליחות מאת הקב\"ה, כדי \"לפתוח את הצינור\" ולתת כח לבני ישראל שיוכלו להחזיק מעמד בגלות, לחיות בחיים רוחניים, \"ו­אתם הדבקים בה\"א חיים\", גם במצרים.\nובזה יובן ג\"כ דיוק לשונו של יוסף \"למחי' שלחני אלקים. . וישלחני אלקים. . ועתה לא אתם שלחתם אותי הנה כי האלקים\"<sup data-n=\"1912\">41</sup> — שם אלקים דוקא, מדת הדין והגבורה (ולא שם הוי', מדת הרחמים) — כי שליחות זו היא באופן של ירידה לגלות, מקום של העלם והסתר כו' [ובאופן שגרם צער ועגמת נפש ליוסף וליעקב וכו'] שלא ניכרין בו רחמיו של הקב\"ה באופן גלוי — וגם במצב זה, פעל יוסף שירידתו שם תהי' \"למחי'. . להחיות לכם לפליטה גדולה\".\nה. אמנם ענין זה עדיין אינו תכלית שליחותו של יוסף למצרים — שהרי אין זו אלא תועלת ופעולה שלילית — הגנה",[["1906","35","ראה רש\"י וישב לז, ב: סיבה ראשונה כו'. רש\"י שם, יד: מעצה עמוקה כו'. ועוד."],["1907","36","ראה מאמרי אדה\"ז — הקצרים ע' יט; תקס\"ה (ח\"א) ע' קצב ואילך. תו\"ח ויחי (קב, ב ואילך). ד\"ה ולא זכר תרע\"ז, תפר\"ח. ועוד."],["1908","37","וישב לט, ד. וראה שם, ה­ו. ח. ובת\"א (ועד\"ז בתיב\"ע) שם, יא: למבדק בכתבי חושבני'."],["1909","38","וישב שם, כב."],["1910","39","מקץ מא, מ. שם, מד."],["1911","40","ראה בארוכה בזה — תקס\"ה שם (ע' קצה ואילך). תו\"ח שם (קה, ב ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251253\" data-slug=\"likkutei-sichot\" data-id=\"1300251253\">לקו\"ש חכ\"ה ע' 253</a> ואילך."],["1912","41","וראה גם ויחי (נ, כ) \"אלקים חשבה לטובה. . להחיות עם רב\"."]]],[1301410290,"מהענינים הבלתי­רצויים שבגלות, כדי שהאדם ישאר דבוק באלקים (כמקודם) גם במצב זה —\nעיקר חידושו של יוסף הוא — כשמו — יוסף מלשון הוספה<sup data-n=\"1913\">42</sup>, וכהפירוש<sup data-n=\"1914\">43</sup> ב­פסוק<sup data-n=\"1915\">44</sup> \"יוסף ה' לי בן אחר\", שענינו של יוסף הוא, שמהפך גם את \"אחר\" (היינו מי שאינו שייך לצד הקדושה), שיהי' \"בן\" להקב\"ה. כלומר, לא רק שאינו מת­פעל מהמניעות ועיכובים שבגלות, אלא אדרבה, שהוא שולט עליהם עד שכוב­שם תחת ממשלת הקדושה.\n[וע\"ד דברי הרמב\"ם בנוגע למלך המשיח, שתפקידו הוא לא רק \"להחזיר מלכות דוד ליושנה. . (כדי שיהיו) חוזרין כל המשפטים בימיו כשהיו מקודם\"<sup data-n=\"1916\">45</sup> עבור בני ישראל (ע\"י שיבנה מקדש במקומו), דהיינו שבני ישראל יעבדו את השם בתכלית השלימות, אלא גם \"יתקן<sup data-n=\"1917\">46</sup> את העולם כולו לעבוד את ה' ביחד שנאמר<sup data-n=\"1918\">47</sup> כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' וגו'\"].\nוכפי שהי' בפועל ביוסף במצרים, שהי' משנה למלך, ד\"בלעדיך לא ירים איש את ידו ואת רגלו בכל ארץ מצ­רים\"<sup data-n=\"1919\">48</sup>, ויוסף שלט עליהם בפועל, \"ו­יוסף הוא השליט על הארץ\"<sup data-n=\"1920\">49</sup> [וכמסופר בארוכה בסוף פרשתנו<sup data-n=\"1921\">50</sup> שיוסף קנה המצרים ואת אדמתם, ועוד העבירם מק­צה גבול מצרים ועד קצהו וכו'], וכוונת יוסף היתה לא רק לשליטה גשמית, אלא<sup data-n=\"1922\">51</sup> שיכירו את אלקי השמים ואלקי הארץ, ויקיימו שבע מצות ב\"נ<sup data-n=\"1923\">52</sup>, ועד ש­ארז\"ל<sup data-n=\"1924\">53</sup> — והובא בפרש\"י על התורה<sup data-n=\"1925\">54</sup> — שהכריחם שימולו את עצמם<sup data-n=\"1926\">55</sup>.\nו. והנה ישנו הבדל יסודי בין שני ענינים אלו בשליחותו של יוסף למצרים — (א) נתינת כח בבני ישראל שעניני (מצרים) הגלות לא יפריעו אותם מדבי­קותם בה', (ב) השליטה על עניני הגלות — שיהיו נכנעים ועד שהם עצמם יהפכו לקדושה:\nהענין הראשון, התוקף שעניני הגלות לא יבלבלו את בני ישראל מדביקותם בה', אף שמקורה מיוסף, מ\"מ, על ידי יוסף נמשך כח זה בכל אחד ואחד מישראל באופן פנימי, עד שזה נקרא על שמו של כאו\"א.",[["1913","42","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151446\" data-slug=\"likkutei-sichot\" data-id=\"1300151446\">וע\"ד</a> החילוק בין מנשה ואפרים (בני יוסף), כמשנ\"ת במק\"א (לקו\"ש חט\"ו ע' 433 ואילך. ועוד), שמנשה ענינו לשלול שכחת \"בית אבי\", משא\"כ אפרים ענינו — \"הפרני אלקים בארץ עניי\" (מקץ מא, נב), ההוספה שע\"י אתהפכא חשוכא לנהורא. ע\"ש."],["1914","43","אוה\"ת עה\"פ. ועוד."],["1915","44","ויצא ל, כד."],["1916","45","ל' הרמב\"ם הל' מלכים רפי\"א."],["1917","46","רמב\"ם שם בסוף הפרק."],["1918","47","צפני' ג, ט."],["1919","48","מקץ מא, מד."],["1920","49","מקץ מב, ו."],["1921","50","מז, כ ואילך."],["1922","51","ראה תו\"ח שם (קה, ד ואילך. וראה שם: להחיות עם רב (ויחי נ, כ) דעכו\"ם. . עם רב ניצו­צות דבחי' התוהו. . לעבדו שכם אחד. ע\"ש ב­ארוכה)."],["1923","52","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051171\" data-slug=\"likkutei-sichot\" data-id=\"1300051171\">ע\"ד</a> שנצטוו כל בנ\"י לכוף כל באי עולם בזה — במ\"ת (רמב\"ם הל' מלכים ספ\"ח). ואולי י\"ל שזהו בכלל דינים ו\"לשבת יצרה\" — שגם ב\"נ מחוייבים בזה (ראה תוד\"ה לא תוהו — גיטין מא, ב (בתי' הב') לענין עבד. וראה לקו\"ש ח\"ה ע' 159 הערה 63. וש\"נ)."],["1924","53","ב\"ר ס\"פ צ. פצ\"א, ה. תנחומא מקץ ז."],["1925","54","מקץ מא, נה."],["1926","55","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101139\" data-slug=\"likkutei-sichot\" data-id=\"1300101139\">לקו\"ש ח\"י ע' 139</a> ובהערות שם, שי\"ל שהי' חייב למולם מפני שהיו כמקנת כספו. ע\"ש."]]],[1301410291,"וזהו הפירוש הפנימי במחז\"ל<sup data-n=\"1927\">56</sup> \"כל ישראל נקראים על שם יוסף לפי שהוא פירנסם וכלכלם בימי הרעב\": כלכלת יוסף את אחיו בימי הרעב כולל<sup data-n=\"1928\">57</sup> שיוסף נתן כח לכאו\"א מישראל, שגם בימי \"רעב\" רוחני — מצב של גלות והעלם והסתר — יוכלו לחיות חיים רוחניים כ­דבעי, וכח זה המשיך יוסף בבנ\"י באופן של מזון, שנעשה דם ובשר כבשרו, היינו שנתעצם בהם להיות ענין שלהם. שלכן \"כל ישראל נקראים על שם יוסף\", כיון שתכונה זו של יוסף נעשית חלק ממצי­אותם הם.\nאבל הענין השני, השליטה על מצ­רים, שייך רק לדרגת יוסף עצמו, וכמו בפשטות שרק הוא השליט על מצרים; ומה שבנ\"י יכולים לשלוט על עניני ה­גלות (בדוגמת יוסף), אינו דבר המתייחס אליהם אלא ליוסף, ובפשטות — שכח שליטתם על עניני הגלות הוא רק בתור שלוחיו של יוסף<sup data-n=\"1929\">58</sup>.\nז. ועפ\"ז מובנים הדיוקים דלעיל (סעיף ג) בלשונות הכתובים וחלוקת חלק \"שלישי\" של הפרשה:\nב' האופנים הנ\"ל בשליחותו של יוסף במצרים, הם הם שני הענינים שאמר יוסף לאחיו בתיאור שליחותו ששלחו \"אלקים\" למצרים: (א) \"למחי' (להיות לכם למחי'<sup data-n=\"1930\">59</sup>) שלחני אלקים לפניכם. . לשום לכם שארית בארץ ולהחיות לכם לפליטה גדולה\" — יוסף פעל בבני ישראל ונתן להם הכח להחזיק מעמד בגלות. (ב) \"ועתה לא אתם שלחתם אותי הנה כי האלקים וישימני לאב לפרעה ולאדון לכל ביתו ומושל בכל ארץ מצרים\" — פעולת שליחותו שיהי' הוא, יוסף, המושל והשליט על מצרים.\n[וגם שליחות זו (השני') שייכת לשם אלקים דוקא — כי הממשלה והשליטה על האומות (ועניני גלות) שייכת לשם אלקים, ענין של דין ומשפט (שלכן נקראים דיינים בשם \"אלקים\"<sup data-n=\"1931\">60</sup>)].\nובזה יש לבאר ולהמתיק שרק בענין השני מדגיש השלילה \"לא אתם שלחתם אותי הנה\" — די\"ל שכוונת יוסף בזה היא, לא רק לשלול (כפי המשמעות ב­פשטות) שסיבת ירידתו למצרים לא היתה בגלל כוונתם של השבטים (במכי­רתו למצרים), אלא, ששליחותו למצרים (מצד תכליתו השני' הנ\"ל — \"וישימני גו' ומושל בכל ארץ מצרים\") אינה שייכת אליהם (\"לא אתם\") אלא רק לדרגתו ומעלתו המיוחדת, שהוא השליט על כל הארץ.\nוזהו הטעם שבקריאת התורה מפסי­קים שני הענינים לשתי \"עליות\" — כי הענין השני בשליחות יוסף, הוא נעלה (\"עלי'\") לגבי הענין הראשון, שדוקא בו נעשית ההוספה<sup data-n=\"1932\">61</sup> (\"יוסף ה' לי בן אחר\").\nועד\"ז הוא בסיום \"שלישי\", בנוגע ליעקב:\nהענין הראשון — \"וירא את העגלות",[["1927","56","ל' רש\"י תהלים פ, ב."],["1928","57","ראה הנסמן בהערה 40."],["1929","58","בסגנון אחר: ענין הראשון הוא רק ענין של גילוי ההעלם, שיוסף מגלה תוקף הנשמה שישנו (אבל) בהעלם בכאו\"א מישראל; משא\"כ ענין השני הו\"ע של חידוש, שיוסף פועל חידוש בבנ\"י שלא ישנו בהם מצ\"ע."],["1930","59","רש\"י עה\"פ."],["1931","60","משפטים כא, ו. ועוד."],["1932","61","וי\"ל שעי\"ז מתגלה שרש שם אלקים, שהוא למעלה משם הוי' — כי הוא למעלה מגדר גילוי (הוי') [שלכן נמשך למטה בענין של העלם והסתר דוקא] — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380932\" data-slug=\"likkutei-torah\" data-id=\"4001380932\">לקו\"ת נצבים נג, סע\"ב</a> ואילך. המשך תרס\"ו (ע' צא. ע' תמ). ועוד."]]],[1301410292,"אשר שלח יוסף\" הראה ליעקב שיוסף עומד בצדקו גם במצרים — \"ותחי רוח יעקב\" (כנ\"ל).\nאבל אין זה ענין של חידוש (כ\"כ) בנוגע ליעקב — שהרי גם אצלו מצינו דוגמתו (עכ\"פ מעין זה), שהי' כ' שנה בבית לבן הארמי (שלא מצינו כזאת אצל אברהם ויצחק), ועבד שם בכל כחו<sup data-n=\"1933\">62</sup> — ומ\"מ הי' \"שלם בתורתו\"<sup data-n=\"1934\">63</sup>, \"עם לבן הרשע גרתי ותרי\"ג מצות שמרתי ולא למדתי ממעשיו הרעים\"<sup data-n=\"1935\">64</sup>.\nמשא\"כ הענין השני הנ\"ל, שיוסף נעשה השליט על כל מצרים — זהו חי­דוש גם לגבי יעקב<sup data-n=\"1936\">65</sup>. ולכן, לאחרי ש­\"ותחי רוח יעקב\" הוסיף ואמר \"רב עוד יוסף בני חי\", שכחו של יוסף הוא \"רב\" ו\"הרבה ממני\"<sup data-n=\"1937\">66</sup> [ולכן בא ענין זה ב­\"עלי'\" אחרת, ע\"ד הנ\"ל בתחילת \"שלי­שי\"].\nח. ומזה יש ללמוד הוראה מיוחדת לדורנו זה — שנשיא הדור, כ\"ק מו\"ח אדמו\"ר, שמו (הראשון) \"יוסף\":\nכ\"ק מו\"ח אדמו\"ר — \"יוסף\" שבדורנו — פתח וסלל את הדרך לכל תלמידיו ושלוחיו ההולכים בדרכיו ועל ידיהם בכל בנ\"י, שיוכלו לעסוק בהפצת התורה והיהדות, והפצת מעיינות החסידות, בכל מקום ומצב, גם ב\"מצרים\", חוצה שאין חוצה הימנו,\nובאופן, שלא זו בלבד שהיותם ב­מקום ה\"חוצה\" (מצרים) לא יגרע מדבי­קותם בה', אלא אדרבה — שפועלים ומשפיעים בכל \"ארץ מצרים\", \"לכוף את כל באי העולם לקבל מצוות שנצטוו בני נח. . מפני שצוה בהן הקב\"ה בתורה והודיענו ע\"י משה רבינו\" (כפסק דין ברור של הרמב\"ם<sup data-n=\"1938\">67</sup>).\nואף אם לפעמים נראה בתחילה ש­זוהי שליחות של \"אלקים\" — באופן של דין והעלם והסתר, ובפרט אם ישנם העלמות והסתרים כו' היכולים לגרום לצער ועגמת נפש כו', הרי על ידי \"יוסף\" מקבלים הכח, לגלות אלקות גם במקום השליחות, ועוד — להגיע (על ידי ירידה זו) לעילוי גדול ביותר<sup data-n=\"1939\">68</sup>, \"יוסף ה' לי בן אחר\", עד לעלי' והוספה שבאין ערוך.\nועל ידי שמוסיפים ביתר שאת ויתר עז בעבודתו של \"יוסף\" — הפצת התורה והיהדות והמעיינות חוצה, עד לחוצה ש­אין חוצה הימנו, מקרבים ומזרזים גאולה האמיתית והשלימה על ידי משיח צדקנו, שיבנה מקדש במקומו ויקבץ נדחי ישר­אל ויתקן את העולם כולו לעבוד את ה' ביחד<sup data-n=\"1940\">69</sup>, ובמהרה בימינו ממש.\n<span data-k=\"q\">(משיחת יום ג', ה' טבת, תשמ\"ז) </span>",[["1933","62","ויצא לא, ו."],["1934","63","רש\"י וישלח לג, יח. ב\"ר עה\"פ (פע\"ט, ה). שבת לג, סע\"ב."],["1935","64","רש\"י ר\"פ וישלח (לב, ה)."],["1936","65","ראה בארוכה (ע\"ד החסידות) במקומות ש­בהערה 27."],["1937","66","ע\"פ המבואר בפנים יומתק מה שאמר יעקב \"נסתרה דרכי מה'\" בנוגע לזה שהקב\"ה הי' \"עוסק להמליך את בנו במצרים\" — כי זהו ענין \"נסתר\" (ולמעלה) ממדריגת יעקב."],["1938","67","הל' מלכים ספ\"ח."],["1939","68","ראה בהערה 61."],["1940","69","רמב\"ם הל' מלכים ספי\"א."]]],[1301410293,"<h3>שיחה ג</h3>\nא. בפסוק<sup data-n=\"1941\">1</sup> \"ויאמר אנכי הא­ל אלקי אביך אל תירא מרדה מצרימה כי לגוי גדול אשימך שם\" מעתיק רש\"י התיבות \"אל תירא מרדה מצרימה\" ומפרש \"לפי שהי' מיצר על שנזקק לצאת לחוצה לארץ\".\nבפירושו זה מחדש רש\"י שני ענינים (לגבי פשטות משמעות הכתוב):\n(א) בכתוב נאמר \"אל תירא\", ורש\"י משנה וכותב \"לפי שהי' מיצר\" — והרי \"ירא\" ו\"מיצר\" הם שני הרגשים שונים (אף שיש בהם צד השווה).\n[וכדמצינו בכתוב לעיל<sup data-n=\"1942\">2</sup> \"ויירא יעקב מאד ויצר לו\", ובתרגום שם \"ודחיל. . ועקת\", כלומר: \"יראה\" היא רגש של דאגה<sup data-n=\"1943\">3</sup> ממאורע בעתיד שאפשר שיזיק לו; ו\"מיצר\" מורה על רגש של דוחק וצער ועגמת נפש<sup data-n=\"1944\">4</sup>, ומתאים גם בקשר לצרה ודאית שבהווה<sup data-n=\"1945\">5</sup> או שבעבר].\n(ב) בכתוב מפורש \"(אל תירא) מרדה מצרימה\", ואילו רש\"י משנה וכותב \"על שנזקק לצאת לחוצה לארץ\", היינו יראתו היתה (לא מהירידה למצרים, המפורשת בקרא, כ\"א) מהיציאה מן הארץ, ואין הפרש לאיזה מקום הוא יוצא, למצרים או לארץ אחרת.\nוי\"ל ששני השינויים תלויים זב\"ז: הירידה למצרים (לארץ חדשה בכלל, ובפרט למצרים, וכדלקמן סעיף ב) מ­עוררת היראה (ודאגה); והיציאה מא\"י (לחוצה לארץ) אינה מעוררת יראה, אלא צער (\"הי' מיצר\").\nאבל צ\"ע: מנ\"ל לרש\"י להוציא את הכתוב מפשוטו?\nב. מקורו של פרש\"י זה הוא (לכאו­רה) בפרקי דר\"א<sup data-n=\"1946\">6</sup>, וז\"ל: \"שמע יעקב על יוסף שהוא חי והי' מהרהר בלבו ואמר איך אעזוב ארץ אבותי ואת ארץ מולדתי ואת ארץ ששכינתו של הקב\"ה בתוכה ואלך אל ארץ בני חם<sup data-n=\"1947\">7</sup> בארץ שאין יראת שמים ביניהם\".\nותמוה מאד:\nהרי גם הפדר\"א (בפירושו ש(הוא גם) ע\"ד הדרש) לא הסתפק בחשש היציאה מהארץ לחוד — שהי' יעקב \"מהרהר כו' איך אעזוב ארץ אבותי כו'\" — אלא ממשיך שהרהר ודאג גם על מקום הלי­כתו \"ואלך אל ארץ בני חם בארץ שאין יראת שמים ביניהם\"<sup data-n=\"1948\">8</sup>, והיינו בהתאם",[["1941","1","פרשתנו מו, ג."],["1942","2","וישלח לב, ח."],["1943","3","ורש\"י רגיל להשתמש בלשון דואג דאגה בפירוש לשון \"תירא\" בכתוב — ראה לדוגמא: לך טו, א. וראה רש\"י ס\"פ עקב. וראה בס' השרשים ל­הרד\"ק מע' דאג."],["1944","4","ראה פרש\"י משפטים כג, כב. וראה שופטים ב, טו וברד\"ק שם."],["1945","5","וי\"ל שזהו גם תוכן פרש\"י וישלח שם: ויירא שמא יהרג ויצר לו אם יהרוג הוא את אחרים — דהיראה היא מההיזק שאפשר שיארע לו, \"שמא יהרג\"; משא\"כ בהחשש ד\"יהרוג הוא את אחרים\" העיקר הוא הצער שיצטרך להרוג כו'."],["1946","6","רפל\"ט. הובא גם ביל\"ש פרשתנו עה\"פ."],["1947","7","שהכוונה לארץ מצרים, וכמ\"ש (תהלים קה, כג — הובא בפרש\"י לך טו, יג (בסופו)) ויבא ישראל מצרים ויעקב גר בארץ חם."],["1948","8","בילקוט פרשתנו עה\"פ: ואלך לי אל ארץ טמאה<sup data-n=\"e50\">*</sup>, אל תוך ערלים בני חם<sup data-n=\"e51\">**</sup> שאין יראת שמים ביניהם. אבל (אפילו את\"ל ש\"אל ארץ טמאה\" ה­כוונה לחו\"ל בכלל<sup data-n=\"e52\">***</sup>. ודוחק — הרי) גם שם ממשיך \"אל. . בני חם שאין יראת שמים ביניהם\", שקאי על מצרים."],["e50","*","ועד\"ז הוא בפרקי דר\"א דפוס ונצי' שנת דש. ובפדר\"א הוצאת מקור (ירושלים, תשל\"ב) הביא עד\"ז מכת\"י פדר\"א."],["e51","**","כ\"ה ביל\"ש ע\"פ כת\"י (ירושלים, תשל\"ג). וכן הובא בילקוט ראובני כאן. וביל\"ש לפנינו ליתא \"בני חם\"."],["e52","***","אבל בפדר\"א הנ\"ל בשוה\"ג הא' הובאה גירסא שבו מפורש \"ארץ טמאה כארץ מצרים\"."]]],[1301410294,"למפורש בקרא שיעקב ירא \"מרדה מצרימה\";\nודוקא רש\"י, שלא בא לפרש אלא פשוטו של מקרא, לא הזכיר כלל מ­דאגתו לרדת מצרימה, כ\"א אך ורק ה­צער כו' על היציאה (מן הארץ) לחו\"ל!\n[ואין לתרץ דהחשש \"שאין יראת שמים ביניהם (בארץ מצרים)\" אינו ע\"פ פשוטו של מקרא — כי כבר מצינו לעיל דוגמתו בנוגע למצרים בפשש\"מ: על דברי פרעה לאברהם<sup data-n=\"1949\">9</sup> \"הנה אשתך קח ולך\" פירש\"י \"לא כאבימלך שאמר לו<sup data-n=\"1950\">10</sup> הנה ארצי לפניך אלא אמר לו לך ואל תעמוד שהמצרים שטופי זמה הם\"<sup data-n=\"1951\">11</sup>].\nזאת ועוד: לפי פרש\"י צ\"ע, איך מתיישב המשך הכתוב, שהקב\"ה הסיר את צערו של יעקב ע\"י שהבטיח לו \"כי לגוי גדול אשימך שם\":\nלפי' הפרקי דר\"א הנ\"ל שיעקב הי' ירא לירד למצרים מפני שאין יראת שמים ביניהם וחשש שלא יתערבו בניו בין המצרים<sup data-n=\"1952\">12</sup> וילמדו ממעשיהם כו'<sup data-n=\"1953\">13</sup>, מובן, שכאשר אמר לו הקב\"ה \"לגוי גדול אשימך שם\" נחה דעתו, כי בזה הבטיח לו שלא יתערבו ביניהם.\nאבל לפי פרש\"י, שיעקב הי' מיצר על שנזקק לצאת לחו\"ל — אינו מובן: איך הופג צערו זה של יעקב ע\"י ה­הבטחה \"כי לגוי גדול גו'\", שאינה שוללת לכאורה סיבת צערו?\nג. לכאורה יש לבאר, דהטעם לכך שרש\"י אינו מפרש שיראתו של יעקב לרדת מצרימה היתה מחמת העדר יראת שמים ביניהם כו' — הוא:\nכשאמר יוסף לאחיו<sup data-n=\"1954\">14</sup>: \"מהרו ועלו אל אבי ואמרתם אליו גו' רדה אלי גו' והיית קרוב אלי אתה ובניך ובני בניך גו' כי עוד חמש שנים רעב\", הודיע ל­יעקב שיקבע עבורו מקום מיוחד ב­מצרים לגור שם — \"וישבת בארץ גושן גו' וכלכלתי אותך שם\". דפשטות ה­משמעות<sup data-n=\"1955\">15</sup> שיהי' להם מקום לגור בפני עצמם<sup data-n=\"1956\">16</sup>.\n[וכפי שהי' בפועל — ע\"פ פשוטו ש\"מ<sup data-n=\"1957\">17</sup> \"והפליתי ביום ההוא את ארץ גושן אשר עמי עומד עלי'\", \"בארץ גושן אשר שם בני ישראל\"<sup data-n=\"1958\">18</sup>, היינו שגרו",[["1949","9","לך יב, יט."],["1950","10","וירא כ, טו."],["1951","11","אף שגם בנוגע ל(אבימלך ו)פלשתים נאמר אין יראת אלקים במקום הזה (וירא כ, יא). ולהעיר מרד\"ל לפדר\"א שם אות ד."],["1952","12","ראה זח\"א רכב, א: בשעתא דהוה נחית יעקב למצרים הוה דחיל הוה אמר דלמא ח\"ו ישתצון בני ביני עממיא. ועד\"ז בזח\"ב נג, א."],["1953","13","להעיר גם מספורנו עה\"פ כאן."],["1954","14","פרשתנו מה, ט­יא."],["1955","15","וכדברי פרעה \"ואתנה לכם את טוב ארץ מצרים\" — ארץ גושן (שם, יח ובפרש\"י)."],["1956","16","אף שכשהיו מתי מספר (וישלח לד, ל) הי' מעלה בשבילם \"ואתנו תשבו\" (שם לד, י)."],["1957","17","וארא ח, יח."],["1958","18","שם ט, כו."]]],[1301410295,"אפילו בארץ מיוחדת, ולא היו מעורבים עם המצרים<sup data-n=\"1959\">19</sup>].\nולכן מובן בפשטות שאין מקום לירא מהנהגת המצרים, מאחר שלא יגורו עמם יחדיו כי אם בארץ שלהם, ארץ גושן.\nאבל דוחק גדול לומר שזה מכריח להוציא את הכתוב מידי פשוטו (ולפרש דמש\"נ \"אל תירא מרדה מצרימה\" אין הכוונה לדאגה על הירידה למצרים כ\"א שהי' מיצר על היציאה מא\"י לחו\"ל),\nכי הגם שאין לדמות מצבם של יעקב ובניו — שבעים נפש ויותר — במצרים למצבם של אברהם ושרה בירידתן ל­מצרים (עד שהוצרך פרעה לשלחם מ­שם), מאחר שיעקב ובניו ישבו בארץ גושן — מכל מקום, מובן בפשטות, שה­ירידה לארץ מצרים, שאנשי' מפורסמים בהנהגתם הגרועה ביותר היפך בתכלית מיראת שמים<sup data-n=\"1960\">20</sup> [הן בג\"ע, שטופי זמה כנ\"ל, והן בע\"ז \"בעירא. . דחלין לי'\"<sup data-n=\"1961\">21</sup> ועוד], יש בה לעורר דאגתו ויראתו של יעקב.\nואעפ\"כ מוציא רש\"י את הכתוב מ­פשוטו, ומפרש שיעקב הי' מיצר על היציאה מא\"י לחו\"ל!\nד. כמה ממפרשי המקרא<sup data-n=\"1962\">22</sup> ביארו ש­\"הי'<sup data-n=\"1963\">23</sup> יעקב מתיירא ואומר עכשיו שאני יורד למצרים קרבו הימים שנאמר לזקני גזירת שעבוד ועינוי על זרעי בארץ לא להם\", וכמ\"ש בתיב\"ע<sup data-n=\"1964\">24</sup> \"לא תדחל מל­מיחות למצרים על עיסק שעבודא די פסקית עם אברהם\". והיינו שהיראה היתה על התחלת קיום גזירת \"ועבדום וענו אותם\"<sup data-n=\"1965\">25</sup> בישראל.\nולכאורה, גם פירוש זה מתאים יותר לדרך הפשט — מפירושו של רש\"י, כי לפי פירש\"י חששו של יעקב הי' רק ענין פרטי, הנוגע לו בלבד (על שנזקק לצאת לחו\"ל); משא\"כ לפי פירוש זה הי' כאן חשש כללי, בשייכות לעם ישראל (זרע יעקב) בכללותו.\n[וגם המשך הכתוב \"כי לגוי גדול אשימך שם\" מתיישב יותר לפי פירוש זה, כמ\"ש החזקוני \"אמר לו הקב\"ה אל תירא מרדה מצרימה אם לאביך הזהרתי באתי לך להבטיחך אם קרבו ימי שעבוד ועינוי גם קרבה הברכה שברכתי את זקנך ואעשך לגוי גדול<sup data-n=\"1966\">26</sup> היינו כי לגוי גדול אשימך שם\", כלומר: ההבטחה \"לגוי גדול אשימך שם\" יש לה קשר ושייכות לקיום ברית בין הבתרים].\nמדוע א\"כ לא פרש\"י שיעקב ירא מקיום גזירת בין הבתרים? והרי לפי פרש\"י לעיל עה\"פ<sup data-n=\"1967\">27</sup> \"ותחי רוח יעקב\" — \"שרתה עליו שכינה שפירשה ממנו\", מסתבר לומר, שיעקב ידע שהירידה ל­",[["1959","19","ולהעיר מפרש\"י פרשתנו מז, כא."],["1960","20","ראה פרש\"י אחרי (יח, ג) מגיד שמעשיהם של מצרים כו'<sup data-n=\"e53\">*</sup> מקולקלים מכל האומות ואותו מקום שישבו בו ישראל מקולקל מן הכל."],["1961","21","ת\"א מקץ מג, לב צוין בפרש\"י שם. וראה פרשתנו מו, לד ובפרש\"י. ועוד."],["1962","22","ראה רמב\"ן פרשתנו מו, א­ב. חזקוני (הובא בצידה לדרך) כאן. אוה\"ח. וראה גם מדרש שכל טוב כאן. ועוד."],["1963","23","ל' החזקוני."],["1964","24","עה\"פ. ולהעיר מזהר שבהערה 12."],["1965","25","לך טו, יג."],["1966","26","ר\"פ לך."],["1967","27","פרשתנו מה, כז."],["e53","*","דמש\"כ רש\"י שם \"ושל כנעניים\" י\"ל שאין הכוונה לכנענים שבימי האבות כ\"א כנענים שבזמן ביאתם לארץ, כהמשך הכתוב כמעשה ארץ כנען אשר אני מביא אתכם שמה. וכמ\"ש רש\"י בד\"ה שלאח\"ז."]]],[1301410296,"מצרים היא התחלת קיומה של גזירת בין הבתרים.\n[לכאורה הי' אפ\"ל שפירוש זה קשה לאומרו, לפשש\"מ, בלשון \"אל תירא\", מאחר שאין זה משנה את הידוע לו שזהו קיום גזירת הקב\"ה. אבל אין זה תירוץ מספיק, שהרי רש\"י הי' יכול לפרש (כמו שהוא מפרש בלאה\"כ, כנ\"ל) שיעקב הי' מיצר ע\"ז שמעתה מתחיל זמן של \"ועבדום וענו אותם\". וכמובן, דגם כאשר יודעים שהגזירה היא רצונו של הקב\"ה, בכ\"ז ה\"ז ענין המעורר צער].\nה. וי\"ל הביאור בזה:\nבפסוקים שלפנ\"ז מסופר כבר ע\"ד החלטתו של יעקב לרדת למצרים: \"ויאמר<sup data-n=\"1968\">28</sup> ישראל רב עוד יוסף בני חי אלכה ואראנו בטרם אמות\"; ועוד יותר — שכבר התחיל לרדת \"ויסע ישראל וכל אשר לו גו'\"<sup data-n=\"1969\">29</sup> — ומכיון שכן תמוה, מהו תוכנה של אמירה זו \"אל תירא מרדה גו'\", שמשמעה שיעקב הי' עדיין בספק ומפחד לירד למצרים<sup data-n=\"1970\">30</sup>? אמירה זו היתה מתאימה לפני החלטתו לירד למצרים<sup data-n=\"1971\">31</sup>, ועכ\"פ קודם שהתחיל לירד בפועל.\nולכן מפרש רש\"י ש\"אל תירא מרדה מצרימה\" אין פירושו שהי' ירא ומפחד להתחיל, אלא \"לפי שהי' מיצר על שנזקק לצאת כו'\", היינו שהי' מצטער על הפעולה שהי' עושה בפועל.\nאמנם אינו מובן:\nמדוע נתעכבה הבטחה זו ד\"אל תירא מרדה גו'\", שבאה להפיג צערו, עד לאחרי ש(נסע ממקומו, ו)הגיע לבאר שבע — ובמילא כל הזמן ההוא הי' יעקב בצער<sup data-n=\"1972\">32</sup>?\nועכצ\"ל שכאן (בבאר שבע) נתחדש איזה ענין, שבגללו הוצרך אז יעקב ל\"נחמתו\" של הקב\"ה בהבטחתו אל תירא גו'. ולכן מפרש רש\"י שהי' מיצר על שנזקק לצאת לחוצה לארץ, ולא על הירידה למצרים בפרט.\nוהביאור בזה:\nבאר שבע היא מקום הגבול<sup data-n=\"1973\">33</sup> — ה­עיר האחרונה בדרומה של א\"י, שממנה יוצאים לחו\"ל. ולכן אע\"פ שהליכתו מתחילה היתה ע\"מ לצאת מהארץ ולרדת למצרים, ונסיעתו זו היתה מתוך שמחה וכו', כמ\"ש<sup data-n=\"1974\">34</sup> \"ויאמר ישראל רב עוד",[["1968","28","מה, כח."],["1969","29","מו, א."],["1970","30","ראה אברבנאל כאן השאלה הי\"ז."],["1971","31","ברד\"ל (לפדר\"א שם אות א) דזה שהסכים כבר לילך מקודם שאמר אלכה ואראנו היינו שילך רק לראותו ולשוב לא\"י מיד, וכיון שנאמר לו אל תירא אז הוא שכתוב ויקם יעקב וגו' וישאו וגו' בעגלות וגו' ויקחו את מקניהם וגו'.\nאבל צ\"ע דהרי נאמר כבר לפנ\"ז \"ויסע ישראל וכל אשר לו ויבא בארה שבע גו'\". ודוחק גדול לומר שהכוונה ב\"וכל אשר לו\" היינו רק מה ששייך ליעקב ולא לכל משפחתו."],["1972","32","לכאורה י\"ל (ע\"ד מ\"ש הרמב\"ן שם. וראה מדרש לקח טוב שם. ועוד) שמאמר הא­ל בא אליו לאחר ש\"ויזבח זבחים לאלקי אביו יצחק\" (מו, א). אבל את\"ל שהקרבתו היתה בשביל שיתגלה אליו ה' הו\"ל לזבוח הזבחים לפני נסיעתו לבאר שבע. ולכ­אורה דוחק לומר בפשש\"מ, דהי' זה מחמת חשיבות העיר באר שבע אצל יעקב דשם נאמר ליצחק אל תירא ושם נתברך (תולדות כו, כג ואילך) — כי הו\"ל לרש\"י לפרש זה. וראה בהנסמן בהערה הבאה."],["1973","33","ראה יפה תואר (השלם) לב\"ר פס\"ח, ו (ה). וראה שם לב\"ר פרשתנו פצ\"ד, ד. מדרש הגדול פרשתנו (מו, א). — אבל בנזר הקודש (השלם) לב\"ר פרשתנו שם, שבאר שבע היא על גבול צפוני של א\"י ואינה על הדרך למצרים (וראה גם פי' מהרז\"ו שם). וצ\"ע. ואכ\"מ."],["1974","34","מה, כח. וראה פרש\"י עה\"פ."]]]]});
